/* Input.js */
// ====== src/core/Input.js ======
// 键盘 + 触摸输入管理
// 按键映射：
//   WASD / 方向键 = 移动
//   Space / KeyJ  = 开火（持续；同时默认自动开火）
//   KeyZ          = 炸弹 BOMB
//   KeyQ          = 一键清屏技能（清除全场敌弹 + AOE）
//   KeyX          = 一键投降技能（自动放弃本局）
//   Shift         = 低速精确模式
//   KeyV          = 僚机编队切换
//   Esc / KeyP    = 暂停

const Input = {
  keys: {},
  // 触摸：玩家手指位置（屏幕坐标）
  touchPos: null,
  touchActive: false,
  // 触发动作（瞬时，每帧消费后清空）
  actions: {
    bomb: false,             // Z 炸弹
    clearScreen: false,      // Q 一键清屏
    surrender: false,        // X 一键投降
    toggleFormation: false,  // V
    pause: false,            // Esc/P
  },
  // 持续状态
  state: {
    slow: false,             // 低速精确模式
    firing: true,            // 默认自动开火
  },
  // 移动方向（-1..1）
  moveX: 0,
  moveY: 0,

  _canvas: null,
  _touchSlow: false,
  _touchFire: false,
  // 相对拖动（虚拟摇杆）状态
  _touchId: null,          // 操控手指的 identifier（支持多点触控）
  _touchAnchor: null,      // 手指落下时的客户端坐标
  _touchPlane0: null,      // 手指落下时飞机的游戏坐标

  init(canvas) {
    this._canvas = canvas;

    // ===== 键盘 =====
    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      this.keys[e.code] = true;
      this._onKeyDown(e.code);
      // 阻止方向键/空格滚动
      if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) {
        e.preventDefault();
      }
    });
    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });

    // ===== 触摸：全屏相对拖动（虚拟摇杆）=====
    // 设计要点（移动端真机兼容）：
    // 1) 监听挂在 window（捕获阶段），canvas 在竖屏手机上下有黑边，
    //    只绑 canvas 会导致黑边区域触摸全部丢失；
    // 2) 手指落下点为"锚点"，飞机目标点 = 飞机初始位置 + 滑动 delta，
    //    手指永远不会盖住飞机（区别于"绝对跟随手指"）；
    // 3) identifier 锁定第一根有效手指，另一根手指可同时点 BOMB/SLOW；
    // 4) 仅在战斗中(state=play)且触摸点不在菜单/按钮上时接管，不挡 UI 点击。
    const toGameXY = (clientX, clientY) => {
      const rect = canvas.getBoundingClientRect();
      return {
        x: (clientX - rect.left) * (canvas.width / rect.width),
        y: (clientY - rect.top) * (canvas.height / rect.height),
      };
    };

    const isUiTouch = (target) => {
      return !!(target && target.closest &&
        (target.closest('#overlay') || target.closest('#touch-controls')));
    };

    const canControl = () => typeof Game !== 'undefined' && Game && Game.state === 'play';

    const findTouch = (list, id) => {
      for (let i = 0; i < list.length; i++) if (list[i].identifier === id) return list[i];
      return null;
    };

    window.addEventListener('touchstart', (e) => {
      if (this._touchId !== null || !canControl()) return;
      for (let i = 0; i < e.changedTouches.length; i++) {
        const t = e.changedTouches[i];
        if (isUiTouch(t.target)) continue;
        // 锁定该手指为操控指
        this._touchId = t.identifier;
        this._touchAnchor = { x: t.clientX, y: t.clientY };
        this._touchPlane0 = { x: Game.player.x, y: Game.player.y };
        this.touchActive = true;
        this.touchPos = { x: Game.player.x, y: Game.player.y };
        e.preventDefault();
        break;
      }
    }, { passive: false });

    window.addEventListener('touchmove', (e) => {
      if (this._touchId === null) return;
      // 离开战斗状态（暂停/死亡/结算）立即释放操控锁
      if (!canControl()) { this._releaseControl(); return; }
      const t = findTouch(e.touches, this._touchId);
      if (!t) return;
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const sx = canvas.width / rect.width;
      const sy = canvas.height / rect.height;
      const gx = this._touchPlane0.x + (t.clientX - this._touchAnchor.x) * sx;
      const gy = this._touchPlane0.y + (t.clientY - this._touchAnchor.y) * sy;
      this.touchPos = {
        x: Utils.clamp(gx, 0, Balance.width),
        y: Utils.clamp(gy, 0, Balance.height),
      };
    }, { passive: false });

    this._releaseControl = () => {
      this._touchId = null;
      this._touchAnchor = null;
      this._touchPlane0 = null;
      this.touchActive = false;
      this.touchPos = null;
    };
    const releaseTouch = (e) => {
      if (this._touchId === null) return;
      if (!findTouch(e.touches, this._touchId)) this._releaseControl();
    };
    window.addEventListener('touchend', releaseTouch, { passive: false });
    window.addEventListener('touchcancel', releaseTouch, { passive: false });

    // ===== 移动端按钮 =====
    const bombBtn = document.getElementById('bomb-btn');
    const slowBtn = document.getElementById('slow-btn');
    if (bombBtn) {
      bombBtn.addEventListener('touchstart', (e) => {
        e.preventDefault();
        this.actions.bomb = true;
      }, { passive: false });
    }
    if (slowBtn) {
      slowBtn.addEventListener('touchstart', (e) => {
        e.preventDefault();
        this._touchSlow = true;
      }, { passive: false });
      slowBtn.addEventListener('touchend', (e) => {
        e.preventDefault();
        this._touchSlow = false;
      }, { passive: false });
    }
  },

  _onKeyDown(code) {
    switch (code) {
      case 'Space':
        // Space = 开火（持续；自动开火默认已开启，此处仅标记，不在 actions 里）
        this.state.firing = true;
        break;
      case 'KeyJ':
        this.state.firing = true;
        break;
      case 'KeyZ':
        this.actions.bomb = true;
        break;
      case 'KeyQ':
        // 一键清屏技能
        this.actions.clearScreen = true;
        break;
      case 'KeyX':
        // 一键投降技能
        this.actions.surrender = true;
        break;
      case 'KeyV':
        this.actions.toggleFormation = true;
        break;
      case 'Escape':
      case 'KeyP':
        this.actions.pause = true;
        break;
    }
  },

  // 每帧调用：从按键状态计算 moveX/moveY 和 slow
  update() {
    // 持续状态：键盘 Shift 或 触屏 slow 按钮
    const kbSlow = !!(this.keys['ShiftLeft'] || this.keys['ShiftRight']);
    this.state.slow = kbSlow || !!this._touchSlow;

    // 开火持续状态：自动开火默认开启；按住 Space/J 也开火
    this.state.firing = true;

    // 键盘移动
    let mx = 0, my = 0;
    if (this.keys['ArrowLeft'] || this.keys['KeyA']) mx -= 1;
    if (this.keys['ArrowRight'] || this.keys['KeyD']) mx += 1;
    if (this.keys['ArrowUp'] || this.keys['KeyW']) my -= 1;
    if (this.keys['ArrowDown'] || this.keys['KeyS']) my += 1;

    if (mx !== 0 || my !== 0) {
      const len = Math.sqrt(mx * mx + my * my);
      this.moveX = mx / len;
      this.moveY = my / len;
    } else {
      this.moveX = 0;
      this.moveY = 0;
    }
  },

  // 每帧末清空瞬时动作（消费后）
  clearFrameActions() {
    this.actions.bomb = false;
    this.actions.clearScreen = false;
    this.actions.surrender = false;
    this.actions.toggleFormation = false;
    this.actions.pause = false;
  },
};

/* Entity.js */
// ====== src/entities/Entity.js ======
// 实体基类：所有游戏对象的基类

class Entity {
  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.radius = 10;       // 碰撞半径（判定用）
    this.alive = true;
    this.dead = false;      // 标记可回收
    this.age = 0;           // 存活时间（秒）
    this.rotation = 0;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.age += dt;
    this._onUpdate(dt);
  }

  // 子类覆盖
  _onUpdate(dt) {}

  draw(ctx) {
    this._onDraw(ctx);
  }
  _onDraw(ctx) {}

  // 出界检测
  offscreen(margin = 0) {
    return (
      this.x < -margin || this.x > Balance.width + margin ||
      this.y < -margin || this.y > Balance.height + margin
    );
  }

  // 距离判定
  distTo(other) {
    return Utils.dist(this.x, this.y, other.x, other.y);
  }

  // 与另一个实体圆碰撞
  hits(other, extra = 0) {
    return Utils.circleHit(this.x, this.y, this.radius + extra, other.x, other.y, other.radius);
  }
}

/* Projectile.js */
// ====== src/entities/Projectile.js ======
// 子弹：玩家弹 / 敌弹，使用对象池

// ===== 玩家子弹 =====
class PlayerBullet extends Entity {
  constructor() { super(); this.reset(); }
  reset() {
    this.kind = 'scatter';   // scatter / laser / homing
    this.level = 1;
    this.damage = 1;
    this.pierce = 0;          // 激光穿透剩余次数（-1=无限）
    this.target = null;       // homing 目标
    this.homingTimer = 0;
    this.color = Balance.color.playerBullet;
    this.active = false;
    this.radius = 4;
  }
  spawn(x, y, vx, vy, kind, level, damage = 1) {
    this.x = x; this.y = y;
    this.vx = vx; this.vy = vy;
    this.kind = kind; this.level = level; this.damage = damage;
    this.color = kind === 'laser' ? '#00f0ff' : kind === 'homing' ? '#9b5cff' : Balance.color.playerBullet;
    this.radius = kind === 'laser' ? 3 : 4;
    this.pierce = kind === 'laser' ? -1 : 0;
    this.homingTimer = 0;
    this.target = null;
    this.active = true;
    this.alive = true; this.dead = false;
    this.age = 0;
  }
  _onUpdate(dt) {
    // homing 每 0.2s 重新指向最近敌人
    if (this.kind === 'homing') {
      this.homingTimer -= dt;
      if (this.homingTimer <= 0 || !this.target || !this.target.alive) {
        this.target = Game.findNearestEnemy(this.x, this.y, 600);
        this.homingTimer = 0.2;
      }
      if (this.target) {
        const desiredVx = this.target.x - this.x;
        const desiredVy = this.target.y - this.y;
        const len = Math.sqrt(desiredVx*desiredVx + desiredVy*desiredVy) || 1;
        const speed = Balance.bullet.playerHoming;
        const tvx = desiredVx/len * speed;
        const tvy = desiredVy/len * speed;
        // 平滑转向（商店制导矩阵可提升灵敏度）
        const steer = PlayerBulletPool.homingAgile ? 0.32 : 0.15;
        this.vx = Utils.lerp(this.vx, tvx, steer);
        this.vy = Utils.lerp(this.vy, tvy, steer);
      }
    }
    // 出界
    if (this.y < -10 || this.y > Balance.height + 10 || this.x < -10 || this.x > Balance.width + 10) {
      this.active = false; this.dead = true;
    }
  }
  _onDraw(ctx) {
    ctx.save();
    if (this.kind === 'laser') {
      // 激光：长条 + 强辉光
      ctx.shadowBlur = 8;
      ctx.shadowColor = this.color;
      ctx.fillStyle = this.color;
      ctx.fillRect(this.x - 2, this.y - 14, 4, 28);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(this.x - 1, this.y - 14, 2, 28);
    } else if (this.kind === 'homing') {
      // 追踪弹：圆形 + 拖尾
      ctx.shadowBlur = 6;
      ctx.shadowColor = this.color;
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Utils.TAU);
      ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius * 0.4, 0, Utils.TAU);
      ctx.fill();
    } else {
      // 散射：圆+光
      ctx.shadowBlur = 6;
      ctx.shadowColor = this.color;
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Utils.TAU);
      ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius * 0.4, 0, Utils.TAU);
      ctx.fill();
    }
    ctx.restore();
  }
}

// 玩家子弹对象池
const PlayerBulletPool = {
  pool: [],
  homingAgile: false,   // 商店"制导矩阵"：追踪转向灵敏度
  init(size = 500) {
    this.pool = [];
    for (let i = 0; i < size; i++) this.pool.push(new PlayerBullet());
  },
  spawn(x, y, vx, vy, kind, level, damage) {
    let b = null;
    for (let i = 0; i < this.pool.length; i++) {
      if (!this.pool[i].active) { b = this.pool[i]; break; }
    }
    if (!b) { b = new PlayerBullet(); this.pool.push(b); }
    b.spawn(x, y, vx, vy, kind, level, damage);
    return b;
  },
  update(dt) {
    for (let i = 0; i < this.pool.length; i++) {
      const b = this.pool[i];
      if (!b.active) continue;
      b.update(dt);
      if (b.dead) { b.active = false; }
    }
  },
  draw(ctx) {
    for (let i = 0; i < this.pool.length; i++) {
      if (this.pool[i].active) this.pool[i].draw(ctx);
    }
  },
  forEachActive(fn) {
    for (let i = 0; i < this.pool.length; i++) {
      if (this.pool[i].active) fn(this.pool[i]);
    }
  },
  clear() {
    for (let i = 0; i < this.pool.length; i++) this.pool[i].active = false;
  },
};

// ===== 敌弹 =====
class EnemyBullet extends Entity {
  constructor() { super(); this.reset(); }
  reset() {
    this.bMode = 'straight'; // straight / accel / decel / curve / spiral / homing
    this.spinAngle = 0;     // 螺旋自旋角度（度/秒）
    this.curveAngle = 0;    // 曲线偏移
    this.curveAmount = 0;   // 度/秒
    this.life = 0;
    this.maxLife = 4;       // 自动消失（缩短，避免满屏乱线）
    this.color = Balance.color.enemyRed;
    this.radius = 5;
    this.active = false;
    this.bornSpeed = 0;     // 原速度
    this.accel = 0;          // 加速度（accel/decel）
    this.homingStrength = 0;
    this.target = null;
    this.split = false;      // 分裂标记
    this.splitTime = 0;
    this.splitCount = 0;
    this.ownerBoss = null;   // 用于分裂时记录来源
    this.bornAngle = 0;      // 出生角度（wave 模式基准）
    this.waveAmp = 0;        // 蛇形摆幅（度）
    this.waveFreq = 2;       // 蛇形频率（Hz）
  }
  spawn(x, y, vx, vy, opts = {}) {
    this.x = x; this.y = y; this.vx = vx; this.vy = vy;
    this.bMode = opts.mode || 'straight';
    this.color = opts.color || Balance.color.enemyRed;
    this.radius = opts.radius || 5;
    this.spinAngle = opts.spinAngle || 0;
    this.curveAmount = opts.curveAmount || 0;
    this.bornSpeed = Math.sqrt(vx*vx + vy*vy);
    this.accel = opts.accel || 0;
    this.life = 0;
    this.maxLife = opts.maxLife || 8;
    this.homingStrength = opts.homingStrength || 0;
    this.target = null;
    this.split = !!opts.split;
    this.splitTime = opts.splitTime || 0;
    this.splitCount = opts.splitCount || 3;
    this.ownerBoss = opts.ownerBoss || null;
    this.bornAngle = Utils.angleFromVec(vx, vy);
    this.waveAmp = opts.waveAmp || 0;
    this.waveFreq = opts.waveFreq || 2;
    this.active = true; this.alive = true; this.dead = false;
    this.age = 0;
    this.grazed = false;  // 擦弹标记，避免同一颗子弹多次擦弹
    this.rotation = Utils.angleFromVec(vx, vy);
  }
  _onUpdate(dt) {
    this.life += dt;
    if (this.life > this.maxLife) { this.active = false; this.dead = true; return; }

    switch (this.bMode) {
      case 'accel':
        // 在原速度上加速
        if (this.accel) {
          const cur = Math.sqrt(this.vx*this.vx + this.vy*this.vy);
          const newSpeed = Math.min(cur + this.accel * dt, 600);
          const ang = Math.atan2(this.vy, this.vx);
          this.vx = Math.cos(ang) * newSpeed;
          this.vy = Math.sin(ang) * newSpeed;
        }
        break;
      case 'decel':
        if (this.accel) {
          const cur = Math.sqrt(this.vx*this.vx + this.vy*this.vy);
          const newSpeed = Math.max(cur - this.accel * dt, 30);
          const ang = Math.atan2(this.vy, this.vx);
          this.vx = Math.cos(ang) * newSpeed;
          this.vy = Math.sin(ang) * newSpeed;
        }
        break;
      case 'curve':
        // 围绕中心曲线
        if (this.curveAmount) {
          this.rotation += this.curveAmount * dt;
          const speed = Math.sqrt(this.vx*this.vx + this.vy*this.vy);
          const r = Utils.rad(this.rotation);
          this.vx = Math.cos(r) * speed;
          this.vy = Math.sin(r) * speed;
        }
        break;
      case 'spiral':
        // 子弹自身方向旋转（弹幕图案螺旋）
        if (this.spinAngle) {
          this.rotation += this.spinAngle * dt;
          const speed = Math.sqrt(this.vx*this.vx + this.vy*this.vy);
          const r = Utils.rad(this.rotation);
          this.vx = Math.cos(r) * speed;
          this.vy = Math.sin(r) * speed;
        }
        break;
      case 'homing':
        if (this.homingStrength > 0) {
          if (!this.target || !this.target.alive) {
            this.target = Game.player;
          }
          if (this.target) {
            const dx = this.target.x - this.x;
            const dy = this.target.y - this.y;
            const len = Math.sqrt(dx*dx + dy*dy) || 1;
            const tvx = dx/len * this.bornSpeed;
            const tvy = dy/len * this.bornSpeed;
            this.vx = Utils.lerp(this.vx, tvx, this.homingStrength * dt);
            this.vy = Utils.lerp(this.vy, tvy, this.homingStrength * dt);
          }
        }
        break;
      case 'wave':
        // 蛇形弹：前进方向绕出生角度正弦摆动
        if (this.waveAmp) {
          const wob = Math.sin(this.life * this.waveFreq * 6.283) * this.waveAmp;
          const r = Utils.rad(this.bornAngle + wob);
          this.vx = Math.cos(r) * this.bornSpeed;
          this.vy = Math.sin(r) * this.bornSpeed;
          this.rotation = this.bornAngle + wob;
        }
        break;
      // 'straight' 无变化
    }

    // 分裂检测
    if (this.split && this.life >= this.splitTime) {
      this._doSplit();
      this.active = false; this.dead = true;
      return;
    }

    // 出界（缩短宽容区，避免子弹滞留过久）
    if (this.x < -20 || this.x > Balance.width + 20 || this.y < -20 || this.y > Balance.height + 20) {
      this.active = false; this.dead = true;
    }
  }
  _doSplit() {
    if (!this.ownerBoss) return;
    const speed = this.bornSpeed * 0.9;
    for (let i = 0; i < this.splitCount; i++) {
      const a = (i / this.splitCount) * 360 + Math.random() * 30;
      const r = Utils.rad(a);
      EnemyBulletPool.spawn(this.x, this.y, Math.cos(r) * speed, Math.sin(r) * speed, {
        color: this.color, radius: 4, mode: 'straight', maxLife: 3,
      });
    }
  }
  _onDraw(ctx) {
    ctx.save();
    ctx.shadowBlur = 4;       // 降低发光重叠（避免满屏糊一团）
    ctx.shadowColor = this.color;
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Utils.TAU);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius * 0.35, 0, Utils.TAU);
    ctx.fill();
    ctx.restore();
  }
}

// 敌弹对象池
const EnemyBulletPool = {
  pool: [],
  init(size = 800) {
    this.pool = [];
    for (let i = 0; i < size; i++) this.pool.push(new EnemyBullet());
  },
  spawn(x, y, vx, vy, opts) {
    let b = null;
    for (let i = 0; i < this.pool.length; i++) {
      if (!this.pool[i].active) { b = this.pool[i]; break; }
    }
    if (!b) { b = new EnemyBullet(); this.pool.push(b); }
    b.spawn(x, y, vx, vy, opts);
    return b;
  },
  // 从角度发射
  spawnAt(x, y, angleDeg, speed, opts = {}) {
    const r = Utils.rad(angleDeg);
    return this.spawn(x, y, Math.cos(r) * speed, Math.sin(r) * speed, opts);
  },
  update(dt) {
    for (let i = 0; i < this.pool.length; i++) {
      const b = this.pool[i];
      if (!b.active) continue;
      b.update(dt);
      if (b.dead) b.active = false;
    }
  },
  draw(ctx) {
    for (let i = 0; i < this.pool.length; i++) {
      if (this.pool[i].active) this.pool[i].draw(ctx);
    }
  },
  forEachActive(fn) {
    for (let i = 0; i < this.pool.length; i++) {
      if (this.pool[i].active) fn(this.pool[i]);
    }
  },
  clear() {
    for (let i = 0; i < this.pool.length; i++) this.pool[i].active = false;
  },
  // 清屏（Bomb 效果）
  clearAll() {
    let cleared = 0;
    for (let i = 0; i < this.pool.length; i++) {
      if (this.pool[i].active) { this.pool[i].active = false; cleared++; }
    }
    return cleared;
  },
};

/* Option.js */
// ====== src/entities/Option.js ======
// 僚机：跟随玩家，协同开火

class Option extends Entity {
  constructor() {
    super();
    this.radius = 8;
    this.formation = 'tight';   // tight / spread
    this.index = 0;              // 第几号僚机（0 或 1）
    this.fireCooldown = 0;
    this.targetX = 0;
    this.targetY = 0;
  }

  setup(player, index) {
    this.index = index;
    this.formation = player.formation;
    this.x = player.x;
    this.y = player.y;
    this.fireCooldown = 0;
  }

  _onUpdate(dt) {
    // 跟随目标位置
    this._computeTargetPos();
    // 平滑跟随
    this.x = Utils.lerp(this.x, this.targetX, 0.18);
    this.y = Utils.lerp(this.y, this.targetY, 0.18);

    // 自动开火
    this.fireCooldown -= dt;
    if (this.fireCooldown <= 0) {
      this._fire();
      const cd = Balance.player.fireCooldown[Game.player.weapon.type] || 0.12;
      this.fireCooldown = cd * 1.4; // 僚机射速稍慢
    }
  }

  _computeTargetPos() {
    const player = Game.player;
    if (!player) return;
    this.formation = player.formation;
    const offset = this.index === 0 ? -1 : 1;
    if (this.formation === 'tight') {
      // 紧贴玩家下方两侧
      this.targetX = player.x + offset * 18;
      this.targetY = player.y + 14;
    } else {
      // 展开：远离玩家两侧
      this.targetX = player.x + offset * 50;
      this.targetY = player.y + 8;
    }
  }

  _fire() {
    const player = Game.player;
    if (!player || !player.alive) return;
    const lvl = player.weapon.level;
    const damage = lvl * Balance.player.optionFireMultiplier;
    const w = player.weapon.type;
    const speed = Balance.bullet.playerScatter;

    if (w === 'scatter') {
      // 直射
      PlayerBulletPool.spawn(this.x, this.y - 8, 0, -speed, 'scatter', lvl, damage);
    } else if (w === 'laser') {
      // 短激光
      PlayerBulletPool.spawn(this.x, this.y - 8, 0, -Balance.bullet.playerScatter * 1.5, 'laser', lvl, damage);
    } else if (w === 'homing') {
      PlayerBulletPool.spawn(this.x, this.y - 8, 0, -speed, 'homing', lvl, damage);
    }
    if (Game.audio) Game.audio.play('shoot');
  }

  _onDraw(ctx) {
    const player = Game.player;
    const w = player ? player.weapon.type : 'scatter';
    const color = w === 'laser' ? '#00f0ff' : w === 'homing' ? '#9b5cff' : Balance.color.cyan;

    ctx.save();
    ctx.shadowBlur = 12;
    ctx.shadowColor = color;
    // 小三角僚机
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(this.x, this.y - 10);
    ctx.lineTo(this.x - 7, this.y + 6);
    ctx.lineTo(this.x + 7, this.y + 6);
    ctx.closePath();
    ctx.fill();
    // 内核
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(this.x, this.y - 2, 3, 0, Utils.TAU);
    ctx.fill();
    ctx.restore();
  }
}

/* Player.js */
// ====== src/entities/Player.js ======
// 玩家飞机

class Player extends Entity {
  constructor(x, y, planeKey) {
    super(x, y);
    const cfg = Planes[planeKey] || Planes.pioneer;
    this.planeKey = cfg.key;
    this.planeConfig = cfg;
    this.color = cfg.color;
    this.accent = cfg.accent;
    this.radius = 12;
    this.hp = cfg.startHp;
    this.maxHp = cfg.maxHp;
    this.speed = cfg.speed;
    this.weapon = { type: cfg.startWeapon, level: cfg.startWeaponLevel };
    this.energy = 0;
    this.bombs = cfg.startBombs;
    this.maxBombs = Balance.player.maxBombs;
    this.graze = 0;
    this.invincible = 0;
    this.hitboxRadius = Balance.player.hitboxRadius;
    this.grazeRadius = Balance.player.grazeRadius;
    this.options = [];           // 僚机数组
    this.formation = 'tight';
    this.slowMode = false;
    this.fireCooldown = 0;
    this.flashTimer = 0;         // 受伤闪烁
    this.shielded = false;        // 护盾
    this.dead = false;
    // 飞机朝向角度（视觉用）
    this.tilt = 0;
    // 死亡后短暂等待重生
    this.respawnTimer = 0;
    this.alive = true;
    // 玩家受击相关：用于"完美 Boss"判定
    this.tookDamageThisStage = false;
    // 商店永久强化
    this.dmgMult = 1;
    this.homingExtra = 0;
    this.homingAgile = false;
    this.laserRapid = false;
    this._applyShopUpgrades(cfg);
    // 同步追踪敏捷标记到弹池（homing 转向用）
    PlayerBulletPool.homingAgile = this.homingAgile;
    // 消耗品：临时护盾（Game 在开局时消费库存并置 pending 标记）
    if (Game._shieldPending) {
      Game._shieldPending = false;
      this.shielded = true;
    }
  }

  // 应用武器商店已购强化（永久生效）
  _applyShopUpgrades(cfg) {
    if (typeof SaveSystem === 'undefined' || !SaveSystem.getOwnedItems) return;
    const owned = SaveSystem.getOwnedItems();
    for (let i = 0; i < owned.length; i++) {
      switch (owned[i]) {
        case 'scatter_plus':
          // 全武器伤害 +25%（散弹为主），散射系开局火力+1
          this.dmgMult *= 1.25;
          if (this.weapon.type === 'scatter') {
            this.weapon.level = Math.min(Balance.player.maxWeaponLevel, this.weapon.level + 1);
          }
          break;
        case 'laser_plus':
          // 激光伤害 +30%
          this.dmgMult *= 1.30;
          this.laserRapid = true;
          break;
        case 'homing_plus':
          this.homingExtra = 2;
          this.homingAgile = true;
          break;
        case 'start_bomb':
          this.maxBombs = Balance.player.maxBombs + 1;
          this.bombs = Math.min(this.maxBombs, this.bombs + 1);
          break;
        case 'start_option':
          if (this.options.length < 2) {
            const opt = new Option();
            opt.setup(this, this.options.length);
            this.options.push(opt);
          }
          break;
        case 'hp_up':
          this.maxHp = cfg.maxHp + 1;
          this.hp = Math.min(this.maxHp, cfg.startHp + 1);
          break;
      }
    }
  }

  reset(x, y) {
    this.x = x; this.y = y;
    this.vx = 0; this.vy = 0;
    this.hp = Balance.player.startHp;
    this.maxHp = Balance.player.maxHp;
    this.weapon = { type: 'scatter', level: 1 };
    this.energy = 0;
    this.bombs = Balance.player.startBombs;
    this.graze = 0;
    this.invincible = 1.0;
    this.options = [];
    this.formation = 'tight';
    this.slowMode = false;
    this.fireCooldown = 0;
    this.flashTimer = 0;
    this.shielded = false;
    this.dead = false;
    this.alive = true;
    this.tookDamageThisStage = false;
  }

  // 解锁僚机
  addOption() {
    if (this.options.length >= 2) return;
    const opt = new Option();
    opt.setup(this, this.options.length);
    this.options.push(opt);
    if (Game.particles) Game.particles.spawnBurst(this.x, this.y, '#ffaa00', 16);
    if (Game.audio) Game.audio.play('powerup');
  }

  _onUpdate(dt) {
    if (!this.alive) return;

    // 输入移动
    let speed = this.speed;
    this.slowMode = Input.state.slow;
    if (this.slowMode) speed *= Balance.player.slowMultiplier;

    let mx = Input.moveX, my = Input.moveY;
    // 触摸控制：朝触控目标点平滑移动（Input 采用相对拖动虚拟摇杆，
    // touchPos = 飞机初始位置 + 手指滑动 delta，手指不会遮挡飞机）
    if (Input.touchActive && Input.touchPos) {
      const dx = Input.touchPos.x - this.x;
      const dy = Input.touchPos.y - this.y;
      const d = Math.sqrt(dx*dx + dy*dy);
      if (d > 2) {
        // 平滑追随
        const factor = Math.min(1, d / 30);
        this.vx = (dx / d) * speed * factor;
        this.vy = (dy / d) * speed * factor;
        mx = this.vx / speed;
        my = this.vy / speed;
      } else {
        this.vx = 0; this.vy = 0; mx = 0; my = 0;
      }
    } else {
      this.vx = mx * speed;
      this.vy = my * speed;
    }

    super._onUpdate(dt);

    // 限制在画布内
    this.x = Utils.clamp(this.x, this.radius, Balance.width - this.radius);
    this.y = Utils.clamp(this.y, this.radius, Balance.height - this.radius);

    // 倾斜视觉
    this.tilt = Utils.lerp(this.tilt, mx * 0.4, 0.2);

    // 无敌计时
    if (this.invincible > 0) this.invincible -= dt;
    if (this.flashTimer > 0) this.flashTimer -= dt;
    // 清屏技能冷却
    if (this._clearCd !== undefined && this._clearCd > 0) this._clearCd -= dt;

    // 自动开火（默认开启；按住 Space/J 也开火）
    this.fireCooldown -= dt;
    if (this.fireCooldown <= 0 && Input.state.firing) {
      this._fire();
      let cd = Balance.player.fireCooldown[this.weapon.type] || 0.10;
      // 商店：激光急速
      if (this.laserRapid && this.weapon.type === 'laser') cd *= 0.85;
      this.fireCooldown = cd * (1 - (this.weapon.level - 1) * 0.08);
    }

    // Bomb（Z）
    if (Input.actions.bomb) {
      this._useBomb();
    }
    // 一键清屏技能（Q）：清除全场敌弹 + AOE 伤害
    if (Input.actions.clearScreen) {
      this._useClearScreen();
    }
    // 一键投降技能（X）：主动放弃本局
    if (Input.actions.surrender) {
      this._surrender();
    }
    // 切换编队
    if (Input.actions.toggleFormation) {
      this.formation = this.formation === 'tight' ? 'spread' : 'tight';
      if (Game.audio) Game.audio.play('toggle');
    }

    // 更新僚机
    for (let i = this.options.length - 1; i >= 0; i--) {
      const opt = this.options[i];
      opt.update(dt);
    }
  }

  _fire() {
    const lvl = this.weapon.level;
    const dmg = lvl * 0.9 * (this.dmgMult || 1);
    const w = this.weapon.type;

    if (w === 'scatter') {
      const speed = Balance.bullet.playerScatter;
      // 1 级单发，3 级 3 发扇形，5 级 5 发扇形+2 后侧
      const fanCount = lvl === 1 ? 1 : lvl <= 3 ? 3 : 5;
      const spread = lvl <= 3 ? 18 : 28;
      const half = (fanCount - 1) / 2;
      for (let i = 0; i < fanCount; i++) {
        const offset = (i - half) * (spread / Math.max(1, half));
        const ang = -90 + offset;
        const r = Utils.rad(ang);
        PlayerBulletPool.spawn(this.x, this.y - 8, Math.cos(r) * speed, Math.sin(r) * speed, 'scatter', lvl, dmg);
      }
      if (lvl === 5) {
        // 后侧 2 发
        PlayerBulletPool.spawn(this.x - 10, this.y, -speed * 0.6, 0, 'scatter', lvl, dmg * 0.6);
        PlayerBulletPool.spawn(this.x + 10, this.y, speed * 0.6, 0, 'scatter', lvl, dmg * 0.6);
      }
    } else if (w === 'laser') {
      // 主激光（穿透）
      const speed = Balance.bullet.playerScatter * 1.8;
      PlayerBulletPool.spawn(this.x, this.y - 8, 0, -speed, 'laser', lvl, dmg);
      if (lvl >= 3) {
        PlayerBulletPool.spawn(this.x - 14, this.y - 4, 0, -speed, 'laser', lvl, dmg * 0.7);
        PlayerBulletPool.spawn(this.x + 14, this.y - 4, 0, -speed, 'laser', lvl, dmg * 0.7);
      }
      if (lvl === 5) {
        PlayerBulletPool.spawn(this.x - 24, this.y, -speed * 0.3, -speed * 0.6, 'laser', lvl, dmg * 0.5);
        PlayerBulletPool.spawn(this.x + 24, this.y, speed * 0.3, -speed * 0.6, 'laser', lvl, dmg * 0.5);
      }
    } else if (w === 'homing') {
      const speed = Balance.bullet.playerHoming;
      const count = (lvl === 1 ? 1 : lvl <= 3 ? 3 : 5) + (this.homingExtra || 0);
      for (let i = 0; i < count; i++) {
        const offset = (i - (count-1)/2) * 12;
        PlayerBulletPool.spawn(this.x + offset, this.y - 8, 0, -speed, 'homing', lvl, dmg);
      }
      if (lvl === 5) {
        // 副散射
        PlayerBulletPool.spawn(this.x, this.y, -1, -1, 'scatter', lvl, dmg * 0.5);
        PlayerBulletPool.spawn(this.x, this.y, 1, -1, 'scatter', lvl, dmg * 0.5);
      }
    }

    if (Game.audio) Game.audio.play('shoot');
  }

  _useBomb() {
    if (this.bombs <= 0 && this.energy < Balance.energy.bombCost) return;
    if (this.bombs <= 0) {
      // 用能量
      if (this.energy < Balance.energy.bombCost) return;
      this.energy = 0;
    } else {
      this.bombs--;
    }
    this._doScreenClear(false);
    // 统计
    if (Game.stats) Game.stats.onBomb();
  }

  // 一键清屏技能（Q）：无需消耗炸弹/能量，但只清敌弹 + 轻量 AOE，且有冷却
  _useClearScreen() {
    if (this._clearCd !== undefined && this._clearCd > 0) {
      // 冷却中：提示
      if (Game.particles) Game.particles.spawnText(this.x, this.y - 24, '冷却中', '#ff3050');
      return;
    }
    this._clearCd = 8; // 8 秒冷却
    this._doScreenClear(true);
    // 提示文字
    if (Game.particles) Game.particles.spawnText(this.x, this.y - 24, '清屏！', '#00f0ff');
  }

  // 实际清屏效果
  _doScreenClear(light) {
    const cleared = EnemyBulletPool.clearAll();
    this.invincible = Math.max(this.invincible, light ? 0.8 : Balance.energy.bombInvincibleTime);
    // 全屏敌人 AOE（轻量 20% / 炸弹 30%）
    const pct = light ? 0.20 : Balance.energy.bombAoEDamagePercent;
    Game.enemies.forEach(e => {
      if (e.alive) e.damage(e.maxHp * pct, this);
    });
    if (Game.boss && Game.boss.alive) {
      Game.boss.damage(Game.boss.maxHp * pct, this);
    }
    // 视觉效果
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, '#ffffff', light ? 120 : 200);
    Effects.flash();
    if (Game.audio) Game.audio.play('bomb');
  }

  // 一键投降技能（X）：主动放弃本局，直接判定玩家死亡（不消耗复活币）
  _surrender() {
    if (!this.alive) return;
    // 视觉提示
    if (Game.particles) Game.particles.spawnText(this.x, this.y - 24, '投降！', '#ff3050');
    if (Game.audio) Game.audio.play('hurt');
    // 直接清空生命
    this.hp = 0;
    this._die(true);
  }

  takeDamage() {
    if (this.invincible > 0) return;
    if (this.shielded) {
      this.shielded = false;
      this.invincible = 0.6;
      if (Game.particles) Game.particles.spawnBurst(this.x, this.y, Balance.color.cyan, 20);
      if (Game.audio) Game.audio.play('shield');
      return;
    }
    this.hp--;
    this.tookDamageThisStage = true;
    this.invincible = Balance.player.invincibleTime;
    this.flashTimer = 0.3;
    this.weapon.level = Math.max(1, this.weapon.level - 1);
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, '#00f0ff', 30);
    if (Game.score) Game.score.breakCombo();
    if (Game.audio) Game.audio.play('hurt');
    if (this.hp <= 0) {
      this._die();
    }
  }

  _die(fromSurrender) {
    // 复活币：非投降被击坠时自动复活
    if (!fromSurrender && typeof SaveSystem !== 'undefined'
        && SaveSystem.getConsumableCount && SaveSystem.getConsumableCount('revive_token') > 0) {
      SaveSystem.useConsumable('revive_token');
      this.dead = false;
      this.alive = true;
      this.hp = 1;
      this.invincible = 2.5;
      EnemyBulletPool.clearAll();
      if (Game.particles) Game.particles.spawnBurst(this.x, this.y, '#ff2e88', 40);
      if (Game.particles) Game.particles.spawnText(this.x, this.y - 30, '复活币！', '#ff2e88');
      Effects.flash();
      if (Game.audio) Game.audio.play('powerup');
      return;
    }
    this.dead = true;
    this.alive = false;
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, '#ffaa00', 60);
    if (Game.audio) Game.audio.play('death');
    // 死亡倒计时（由 Game.update 检测并触发 Game Over，避免 setTimeout 跨重启污染）
    this.deathTimer = 0.8;
  }

  addGraze() {
    this.graze++;
    this.energy = Math.min(Balance.energy.max, this.energy + Balance.energy.fromGraze);
    if (Game.score) Game.score.addGraze();
    if (Game.particles) Game.particles.spawnGrazeFx(this.x, this.y);
    if (Game.audio) Game.audio.play('graze');
  }

  addEnergyFromKill() {
    this.energy = Math.min(Balance.energy.max, this.energy + Balance.energy.fromKill);
  }

  // 道具拾取
  pickup(kind) {
    if (kind === 'P') {
      if (this.weapon.level < Balance.player.maxWeaponLevel) {
        this.weapon.level++;
        if (Game.particles) Game.particles.spawnBurst(this.x, this.y, '#ffaa00', 12);
        if (Game.audio) Game.audio.play('powerup');
      } else {
        if (Game.score) Game.score.addScore(500);
      }
    } else if (kind === 'energy') {
      this.energy = Math.min(Balance.energy.max, this.energy + Balance.energy.fromPickup);
      if (Game.particles) Game.particles.spawnBurst(this.x, this.y, Balance.color.purple, 12);
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'bomb') {
      if (this.bombs < this.maxBombs) this.bombs++;
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'shield') {
      this.shielded = true;
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'life') {
      if (this.hp < this.maxHp) this.hp++;
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'option') {
      this.addOption();
    } else if (kind === 'weapon_scatter') {
      this.weapon.type = 'scatter';
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'weapon_laser') {
      this.weapon.type = 'laser';
      if (Game.audio) Game.audio.play('powerup');
    } else if (kind === 'weapon_homing') {
      this.weapon.type = 'homing';
      if (Game.audio) Game.audio.play('powerup');
    }
  }

  _onDraw(ctx) {
    if (!this.alive) return;

    const color = this.color;
    const accent = this.accent;

    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.tilt * 0.3);

    // 机身辉光
    ctx.shadowBlur = 16;
    ctx.shadowColor = color;

    ctx.globalAlpha = (this.invincible > 0 && Math.floor(this.age * 30) % 2 === 0) ? 0.5 : 1;
    ctx.fillStyle = color;

    // ===== 按战机类型画不同形状 =====
    switch (this.planeKey) {
      case 'interceptor':
        // 截击者：细长箭头型
        ctx.beginPath();
        ctx.moveTo(0, -22);
        ctx.lineTo(-8, 4);
        ctx.lineTo(-14, 10);
        ctx.lineTo(-4, 10);
        ctx.lineTo(0, 16);
        ctx.lineTo(4, 10);
        ctx.lineTo(14, 10);
        ctx.lineTo(8, 4);
        ctx.closePath();
        ctx.fill();
        break;
      case 'guardian':
        // 守护者：厚重梯形
        ctx.beginPath();
        ctx.moveTo(0, -16);
        ctx.lineTo(-18, 4);
        ctx.lineTo(-14, 12);
        ctx.lineTo(-6, 10);
        ctx.lineTo(0, 16);
        ctx.lineTo(6, 10);
        ctx.lineTo(14, 12);
        ctx.lineTo(18, 4);
        ctx.closePath();
        ctx.fill();
        // 额外装甲条纹
        ctx.fillStyle = accent;
        ctx.beginPath();
        ctx.moveTo(-12, 2); ctx.lineTo(12, 2); ctx.lineTo(8, -2); ctx.lineTo(-8, -2);
        ctx.closePath(); ctx.fill();
        break;
      case 'falcon':
        // 游隼：后掠翼箭型
        ctx.beginPath();
        ctx.moveTo(0, -20);
        ctx.lineTo(-6, 0);
        ctx.lineTo(-20, 8);
        ctx.lineTo(-8, 8);
        ctx.lineTo(0, 16);
        ctx.lineTo(8, 8);
        ctx.lineTo(20, 8);
        ctx.lineTo(6, 0);
        ctx.closePath();
        ctx.fill();
        break;
      default: // pioneer
        // 先锋号：标准三角
        ctx.beginPath();
        ctx.moveTo(0, -18);
        ctx.lineTo(-14, 10);
        ctx.lineTo(-6, 6);
        ctx.lineTo(0, 14);
        ctx.lineTo(6, 6);
        ctx.lineTo(14, 10);
        ctx.closePath();
        ctx.fill();
    }

    // 引擎尾焰
    ctx.shadowBlur = 8;
    const flick = 0.7 + Math.random() * 0.3;
    ctx.fillStyle = '#ffaa00';
    ctx.beginPath();
    ctx.moveTo(-4, 10);
    ctx.lineTo(0, 16 + 6 * flick);
    ctx.lineTo(4, 10);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#ffe8a0';
    ctx.beginPath();
    ctx.moveTo(-2, 10);
    ctx.lineTo(0, 13 + 4 * flick);
    ctx.lineTo(2, 10);
    ctx.closePath();
    ctx.fill();

    // 内核
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(0, -2, 4, 0, Utils.TAU);
    ctx.fill();

    // 护盾环
    if (this.shielded) {
      ctx.shadowBlur = 14;
      ctx.shadowColor = Balance.color.cyan;
      ctx.strokeStyle = Balance.color.cyan;
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.6 + Math.sin(this.age * 6) * 0.3;
      ctx.beginPath();
      ctx.arc(0, 0, 22, 0, Utils.TAU);
      ctx.stroke();
    }

    // 低速精确判定点
    if (this.slowMode) {
      ctx.shadowBlur = 8;
      ctx.shadowColor = '#ff2e88';
      ctx.fillStyle = '#ff2e88';
      ctx.globalAlpha = 1;
      ctx.beginPath();
      ctx.arc(0, 0, this.hitboxRadius, 0, Utils.TAU);
      ctx.fill();
      // 擦弹判定圈
      ctx.strokeStyle = 'rgba(255,46,136,0.4)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, this.grazeRadius, 0, Utils.TAU);
      ctx.stroke();
    }
    ctx.restore();

    // 僚机绘制
    for (let i = 0; i < this.options.length; i++) {
      this.options[i].draw(ctx);
    }
  }
}

/* Enemy.js */
// ====== src/entities/Enemy.js ======
// 敌机：6 种类型 + 自爆 / 精英护盾

// 网络热梗嘲讽语（随机分配给小怪）
const TAUNT_PHRASES = [
  '就这？',
  '你不行啊',
  '菜就多练',
  '退退退',
  '你礼貌吗',
  '真的栓Q',
  '我不李姐',
  '如何呢又能怎',
  '老叟戏顽童',
  '不知道，我的身材很曼妙',
  '大可不必',
  '蚌埠住了',
  '夺笋啊',
  '你已急哭',
  '助我破鼎',
  '胆子真是肥嘟嘟的',
];

class Enemy extends Entity {
  constructor(type, x, y, opts = {}) {
    super(x, y);
    const cfg = Balance.enemy[type] || Balance.enemy.grunt;
    this.type = type;
    this.hp = cfg.hp;
    this.maxHp = cfg.hp;
    this.scoreValue = cfg.score;
    this.radius = cfg.radius;
    this.speed = cfg.speed;
    this.shoot = cfg.shoot || false;
    this.shootInterval = cfg.shootInterval || 1.5;
    this.shootTimer = 0;
    this.hasShield = cfg.hasShield || false;
    this.shieldHp = this.hasShield ? Math.ceil(cfg.hp * 0.5) : 0;
    this.color = type === 'elite' ? '#9b5cff' : type === 'bomber' ? '#ffaa00' : type === 'ram' ? '#ff3050' : '#ff7050';
    this.entryPattern = opts.pattern || 'line';   // line / arc
    this.dropGuaranteed = opts.dropGuaranteed || null;
    // 入场目标位置 / 行为参数
    this.entryTime = 0;
    this.targetY = opts.targetY || 80;
    this.amp = opts.amp || 80;
    this.freq = opts.freq || 1.5;
    this.phase = opts.phase || Math.random() * Math.PI * 2;
    this.startX = x;
    this.arrived = false;
    this.exploded = false;
    this.explodeBullets = cfg.explodeBullets || 0;
    // 嘲讽文字：约 25% 概率随机分配一条热梗
    this.taunt = Math.random() < 0.25 ? Utils.pick(TAUNT_PHRASES) : null;
    this.tauntOffsetY = 0;
  }

  _onUpdate(dt) {
    this.entryTime += dt;
    switch (this.type) {
      case 'grunt':
        this.vy = this.speed;
        this.vx = 0;
        break;
      case 'zigzag':
        this.vy = this.speed;
        this.vx = Math.sin(this.entryTime * this.freq + this.phase) * this.amp;
        break;
      case 'arc':
        // 入场弧线后悬停射击
        if (!this.arrived) {
          this.vy = this.speed * 0.5;
          this.vx = Math.sin(this.entryTime * 1.5 + this.phase) * this.amp * 0.7;
          if (this.y >= this.targetY) { this.arrived = true; this.vy = 0; this.vx *= 0.3; }
        } else {
          this.vy = Math.sin(this.entryTime * 0.5) * 10;
          this.vx = Math.sin(this.entryTime * 0.7 + this.phase) * this.amp * 0.3;
        }
        break;
      case 'ram':
        // 高速冲向玩家
        if (Game.player) {
          const dx = Game.player.x - this.x;
          const dy = Game.player.y - this.y;
          const d = Math.sqrt(dx*dx + dy*dy) || 1;
          this.vx = dx/d * this.speed;
          this.vy = dy/d * this.speed;
        } else {
          this.vy = this.speed;
        }
        break;
      case 'bomber':
        // 接近后爆炸散弹
        this.vy = this.speed;
        this.vx = Math.sin(this.entryTime * 0.8 + this.phase) * 30;
        // 离玩家 100px 内或飞到一定位置就自爆
        if (Game.player) {
          const d = Utils.dist(this.x, this.y, Game.player.x, Game.player.y);
          if (d < 120 || this.y > Balance.height - 100) {
            this._explode();
          }
        }
        break;
      case 'elite':
        // 缓慢下降，规律射击
        if (this.y < this.targetY) {
          this.vy = this.speed;
          this.vx = 0;
        } else {
          this.vy = Math.sin(this.entryTime * 0.5) * 20;
          this.vx = Math.sin(this.entryTime * 0.6 + this.phase) * this.amp * 0.5;
        }
        break;
    }

    super._onUpdate(dt);

    // 射击
    if (this.shoot && this.y > 0) {
      this.shootTimer -= dt;
      if (this.shootTimer <= 0) {
        this._shoot();
        this.shootTimer = this.shootInterval;
      }
    }

    // 出界
    if (this.offscreen(50)) {
      this.dead = true;
      // 逃逸（不计入击杀）
      if (Game.score) Game.score.markEscaped(this);
    }
  }

  _shoot() {
    if (!Game.player) return;
    const speed = Balance.bullet.enemyStraight;
    const dx = Game.player.x - this.x;
    const dy = Game.player.y - this.y;
    const d = Math.sqrt(dx*dx + dy*dy) || 1;
    EnemyBulletPool.spawn(this.x, this.y + this.radius, dx/d * speed, dy/d * speed, {
      color: this.color, radius: 5,
    });
    if (Game.audio) Game.audio.play('enemyShoot');
  }

  _explode() {
    if (this.exploded) return;
    this.exploded = true;
    // 散弹
    const n = this.explodeBullets || 8;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * 360 + Math.random() * 20;
      const r = Utils.rad(a);
      EnemyBulletPool.spawn(this.x, this.y, Math.cos(r) * 200, Math.sin(r) * 200, {
        color: '#ffaa00', radius: 5,
      });
    }
    this.hp = 0;
    this.dead = true;
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, '#ffaa00', 18);
    if (Game.audio) Game.audio.play('explode');
  }

  damage(amount, source) {
    if (this.shieldHp > 0) {
      this.shieldHp--;
      if (this.shieldHp <= 0) {
        this.hasShield = false;
        if (Game.particles) Game.particles.spawnBurst(this.x, this.y, Balance.color.cyan, 12);
      }
      return;
    }
    this.hp -= amount;
    if (this.hp <= 0) {
      this._die(source);
    }
  }

  _die(source) {
    this.dead = true;
    this.alive = false;
    if (Game.score) Game.score.addKill(this);
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, this.color, 14);
    if (Game.audio) Game.audio.play('explode');
    if (Game.player) Game.player.addEnergyFromKill();
    // 掉落
    this._maybeDrop();
  }

  _maybeDrop() {
    let kind = null;
    if (this.dropGuaranteed) {
      kind = this.dropGuaranteed;
    } else {
      const rates = this.type === 'elite' ? Balance.dropRates.elite : Balance.dropRates.normal;
      if (Utils.chance(rates.P)) kind = 'P';
      else if (Utils.chance(rates.energy)) kind = 'energy';
      else if (Utils.chance(rates.bomb)) kind = 'bomb';
      else if (Utils.chance(rates.shield)) kind = 'shield';
      else if (Utils.chance(rates.life)) kind = 'life';
      else if (this.type === 'elite' && Utils.chance(rates.option)) kind = 'option';
    }
    if (kind && Game.pickups) {
      Game.pickups.push(new Pickup(this.x, this.y, kind));
    }
  }

  _onDraw(ctx) {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.shadowBlur = 10;
    ctx.shadowColor = this.color;

    ctx.fillStyle = this.color;
    switch (this.type) {
      case 'grunt':
        // 倒三角小敌
        ctx.beginPath();
        ctx.moveTo(0, 12);
        ctx.lineTo(-10, -8);
        ctx.lineTo(10, -8);
        ctx.closePath();
        ctx.fill();
        break;
      case 'zigzag':
        // 菱形
        ctx.beginPath();
        ctx.moveTo(0, -12);
        ctx.lineTo(10, 0);
        ctx.lineTo(0, 12);
        ctx.lineTo(-10, 0);
        ctx.closePath();
        ctx.fill();
        break;
      case 'arc':
        // 圆形带翼
        ctx.beginPath();
        ctx.arc(0, 0, 12, 0, Utils.TAU);
        ctx.fill();
        ctx.fillStyle = '#ff7050';
        ctx.fillRect(-16, -3, 8, 6);
        ctx.fillRect(8, -3, 8, 6);
        break;
      case 'ram':
        // 火箭型
        ctx.beginPath();
        ctx.moveTo(0, 14);
        ctx.lineTo(-8, -10);
        ctx.lineTo(0, -6);
        ctx.lineTo(8, -10);
        ctx.closePath();
        ctx.fill();
        break;
      case 'bomber':
        // 球+红点
        ctx.beginPath();
        ctx.arc(0, 0, 12, 0, Utils.TAU);
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#ff3050';
        ctx.beginPath();
        ctx.arc(0, 0, 4, 0, Utils.TAU);
        ctx.fill();
        break;
      case 'elite':
        // 大六边形
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Utils.TAU;
          const px = Math.cos(a) * 18;
          const py = Math.sin(a) * 18;
          if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, 4, 0, Utils.TAU);
        ctx.fill();
        break;
    }

    // 护盾
    if (this.hasShield) {
      ctx.shadowBlur = 12;
      ctx.shadowColor = Balance.color.cyan;
      ctx.strokeStyle = Balance.color.cyan;
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius + 6, 0, Utils.TAU);
      ctx.stroke();
    }

    // 血条（精英）
    if (this.type === 'elite' && this.hp < this.maxHp) {
      ctx.shadowBlur = 0;
      const w = 30;
      ctx.fillStyle = 'rgba(255,255,255,0.2)';
      ctx.fillRect(-w/2, -this.radius - 8, w, 3);
      ctx.fillStyle = '#ff3050';
      ctx.fillRect(-w/2, -this.radius - 8, w * (this.hp / this.maxHp), 3);
    }

    ctx.restore();

    // 嘲讽文字气泡
    if (this.taunt) {
      ctx.save();
      ctx.translate(this.x, this.y);
      const bob = Math.sin(this.age * 3) * 2;
      const ty = -this.radius - 22 + bob;
      // 气泡背景
      ctx.font = 'bold 11px "Microsoft YaHei", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const metrics = ctx.measureText(this.taunt);
      const bw = metrics.width + 12;
      const bh = 18;
      ctx.fillStyle = 'rgba(20,28,50,0.92)';
      ctx.strokeStyle = this.color;
      ctx.lineWidth = 1;
      // 圆角矩形
      const bx = -bw / 2;
      const by = ty - bh / 2;
      ctx.beginPath();
      ctx.moveTo(bx + 4, by);
      ctx.lineTo(bx + bw - 4, by);
      ctx.quadraticCurveTo(bx + bw, by, bx + bw, by + 4);
      ctx.lineTo(bx + bw, by + bh - 4);
      ctx.quadraticCurveTo(bx + bw, by + bh, bx + bw - 4, by + bh);
      ctx.lineTo(bx + 4, by + bh);
      ctx.quadraticCurveTo(bx, by + bh, bx, by + bh - 4);
      ctx.lineTo(bx, by + 4);
      ctx.quadraticCurveTo(bx, by, bx + 4, by);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      // 文字
      ctx.shadowBlur = 4;
      ctx.shadowColor = this.color;
      ctx.fillStyle = '#ffffff';
      ctx.fillText(this.taunt, 0, ty);
      ctx.restore();
    }
  }
}

/* Boss.js */
// ====== src/entities/Boss.js ======
// Boss：多阶段、多弹幕图案、炮塔系统、入场仪式

class Boss extends Entity {
  constructor(config) {
    super(Balance.width / 2, -100);
    this.config = config;
    this.name = config.name;
    this.title = config.title;
    this.color = config.color;
    this.maxHp = config.maxHp;
    this.hp = config.maxHp;
    this.radius = config.radius;
    this.coreRadius = config.coreRadius || 18;
    this.hoverY = config.hoverY || 140;
    this.movePattern = config.movePattern || 'sweep';
    this.moveRange = config.moveRange || 160;
    this.moveSpeed = config.moveSpeed || 90;
    this.phases = config.phases;
    this.phaseIndex = 0;
    this.state = 'intro';      // intro / fight / transition / dead
    this.introTimer = 2.0;     // 入场时长
    this.invincible = 2.0;
    this.turrets = [];
    this.patternIndex = 0;
    this.patternTimer = 0;
    this.patternFireTimer = 0;
    this.moveDir = 1;
    this.moveOriginX = Balance.width / 2;
    this.transitionTimer = 0;
    this.coreExposed = false;
    this.coreAlwaysOpen = false;
    this.invulnerable = false;  // 炮塔存活时无敌（深渊Boss）
    this.summonTimer = 0;
    this.warningActive = true;  // 出场 WARNING
    this.warningTimer = 1.8;
    this.spawnArrived = false;
    this.tilt = 0;
    this.perfectStage = true;   // 完美阶段标记
    this.finalDeathTimer = 0;
    // 战斗台词计时器（黄牛 Boss 定时插入经典台词）
    this._dialogueTimer = 8 + Math.random() * 5;
    this._dialogueIndex = 0;

    // 创建炮塔
    if (config.turrets) {
      for (let i = 0; i < config.turrets.length; i++) {
        const t = config.turrets[i];
        this.turrets.push(new BossTurret(this, t));
      }
    }
  }

  _onUpdate(dt) {
    // WARNING 阶段
    if (this.warningActive) {
      this.warningTimer -= dt;
      if (this.warningTimer <= 0) this.warningActive = false;
      return;
    }

    // 入场
    if (this.state === 'intro') {
      this.introTimer -= dt;
      this.y = Utils.lerp(this.y, this.hoverY, 0.04);
      if (this.introTimer <= 0 || Math.abs(this.y - this.hoverY) < 2) {
        this.y = this.hoverY;
        this.state = 'fight';
        this.introTimer = 0;
        this.invincible = 0;
      }
      return;
    }

    // 阶段过渡
    if (this.state === 'transition') {
      this.transitionTimer -= dt;
      if (this.transitionTimer <= 0) {
        this.state = 'fight';
        this.invincible = 0;
      }
      return;
    }

    // 死亡动画
    if (this.state === 'dead') {
      this.finalDeathTimer -= dt;
      // 爆炸连锁
      if (Math.random() < 0.4) {
        const ex = this.x + Utils.rndRange(-this.radius, this.radius);
        const ey = this.y + Utils.rndRange(-this.radius, this.radius);
        if (Game.particles) Game.particles.spawnExplosion(ex, ey, Utils.pick(['#ffaa00','#ff3050','#ffffff']), 10);
        if (Game.audio) Game.audio.play('explode');
      }
      if (this.finalDeathTimer <= 0) {
        this.dead = true;
        if (Game) Game.onBossDefeated(this);
      }
      return;
    }

    // ===== fight 主状态 =====
    // 移动
    this._updateMovement(dt);

    // 黄牛 Boss 战斗台词（定时插入经典台词）
    if (this.config.character === 'cow') {
      this._dialogueTimer -= dt;
      if (this._dialogueTimer <= 0) {
        this._speakCowDialogue();
        this._dialogueTimer = 12 + Math.random() * 6;
      }
    }

    // 阶段判定
    this._updatePhase(dt);

    // 炮塔更新
    for (let i = this.turrets.length - 1; i >= 0; i--) {
      const t = this.turrets[i];
      t.update(dt);
      if (t.dead) this.turrets.splice(i, 1);
    }
    // 全部炮塔被破 -> invulnerable = false
    if (this.invulnerable && this.turrets.length === 0) {
      this.invulnerable = false;
      // 进入下一阶段
      this._nextPhase();
    }

    if (this.invulnerable) return; // 炮塔存活时核心不射击

    // 弹幕图案
    const phase = this.phases[this.phaseIndex];
    const pattern = phase.patterns[this.patternIndex];
    this.patternTimer -= dt;
    this.patternFireTimer -= dt;

    // 召唤
    if (pattern.type === 'summon') {
      this.summonTimer -= dt;
      if (this.summonTimer <= 0) {
        this._summon(pattern);
        this.summonTimer = pattern.fireRate;
      }
    } else if (this.patternFireTimer <= 0) {
      this._firePattern(pattern);
      this.patternFireTimer = pattern.fireRate;
    }

    if (this.patternTimer <= 0) {
      // 切换到下一个 pattern
      this.patternIndex = (this.patternIndex + 1) % phase.patterns.length;
      const next = phase.patterns[this.patternIndex];
      this.patternTimer = next.duration || 4;
      this.patternFireTimer = 0;
    }
  }

  _updateMovement(dt) {
    if (this.movePattern === 'sweep') {
      this.x += this.moveDir * this.moveSpeed * dt;
      if (this.x > this.moveOriginX + this.moveRange) { this.x = this.moveOriginX + this.moveRange; this.moveDir = -1; }
      if (this.x < this.moveOriginX - this.moveRange) { this.x = this.moveOriginX - this.moveRange; this.moveDir = 1; }
    }
  }

  _updatePhase(dt) {
    const phase = this.phases[this.phaseIndex];
    const nextIndex = this.phaseIndex + 1;
    if (nextIndex < this.phases.length) {
      const next = this.phases[nextIndex];
      if (this.hp <= this.maxHp * next.hpThreshold) {
        this._nextPhase();
      }
    }
  }

  _nextPhase() {
    const nextIndex = this.phaseIndex + 1;
    if (nextIndex >= this.phases.length) {
      // 已是最后阶段，HP 已为 0 -> 死亡
      return;
    }
    this.phaseIndex = nextIndex;
    const phase = this.phases[this.phaseIndex];
    this.patternIndex = 0;
    this.patternTimer = phase.patterns[0].duration || 4;
    this.patternFireTimer = 0;
    this.state = 'transition';
    this.transitionTimer = 1.0;
    this.invincible = 1.0;
    this.coreExposed = !!phase.coreExposed;
    this.coreAlwaysOpen = !!phase.coreAlwaysOpen;
    // 阶段切换效果
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, phase.color, 80);
    if (Game.particles) Game.particles.spawnShockwave(this.x, this.y, phase.color);
    EnemyBulletPool.clearAll();
    Effects.flash();
    // 掉落道具
    this._dropOnTransition();
    if (Game.audio) Game.audio.play('bomb');
    // 更新 BossUI
    if (Game.bossUI) Game.bossUI.onPhaseChange(this);
    // 完美阶段标记重置（用于 Boss 完美通关判定）
    this.perfectStage = !Game.player.tookDamageThisStage;
  }

  _dropOnTransition() {
    const r = Balance.dropRates.bossTransition;
    const drops = [];
    if (Utils.chance(r.P)) drops.push('P');
    if (Utils.chance(r.energy)) drops.push('energy');
    if (Utils.chance(r.bomb)) drops.push('bomb');
    if (Utils.chance(r.shield)) drops.push('shield');
    if (Utils.chance(r.life)) drops.push('life');
    if (Game.pickups) {
      for (let i = 0; i < drops.length; i++) {
        const p = new Pickup(this.x + Utils.rndRange(-40, 40), this.y + 30, drops[i]);
        p.vy = 60 + i * 20;
        Game.pickups.push(p);
      }
    }
  }

  // ============ 弹幕图案分发 ============
  _firePattern(p) {
    switch (p.type) {
      case 'spiral': this._fireSpiral(p); break;
      case 'fan': this._fireFan(p); break;
      case 'cross': this._fireCross(p); break;
      case 'rotating_bars': this._fireRotatingBars(p); break;
      case 'split_homing': this._fireSplitHoming(p); break;
      case 'barrage': this._fireBarrage(p); break;
      case 'boomerang': this._fireBoomerang(p); break;
      case 'random_even': this._fireRandomEven(p); break;
      case 'wave_stream': this._fireWaveStream(p); break;
      case 'ring_pulse': this._fireRingPulse(p); break;
      case 'cross': this._fireCross(p); break;
    }
  }

  // 蛇形波流：朝玩家的数条正弦摆动弹
  _fireWaveStream(p) {
    const count = p.count || 4;
    const speed = p.bulletSpeed || 200;
    const amp = p.waveAmp || 28;
    const freq = p.waveFreq || 1.6;
    const player = Game.player;
    let baseAngle = 90;
    if (player) baseAngle = Utils.angleFromVec(player.x - this.x, player.y - this.y);
    for (let i = 0; i < count; i++) {
      const ang = baseAngle + (i - (count - 1) / 2) * (p.spread || 16);
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
        mode: 'wave', waveAmp: amp, waveFreq: freq,
      });
    }
  }

  // 环形脉冲：全周密集环，偶数圈反向偏移半步
  _fireRingPulse(p) {
    const count = p.count || 18;
    const speed = p.bulletSpeed || 210;
    const pulse = Math.floor(this.age * 2) % 2 === 1;
    const offset = pulse ? 180 / count : 0;
    for (let i = 0; i < count; i++) {
      const ang = (i / count) * 360 + offset;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, pulse ? speed * 0.82 : speed, {
        color: this.phases[this.phaseIndex].color, radius: 4,
      });
    }
  }

  // 螺旋
  _fireSpiral(p) {
    const arms = p.arms || 3;
    const speed = p.bulletSpeed || 200;
    const t = this.age * (p.fireRate > 0 ? 1 / p.fireRate : 10);
    for (let a = 0; a < arms; a++) {
      const ang = (t * 50 + a * (360 / arms)) % 360;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
      });
    }
  }

  // 扇形（朝玩家）
  _fireFan(p) {
    const count = p.count || 5;
    const spread = p.spread || 50;
    const speed = p.bulletSpeed || 220;
    const player = Game.player;
    let baseAngle = 90; // 默认朝下
    if (player) {
      baseAngle = Utils.angleFromVec(player.x - this.x, player.y - this.y);
    }
    const half = (count - 1) / 2;
    for (let i = 0; i < count; i++) {
      const offset = (i - half) * spread / Math.max(1, half);
      EnemyBulletPool.spawnAt(this.x, this.y, baseAngle + offset, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
      });
    }
  }

  // 交叉网（n 组交替方向）
  _fireCross(p) {
    const groups = p.groupCount || 4;
    const speed = p.bulletSpeed || 220;
    const t = Math.floor(this.age * 2);
    for (let i = 0; i < groups; i++) {
      const ang = (i / groups) * 180 + t * 30;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
      });
    }
  }

  // 旋转栅栏：弹幕墙以恒定角速度旋转，玩家找间隙穿
  _fireRotatingBars(p) {
    const bars = p.bars || 2;
    const speed = p.bulletSpeed || 200;
    const rotation = (this.age * 60) % 360;
    for (let b = 0; b < bars; b++) {
      const baseAng = rotation + (b / bars) * 360;
      // 一道弹幕墙：连续发射 5 发
      for (let i = -2; i <= 2; i++) {
        const ang = baseAng + i * (p.barWidth || 30) / 5;
        EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
          color: this.phases[this.phaseIndex].color, radius: 5,
        });
      }
    }
  }

  // 追踪分裂
  _fireSplitHoming(p) {
    const count = p.count || 4;
    const speed = p.bulletSpeed || 200;
    const splitTime = p.splitTime || 1.5;
    const splitCount = p.splitCount || 3;
    const player = Game.player;
    let baseAngle = 90;
    if (player) baseAngle = Utils.angleFromVec(player.x - this.x, player.y - this.y);
    for (let i = 0; i < count; i++) {
      const ang = baseAngle + (i - (count-1)/2) * 20;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 6,
        split: true, splitTime, splitCount, ownerBoss: this,
      });
    }
  }

  // 全方位弹幕（保证有可穿越间隙）
  _fireBarrage(p) {
    const count = p.count || 16;
    const speed = p.bulletSpeed || 240;
    const offset = this.age * 30;
    // 留一个 30° 缺口
    const gapAngle = Utils.rndRange(0, 360);
    for (let i = 0; i < count; i++) {
      const ang = (i / count) * 360 + offset;
      // 跳过缺口
      const diff = Math.abs(Utils.angleDiff(ang, gapAngle));
      if (diff < 15) continue;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
      });
    }
  }

  // 回旋返回
  _fireBoomerang(p) {
    const count = p.count || 4;
    const speed = p.bulletSpeed || 200;
    const player = Game.player;
    let baseAngle = 90;
    if (player) baseAngle = Utils.angleFromVec(player.x - this.x, player.y - this.y);
    for (let i = 0; i < count; i++) {
      const ang = baseAngle + (i - (count-1)/2) * 30;
      const r = Utils.rad(ang);
      EnemyBulletPool.spawn(this.x, this.y, Math.cos(r) * speed, Math.sin(r) * speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
        mode: 'decel', accel: 200, maxLife: 4,
      });
    }
  }

  // 随机均匀（有可穿越间隙）
  _fireRandomEven(p) {
    const count = p.count || 12;
    const speed = p.bulletSpeed || 220;
    // 留 1/4 的角度不发，制造可穿越路径
    const gapStart = Math.random() * 360;
    for (let i = 0; i < count; i++) {
      const ang = (i / count) * 360 + Math.random() * 5;
      const diff = Math.abs(Utils.angleDiff(ang, gapStart));
      if (diff < 45) continue;
      EnemyBulletPool.spawnAt(this.x, this.y, ang, speed, {
        color: this.phases[this.phaseIndex].color, radius: 5,
      });
    }
  }

  // 召唤小怪
  _summon(p) {
    const count = p.count || 2;
    const type = p.type_enemy || 'grunt';
    if (!Game.enemies) return;
    for (let i = 0; i < count; i++) {
      const x = this.x + Utils.rndRange(-30, 30);
      const y = this.y + this.radius + 10;
      const e = new Enemy(type, x, y, { pattern: 'line' });
      e.vy = 100;
      Game.enemies.push(e);
    }
    if (Game.audio) Game.audio.play('summon');
  }

  // ============ 受伤判定 ============
  damage(amount, source) {
    if (this.invincible > 0) return false;
    if (this.invulnerable) {
      // 炮塔存活，核心免伤
      return false;
    }
    // 阶段2+核心暴露时伤害×2
    if (this.coreExposed || this.coreAlwaysOpen) {
      amount *= 2;
    }
    this.hp = Math.max(0, this.hp - amount);
    // 受击粒子
    if (Game.particles && Math.random() < 0.5) {
      Game.particles.spawnBurst(this.x + Utils.rndRange(-this.radius/2, this.radius/2), this.y, '#ffffff', 4);
    }
    if (this.hp <= 0) {
      this._die();
    }
    return true;
  }

  _die() {
    if (this.state === 'dead') return;
    this.state = 'dead';
    this.finalDeathTimer = 2.0;
    this.invincible = 999;
    EnemyBulletPool.clearAll();
    if (Game.score) Game.score.addScore(5000);
    if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, '#ffffff', 80);
    if (Game.audio) Game.audio.play('bomb');
  }

  // 黄牛 Boss 战斗中插入的经典台词（参考《牛来》风格 + 火出圈电影台词）
  _speakCowDialogue() {
    const lines = [
      '牛来！',
      '我命由我不由天！',
      '你已急哭',
      '不知道，我的身材很曼妙',
      '老叟戏顽童',
      '如何呢又能怎',
      '胆子真是肥嘟嘟的',
      '助我破鼎',
    ];
    const line = lines[this._dialogueIndex % lines.length];
    this._dialogueIndex++;
    // 用浏览器语音合成朗读
    if (Game.audio && Game.audio.speak) {
      Game.audio.speak(line, { rate: 0.85, pitch: 0.75 });
    }
    // 同时在 Boss 头顶显示台词气泡
    if (Game.particles) {
      Game.particles.spawnText(this.x, this.y - this.radius - 20, line, '#f0c020');
    }
  }

  _onDraw(ctx) {
    // 入场前不出场（WARNING 时只画警告）
    if (this.state === 'intro' && this.y < -50) return;

    ctx.save();
    ctx.translate(this.x, this.y);
    const phase = this.phases[this.phaseIndex];
    const phaseColor = phase.color;

    ctx.shadowBlur = 20;
    ctx.shadowColor = phaseColor;

    // ===== 按 Boss 形态绘制角色 =====
    const r = this.radius;
    if (this.config.character === 'dog') {
      this._drawDogBoss(ctx, r, phaseColor);
    } else if (this.config.character === 'cow') {
      this._drawCowBoss(ctx, r, phaseColor);
    } else if (this.config.character === 'kangaroo') {
      this._drawKangarooBoss(ctx, r, phaseColor);
    } else if (this.config.turrets) {
      // 深渊母舰：大菱形+4 边角
      ctx.fillStyle = phaseColor;
      ctx.beginPath();
      ctx.moveTo(0, -this.radius);
      ctx.lineTo(this.radius * 0.8, 0);
      ctx.lineTo(this.radius * 0.6, this.radius * 0.7);
      ctx.lineTo(0, this.radius);
      ctx.lineTo(-this.radius * 0.6, this.radius * 0.7);
      ctx.lineTo(-this.radius * 0.8, 0);
      ctx.closePath();
      ctx.fill();
      // 内层
      ctx.fillStyle = Utils.hexToRgba(phaseColor, 0.5);
      ctx.beginPath();
      ctx.moveTo(0, -this.radius * 0.5);
      ctx.lineTo(this.radius * 0.4, 0);
      ctx.lineTo(0, this.radius * 0.4);
      ctx.lineTo(-this.radius * 0.4, 0);
      ctx.closePath();
      ctx.fill();
    } else if (this.title === '裂光') {
      // 棱镜：八角星
      ctx.fillStyle = phaseColor;
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * Utils.TAU + this.age * 0.3;
        const r = i % 2 === 0 ? this.radius : this.radius * 0.6;
        const px = Math.cos(a) * r;
        const py = Math.sin(a) * r;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fill();
    } else {
      // 巡哨者：圆形带翼
      ctx.fillStyle = phaseColor;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius * 0.8, 0, Utils.TAU);
      ctx.fill();
      // 侧翼
      ctx.beginPath();
      ctx.moveTo(-this.radius * 0.8, 0);
      ctx.lineTo(-this.radius * 1.3, this.radius * 0.5);
      ctx.lineTo(-this.radius * 0.6, this.radius * 0.4);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(this.radius * 0.8, 0);
      ctx.lineTo(this.radius * 1.3, this.radius * 0.5);
      ctx.lineTo(this.radius * 0.6, this.radius * 0.4);
      ctx.closePath();
      ctx.fill();
    }

    // 核心（阶段2+ 暴露时显示）
    if (this.coreExposed || this.coreAlwaysOpen || this.invulnerable) {
      const corePulse = 0.7 + Math.sin(this.age * 8) * 0.3;
      ctx.shadowBlur = 24;
      ctx.shadowColor = '#ffffff';
      ctx.fillStyle = `rgba(255,255,255,${corePulse})`;
      ctx.beginPath();
      ctx.arc(0, 0, this.coreRadius, 0, Utils.TAU);
      ctx.fill();
      // 内核
      ctx.fillStyle = phaseColor;
      ctx.beginPath();
      ctx.arc(0, 0, this.coreRadius * 0.5, 0, Utils.TAU);
      ctx.fill();
    } else {
      // 平时小核心
      ctx.shadowBlur = 8;
      ctx.fillStyle = Utils.hexToRgba('#ffffff', 0.4);
      ctx.beginPath();
      ctx.arc(0, 0, 6, 0, Utils.TAU);
      ctx.fill();
    }

    ctx.restore();

    // 炮塔
    for (let i = 0; i < this.turrets.length; i++) {
      this.turrets[i].draw(ctx);
    }

    // 受伤红色闪烁
    if (this.invincible > 0 && this.state !== 'dead' && Math.floor(this.age * 30) % 2 === 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.3;
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Utils.TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  // ===== Boss 1：小狗戴帽（惊讶表情）=====
  _drawDogBoss(ctx, r, phaseColor) {
    // 身体（白色）
    ctx.fillStyle = '#f5f0e8';
    ctx.beginPath();
    ctx.ellipse(0, 10, r * 0.75, r * 0.85, 0, 0, Utils.TAU);
    ctx.fill();
    // 头（更大的白圆）
    ctx.beginPath();
    ctx.ellipse(0, -r * 0.35, r * 0.85, r * 0.8, 0, 0, Utils.TAU);
    ctx.fill();
    // 左耳朵
    ctx.fillStyle = '#e8e0d0';
    ctx.beginPath();
    ctx.ellipse(-r * 0.7, -r * 0.55, r * 0.22, r * 0.38, -0.3, 0, Utils.TAU);
    ctx.fill();
    // 右耳朵
    ctx.beginPath();
    ctx.ellipse(r * 0.7, -r * 0.55, r * 0.22, r * 0.38, 0.3, 0, Utils.TAU);
    ctx.fill();
    // 蓝色帽子
    ctx.fillStyle = '#2b5a8c';
    ctx.beginPath();
    ctx.ellipse(0, -r * 0.85, r * 0.85, r * 0.22, 0, 0, Utils.TAU);
    ctx.fill();
    ctx.fillStyle = '#3a70a8';
    ctx.beginPath();
    ctx.arc(0, -r * 0.95, r * 0.45, Math.PI, Utils.TAU);
    ctx.fill();
    // 大眼白
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(-r * 0.3, -r * 0.3, r * 0.2, 0, Utils.TAU);
    ctx.arc(r * 0.3, -r * 0.3, r * 0.2, 0, Utils.TAU);
    ctx.fill();
    // 黑眼珠（瞪大）
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(-r * 0.3, -r * 0.28, r * 0.11, 0, Utils.TAU);
    ctx.arc(r * 0.3, -r * 0.28, r * 0.11, 0, Utils.TAU);
    ctx.fill();
    // 鼻子
    ctx.fillStyle = '#2a2a2a';
    ctx.beginPath();
    ctx.ellipse(0, -r * 0.02, r * 0.13, r * 0.1, 0, 0, Utils.TAU);
    ctx.fill();
    // 张嘴（惊讶 O 型）
    ctx.fillStyle = '#c44a5a';
    ctx.beginPath();
    ctx.ellipse(0, r * 0.25, r * 0.12, r * 0.16, 0, 0, Utils.TAU);
    ctx.fill();
    // 舌头
    ctx.fillStyle = '#e88a9a';
    ctx.beginPath();
    ctx.ellipse(0, r * 0.32, r * 0.07, r * 0.06, 0, 0, Utils.TAU);
    ctx.fill();
    // 胡须
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-r * 0.25, r * 0.05); ctx.lineTo(-r * 0.6, r * 0.02);
    ctx.moveTo(-r * 0.25, r * 0.12); ctx.lineTo(-r * 0.55, r * 0.14);
    ctx.moveTo(r * 0.25, r * 0.05); ctx.lineTo(r * 0.6, r * 0.02);
    ctx.moveTo(r * 0.25, r * 0.12); ctx.lineTo(r * 0.55, r * 0.14);
    ctx.stroke();
  }

  // ===== Boss 2：黄牛（牛来）=====
  _drawCowBoss(ctx, r, phaseColor) {
    // 头（黄色）
    ctx.fillStyle = '#f0c020';
    ctx.beginPath();
    ctx.ellipse(0, 0, r * 0.9, r * 0.85, 0, 0, Utils.TAU);
    ctx.fill();
    // 牛角（左）
    ctx.fillStyle = '#c8c0a8';
    ctx.beginPath();
    ctx.moveTo(-r * 0.5, -r * 0.7);
    ctx.quadraticCurveTo(-r * 0.9, -r * 1.1, -r * 0.7, -r * 0.5);
    ctx.closePath();
    ctx.fill();
    // 牛角（右）
    ctx.beginPath();
    ctx.moveTo(r * 0.5, -r * 0.7);
    ctx.quadraticCurveTo(r * 0.9, -r * 1.1, r * 0.7, -r * 0.5);
    ctx.closePath();
    ctx.fill();
    // 耳朵
    ctx.fillStyle = '#d8a818';
    ctx.beginPath();
    ctx.ellipse(-r * 0.85, -r * 0.1, r * 0.2, r * 0.35, -0.4, 0, Utils.TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(r * 0.85, -r * 0.1, r * 0.2, r * 0.35, 0.4, 0, Utils.TAU);
    ctx.fill();
    // 眉毛（不爽）
    ctx.strokeStyle = '#5a4010';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(-r * 0.45, -r * 0.3); ctx.lineTo(-r * 0.1, -r * 0.22);
    ctx.moveTo(r * 0.45, -r * 0.3); ctx.lineTo(r * 0.1, -r * 0.22);
    ctx.stroke();
    // 眼睛（半眯不爽）
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.ellipse(-r * 0.25, -r * 0.08, r * 0.12, r * 0.08, 0, 0, Utils.TAU);
    ctx.ellipse(r * 0.25, -r * 0.08, r * 0.12, r * 0.08, 0, 0, Utils.TAU);
    ctx.fill();
    // 鼻吻部（米色）
    ctx.fillStyle = '#e8d8b0';
    ctx.beginPath();
    ctx.ellipse(0, r * 0.35, r * 0.45, r * 0.35, 0, 0, Utils.TAU);
    ctx.fill();
    // 鼻孔
    ctx.fillStyle = '#8a6a30';
    ctx.beginPath();
    ctx.ellipse(-r * 0.12, r * 0.35, r * 0.06, r * 0.08, 0, 0, Utils.TAU);
    ctx.ellipse(r * 0.12, r * 0.35, r * 0.06, r * 0.08, 0, 0, Utils.TAU);
    ctx.fill();
    // "牛来" 嘴部文字感
    ctx.fillStyle = '#5a4010';
    ctx.font = `bold ${Math.round(r * 0.32)}px "Microsoft YaHei", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('牛来', 0, r * 0.75);
  }

  // ===== Boss 3：黄袋鼠（胆子真是肥嘟嘟的）=====
  _drawKangarooBoss(ctx, r, phaseColor) {
    // 身体（黄色）
    ctx.fillStyle = '#f5c830';
    ctx.beginPath();
    ctx.ellipse(0, r * 0.1, r * 0.8, r * 0.85, 0, 0, Utils.TAU);
    ctx.fill();
    // 肚子（浅黄）
    ctx.fillStyle = '#fae890';
    ctx.beginPath();
    ctx.ellipse(0, r * 0.2, r * 0.45, r * 0.5, 0, 0, Utils.TAU);
    ctx.fill();
    // 头
    ctx.fillStyle = '#f5c830';
    ctx.beginPath();
    ctx.ellipse(0, -r * 0.55, r * 0.45, r * 0.42, 0, 0, Utils.TAU);
    ctx.fill();
    // 长耳朵
    ctx.fillStyle = '#f5c830';
    ctx.beginPath();
    ctx.ellipse(-r * 0.3, -r * 0.95, r * 0.12, r * 0.35, -0.2, 0, Utils.TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(r * 0.3, -r * 0.95, r * 0.12, r * 0.35, 0.2, 0, Utils.TAU);
    ctx.fill();
    // 耳朵内粉
    ctx.fillStyle = '#f0a0a0';
    ctx.beginPath();
    ctx.ellipse(-r * 0.3, -r * 0.92, r * 0.06, r * 0.22, -0.2, 0, Utils.TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(r * 0.3, -r * 0.92, r * 0.06, r * 0.22, 0.2, 0, Utils.TAU);
    ctx.fill();
    // 大眼白
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(-r * 0.18, -r * 0.6, r * 0.13, 0, Utils.TAU);
    ctx.arc(r * 0.18, -r * 0.6, r * 0.13, 0, Utils.TAU);
    ctx.fill();
    // 黑眼珠
    ctx.fillStyle = '#3a2010';
    ctx.beginPath();
    ctx.arc(-r * 0.18, -r * 0.58, r * 0.07, 0, Utils.TAU);
    ctx.arc(r * 0.18, -r * 0.58, r * 0.07, 0, Utils.TAU);
    ctx.fill();
    // 大鼻子
    ctx.fillStyle = '#a05a30';
    ctx.beginPath();
    ctx.ellipse(0, -r * 0.35, r * 0.16, r * 0.12, 0, 0, Utils.TAU);
    ctx.fill();
    // 嘴
    ctx.strokeStyle = '#7a4020';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -r * 0.22); ctx.lineTo(0, -r * 0.1);
    ctx.moveTo(0, -r * 0.1); ctx.quadraticCurveTo(-r * 0.1, 0, -r * 0.15, -r * 0.05);
    ctx.moveTo(0, -r * 0.1); ctx.quadraticCurveTo(r * 0.1, 0, r * 0.15, -r * 0.05);
    ctx.stroke();
    // 小手（掐腰）
    ctx.fillStyle = '#f5c830';
    ctx.beginPath();
    ctx.ellipse(-r * 0.5, r * 0.15, r * 0.18, r * 0.25, -0.5, 0, Utils.TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(r * 0.5, r * 0.15, r * 0.18, r * 0.25, 0.5, 0, Utils.TAU);
    ctx.fill();
    // 尾巴
    ctx.fillStyle = '#f0b820';
    ctx.beginPath();
    ctx.moveTo(r * 0.6, r * 0.4);
    ctx.quadraticCurveTo(r * 1.2, r * 0.3, r * 1.0, r * 0.8);
    ctx.quadraticCurveTo(r * 0.8, r * 0.7, r * 0.5, r * 0.6);
    ctx.closePath();
    ctx.fill();
  }
}

// ===== Boss 炮塔 =====
class BossTurret extends Entity {
  constructor(boss, cfg) {
    super(boss.x + cfg.offsetX, boss.y + cfg.offsetY);
    this.boss = boss;
    this.offsetX = cfg.offsetX;
    this.offsetY = cfg.offsetY;
    this.hp = cfg.hp;
    this.maxHp = cfg.hp;
    this.color = cfg.color;
    this.pattern = cfg.pattern;
    this.count = cfg.count;
    this.spread = cfg.spread;
    this.arms = cfg.arms;
    this.fireRate = cfg.fireRate;
    this.bulletSpeed = cfg.bulletSpeed;
    this.fireTimer = 0;
    this.radius = 12;
    this.dead = false;
    this.alive = true;
  }
  update(dt) {
    // 跟随 boss
    this.x = this.boss.x + this.offsetX;
    this.y = this.boss.y + this.offsetY;
    this.fireTimer -= dt;
    if (this.fireTimer <= 0) {
      this._fire();
      this.fireTimer = this.fireRate;
    }
    this.age += dt;
  }
  _fire() {
    const player = Game.player;
    let baseAngle = 90;
    if (player) baseAngle = Utils.angleFromVec(player.x - this.x, player.y - this.y);
    if (this.pattern === 'fan') {
      const count = this.count || 5;
      const spread = this.spread || 60;
      const half = (count - 1) / 2;
      for (let i = 0; i < count; i++) {
        const offset = (i - half) * spread / Math.max(1, half);
        EnemyBulletPool.spawnAt(this.x, this.y, baseAngle + offset, this.bulletSpeed, {
          color: this.color, radius: 5,
        });
      }
    } else if (this.pattern === 'spiral') {
      const arms = this.arms || 2;
      for (let a = 0; a < arms; a++) {
        const ang = (this.age * 80 + a * (360 / arms)) % 360;
        EnemyBulletPool.spawnAt(this.x, this.y, ang, this.bulletSpeed, {
          color: this.color, radius: 5,
        });
      }
    }
  }
  damage(amount) {
    this.hp -= amount;
    if (this.hp <= 0) {
      this.dead = true;
      this.alive = false;
      if (Game.particles) Game.particles.spawnExplosion(this.x, this.y, this.color, 16);
      if (Game.audio) Game.audio.play('explode');
    }
  }
  draw(ctx) {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.shadowBlur = 12;
    ctx.shadowColor = this.color;
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.arc(0, 0, this.radius, 0, Utils.TAU);
    ctx.fill();
    // 炮口
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(0, 0, 4, 0, Utils.TAU);
    ctx.fill();
    // 血条
    if (this.hp < this.maxHp) {
      ctx.shadowBlur = 0;
      ctx.fillStyle = 'rgba(255,255,255,0.2)';
      ctx.fillRect(-12, -18, 24, 2);
      ctx.fillStyle = '#ff3050';
      ctx.fillRect(-12, -18, 24 * (this.hp / this.maxHp), 2);
    }
    ctx.restore();
  }
}

/* Pickup.js */
// ====== src/entities/Pickup.js ======
// 道具：P/能量/Bomb/护盾/生命/僚机/武器切换

class Pickup extends Entity {
  constructor(x, y, kind) {
    super(x, y);
    this.kind = kind;  // P / energy / bomb / shield / life / option / weapon_scatter / weapon_laser / weapon_homing
    this.radius = 10;
    this.vx = (Math.random() - 0.5) * 60;
    this.vy = -50;
    this.life = 12;     // 自动消失
    this.gravity = 0;
    // 后期重力让它稳定下落
    this.maxVy = 100;
  }
  _onUpdate(dt) {
    this.life -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    // 缓慢下落，玩家可以吸过来（近距离自动吸）
    if (Game.player) {
      const d = Utils.dist(this.x, this.y, Game.player.x, Game.player.y);
      if (d < 80) {
        // 吸引
        const dx = Game.player.x - this.x;
        const dy = Game.player.y - this.y;
        const len = d || 1;
        this.vx = Utils.lerp(this.vx, dx/len * 300, 0.15);
        this.vy = Utils.lerp(this.vy, dy/len * 300, 0.15);
      } else {
        this.vy = Utils.lerp(this.vy, this.maxVy, 0.05);
        this.vx = Utils.lerp(this.vx, 0, 0.05);
      }
    }
    super._onUpdate(dt);
    // 边界
    if (this.x < this.radius) { this.x = this.radius; this.vx = Math.abs(this.vx) * 0.5; }
    if (this.x > Balance.width - this.radius) { this.x = Balance.width - this.radius; this.vx = -Math.abs(this.vx) * 0.5; }
    if (this.y > Balance.height + 20) this.dead = true;
  }
  _onDraw(ctx) {
    const colors = {
      P: '#ffaa00', energy: '#9b5cff', bomb: '#00f0ff', shield: '#00f0ff',
      life: '#00ff80', option: '#ffe000', weapon_scatter: '#ffaa00',
      weapon_laser: '#00f0ff', weapon_homing: '#9b5cff',
    };
    const color = colors[this.kind] || '#ffffff';
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.age * 1.5);
    ctx.shadowBlur = 14;
    ctx.shadowColor = color;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    // 六边形外框
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Utils.TAU;
      const px = Math.cos(a) * 10;
      const py = Math.sin(a) * 10;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.fillStyle = Utils.hexToRgba(color, 0.2);
    ctx.fill();
    // 内部图标（不旋转）
    ctx.rotate(-this.age * 1.5);
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 10px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const label = this._label();
    ctx.fillText(label, 0, 0);
    ctx.restore();
  }
  _label() {
    const map = {
      P: 'P', energy: 'E', bomb: 'B', shield: 'S', life: '1',
      option: 'O', weapon_scatter: 'SC', weapon_laser: 'LA', weapon_homing: 'HO',
    };
    return map[this.kind] || '?';
  }
}

/* ParticleSystem.js */
// ====== src/systems/ParticleSystem.js ======
// 粒子系统：爆炸/火花/冲击波/文字飘字

const ParticleSystem = {
  pool: [],
  maxPool: 600,
  // 文字飘字
  texts: [],

  init(size = 600) {
    this.pool = [];
    this.maxPool = size;
    for (let i = 0; i < size; i++) {
      this.pool.push(this._makeParticle());
    }
  },

  _makeParticle() {
    return {
      x: 0, y: 0, vx: 0, vy: 0,
      life: 0, maxLife: 1,
      size: 2, color: '#fff',
      gravity: 0, friction: 1,
      type: 'spark',  // spark / debris / shockwave / smoke
      rotation: 0, spin: 0,
      active: false,
    };
  },

  _spawn(opts) {
    let p = null;
    for (let i = 0; i < this.pool.length; i++) {
      if (!this.pool[i].active) { p = this.pool[i]; break; }
    }
    if (!p) {
      if (this.pool.length >= this.maxPool) return null;
      p = this._makeParticle();
      this.pool.push(p);
    }
    Object.assign(p, {
      x: opts.x || 0, y: opts.y || 0,
      vx: opts.vx || 0, vy: opts.vy || 0,
      life: opts.maxLife || 1, maxLife: opts.maxLife || 1,
      size: opts.size || 2, color: opts.color || '#fff',
      gravity: opts.gravity || 0, friction: opts.friction || 1,
      type: opts.type || 'spark',
      rotation: opts.rotation || 0, spin: opts.spin || 0,
      active: true,
    });
    return p;
  },

  // 爆炸：碎片 + 火花（缩短寿命，避免特效拖沓）
  spawnExplosion(x, y, color = '#ffaa00', count = 16) {
    for (let i = 0; i < count; i++) {
      const ang = Math.random() * Utils.TAU;
      const speed = 80 + Math.random() * 220;
      this._spawn({
        x, y, vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
        maxLife: 0.25 + Math.random() * 0.3, size: 2 + Math.random() * 3,
        color, gravity: 200, friction: 0.92, type: i % 2 ? 'debris' : 'spark',
        spin: (Math.random() - 0.5) * 10,
      });
    }
    // 火花
    for (let i = 0; i < count / 2; i++) {
      const ang = Math.random() * Utils.TAU;
      const speed = 200 + Math.random() * 300;
      this._spawn({
        x, y, vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
        maxLife: 0.12 + Math.random() * 0.12, size: 1,
        color: '#ffffff', friction: 0.85, type: 'spark',
      });
    }
  },

  // 短粒子环
  spawnBurst(x, y, color = '#fff', count = 12) {
    for (let i = 0; i < count; i++) {
      const ang = (i / count) * Utils.TAU + Math.random() * 0.3;
      const speed = 100 + Math.random() * 150;
      this._spawn({
        x, y, vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed,
        maxLife: 0.25, size: 2, color, friction: 0.9, type: 'spark',
      });
    }
  },

  // 冲击波环
  spawnShockwave(x, y, color = '#fff') {
    this._spawn({
      x, y, vx: 0, vy: 0,
      maxLife: 0.35, size: 10, color, type: 'shockwave',
    });
  },

  // 擦弹闪光
  spawnGrazeFx(x, y) {
    for (let i = 0; i < 4; i++) {
      this._spawn({
        x: x + Utils.rndRange(-4, 4), y: y + Utils.rndRange(-4, 4),
        vx: Utils.rndRange(-50, 50), vy: Utils.rndRange(-50, 50),
        maxLife: 0.25, size: 1.5, color: '#ffffff', friction: 0.9, type: 'spark',
      });
    }
  },

  // 文字飘字
  spawnText(x, y, text, color = '#00f0ff') {
    this.texts.push({
      x, y, text, color, life: 1.0, maxLife: 1.0, vy: -50,
    });
    if (this.texts.length > 30) this.texts.shift();
  },

  update(dt) {
    for (let i = 0; i < this.pool.length; i++) {
      const p = this.pool[i];
      if (!p.active) continue;
      p.life -= dt;
      if (p.life <= 0) { p.active = false; continue; }
      p.vx *= p.friction;
      p.vy *= p.friction;
      p.vy += p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rotation += p.spin * dt;
    }
    // 文字
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      t.y += t.vy * dt;
      t.vy *= 0.95;
      if (t.life <= 0) this.texts.splice(i, 1);
    }
  },

  draw(ctx) {
    ctx.save();
    for (let i = 0; i < this.pool.length; i++) {
      const p = this.pool[i];
      if (!p.active) continue;
      const a = p.life / p.maxLife;
      ctx.globalAlpha = a;
      ctx.shadowBlur = 4;
      ctx.shadowColor = p.color;
      if (p.type === 'shockwave') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3 * a;
        ctx.beginPath();
        ctx.arc(p.x, p.y, (1 - a) * 80, 0, Utils.TAU);
        ctx.stroke();
      } else if (p.type === 'debris') {
        ctx.fillStyle = p.color;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rotation);
        ctx.fillRect(-p.size, -p.size, p.size * 2, p.size * 2);
        ctx.restore();
      } else {
        // spark
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Utils.TAU);
        ctx.fill();
      }
    }
    // 文字
    ctx.shadowBlur = 6;
    for (let i = 0; i < this.texts.length; i++) {
      const t = this.texts[i];
      ctx.globalAlpha = t.life / t.maxLife;
      ctx.shadowColor = t.color;
      ctx.fillStyle = t.color;
      ctx.font = 'bold 16px Orbitron, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(t.text, t.x, t.y);
    }
    ctx.restore();
  },

  clear() {
    for (let i = 0; i < this.pool.length; i++) this.pool[i].active = false;
    this.texts = [];
  },
};

/* AudioSystem.js */
// ====== src/systems/AudioSystem.js ======
// Web Audio API 程序化音效

const AudioSystem = {
  ctx: null,
  master: null,
  enabled: true,
  lastShoot: 0,

  init() {
    try {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.3;
      this.master.connect(this.ctx.destination);
    } catch (e) {
      this.enabled = false;
    }
  },

  // 解锁（移动端需要用户手势）
  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  },

  // 播放一个简短合成音
  _play(opts) {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = opts.type || 'square';
    osc.frequency.setValueAtTime(opts.freq || 440, t);
    if (opts.freqEnd) {
      osc.frequency.exponentialRampToValueAtTime(opts.freqEnd, t + opts.dur);
    }
    gain.gain.setValueAtTime(opts.vol || 0.3, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + opts.dur);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + opts.dur);
  },

  // 噪声爆破
  _playNoise(dur, vol = 0.3, filterFreq = 1000) {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime;
    const bufferSize = this.ctx.sampleRate * dur;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = filterFreq;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    noise.start(t);
    noise.stop(t + dur);
  },

  play(name) {
    if (!this.enabled || !this.ctx) return;
    switch (name) {
      case 'shoot':
        // 节流
        const now = performance.now();
        if (now - this.lastShoot < 50) return;
        this.lastShoot = now;
        this._play({ type: 'square', freq: 880, freqEnd: 220, dur: 0.06, vol: 0.06 });
        break;
      case 'enemyShoot':
        this._play({ type: 'sawtooth', freq: 200, freqEnd: 100, dur: 0.08, vol: 0.08 });
        break;
      case 'explode':
        this._playNoise(0.25, 0.25, 800);
        break;
      case 'hurt':
        this._play({ type: 'sawtooth', freq: 120, freqEnd: 40, dur: 0.4, vol: 0.3 });
        this._playNoise(0.3, 0.15, 400);
        break;
      case 'graze':
        this._play({ type: 'sine', freq: 1200, freqEnd: 1800, dur: 0.08, vol: 0.08 });
        break;
      case 'bomb':
        this._play({ type: 'sawtooth', freq: 80, freqEnd: 30, dur: 0.8, vol: 0.4 });
        this._playNoise(0.6, 0.3, 1500);
        break;
      case 'powerup':
        this._play({ type: 'sine', freq: 440, freqEnd: 880, dur: 0.15, vol: 0.2 });
        setTimeout(() => this._play({ type: 'sine', freq: 660, freqEnd: 1320, dur: 0.15, vol: 0.2 }), 60);
        break;
      case 'shield':
        this._play({ type: 'sine', freq: 300, freqEnd: 600, dur: 0.2, vol: 0.25 });
        break;
      case 'death':
        this._play({ type: 'sawtooth', freq: 200, freqEnd: 30, dur: 1.0, vol: 0.4 });
        this._playNoise(0.8, 0.25, 600);
        break;
      case 'toggle':
        this._play({ type: 'square', freq: 660, dur: 0.05, vol: 0.1 });
        break;
      case 'summon':
        this._play({ type: 'square', freq: 110, freqEnd: 220, dur: 0.3, vol: 0.2 });
        break;
      case 'warning':
        this._play({ type: 'square', freq: 440, dur: 0.1, vol: 0.2 });
        setTimeout(() => this._play({ type: 'square', freq: 440, dur: 0.1, vol: 0.2 }), 200);
        break;
      case 'boss_die':
        this._play({ type: 'sawtooth', freq: 200, freqEnd: 30, dur: 1.5, vol: 0.5 });
        this._playNoise(1.2, 0.4, 1500);
        break;
      case 'victory_melody':
        // 通关进入下一关的激昂胜利旋律（原创合成，致敬振奋感）
        this._playVictoryMelody();
        return true;
    }
    return false;
  },

  // ===== Web Speech API 语音合成（用于 Boss 胜利专属台词）=====
  speak(text, opts = {}) {
    if (!('speechSynthesis' in window)) return false;
    try {
      window.speechSynthesis.cancel(); // 停止之前的
      const u = new SpeechSynthesisUtterance(text);
      u.lang = opts.lang || 'zh-CN';
      u.rate = opts.rate || 1.1;
      u.pitch = opts.pitch || 1.0;
      u.volume = opts.volume || 0.75;
      window.speechSynthesis.speak(u);
      return true;
    } catch (e) {
      return false;
    }
  },

  // Boss 胜利专属语音（根据 character 类型）
  bossVictory(boss) {
    if (!boss) return;
    const cfg = boss.config;
    // 先播放合成音效（牛叫声等）
    if (cfg.character === 'cow') {
      // 合成牛叫声：低频锯齿波下滑
      this._playCowMoo();
      // 延迟说话
      setTimeout(() => this.speak(cfg.victorySpeech || '牛来', { rate: 0.9, pitch: 0.8 }), 800);
    } else if (cfg.character === 'dog') {
      // 先播放一个上扬的合成音
      this._play({ type: 'square', freq: 400, freqEnd: 800, dur: 0.15, vol: 0.2 });
      setTimeout(() => this.speak(cfg.victorySpeech || '爷们牛逼', { rate: 1.2, pitch: 1.1 }), 300);
    } else if (cfg.character === 'kangaroo') {
      this._play({ type: 'triangle', freq: 300, freqEnd: 600, dur: 0.2, vol: 0.2 });
      setTimeout(() => this.speak(cfg.victorySpeech || '你胆子真是肥嘟嘟的', { rate: 1.0, pitch: 0.9 }), 400);
    } else {
      this.speak(cfg.victorySpeech || '胜利', {});
    }
  },

  // 合成牛叫声
  _playCowMoo() {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(180, t);
    osc.frequency.exponentialRampToValueAtTime(90, t + 1.2);
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(600, t);
    filter.frequency.exponentialRampToValueAtTime(300, t + 1.2);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.4, t + 0.1);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 1.3);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + 1.3);
  },

  // 通关进入下一关：原创凯旋旋律
  // 多轨合成：主旋律(双osc叠加+低通) + 三度和声 + walking bass + 进行曲鼓点 + 简易reverb
  _playVictoryMelody() {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + 0.08;
    // BPM 120，四分音符 = 0.5s
    const beat = 0.5;

    // 频率表（Hz）
    const N = {
      C2: 65.41, D2: 73.42, E2: 82.41, F2: 87.31, G2: 98.00, A2: 110.00,
      C3: 130.81, D3: 146.83, E3: 164.81, F3: 174.61, G3: 196.00, A3: 220.00,
      C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392.00, A4: 440.00, B4: 493.88,
      C5: 523.25, D5: 587.33, E5: 659.25, F5: 698.46, G5: 783.99, A5: 880.00, B5: 987.77,
      C6: 1046.50, D6: 1174.66, E6: 1318.51, F6: 1396.91, G6: 1567.98, A6: 1760.00,
    };

    // 主旋律（C 大调凯旋动机）：琶音前奏 → 回旋 → 上行蓄势 → 高音长音收尾
    const melody = [
      // 前奏琶音（快速上行确立胜利感）
      [N.C5, 0.00, 0.25], [N.E5, 0.25, 0.25], [N.G5, 0.50, 0.25], [N.C6, 0.75, 0.25],
      // A 段：主音回旋
      [N.C6, 1.00, 0.5], [N.G5, 1.50, 0.5], [N.E5, 2.00, 0.5], [N.G5, 2.50, 0.5],
      // B 段：下行回落（引入下属色彩）
      [N.A5, 3.00, 0.5], [N.G5, 3.50, 0.5], [N.E5, 4.00, 0.5], [N.C5, 4.50, 0.5],
      // C 段：上行蓄势
      [N.D5, 5.00, 0.5], [N.E5, 5.50, 0.5], [N.G5, 6.00, 0.5], [N.A5, 6.50, 0.5],
      // 高潮：高音长音收尾
      [N.C6, 7.00, 0.5], [N.E6, 7.50, 0.5], [N.G6, 8.00, 1.5], [N.E6, 9.50, 0.5], [N.C6, 10.00, 0.5], [N.G6, 10.50, 2.0],
    ];

    // 三度和声（每个主旋律音下方三度，增加厚度）
    const harmony = [
      [N.A4, 0.00, 0.25], [N.C5, 0.25, 0.25], [N.E5, 0.50, 0.25], [N.A5, 0.75, 0.25],
      [N.A5, 1.00, 0.5], [N.E5, 1.50, 0.5], [N.C5, 2.00, 0.5], [N.E5, 2.50, 0.5],
      [N.F5, 3.00, 0.5], [N.E5, 3.50, 0.5], [N.C5, 4.00, 0.5], [N.A4, 4.50, 0.5],
      [N.B4, 5.00, 0.5], [N.C5, 5.50, 0.5], [N.E5, 6.00, 0.5], [N.F5, 6.50, 0.5],
      [N.A5, 7.00, 0.5], [N.C6, 7.50, 0.5], [N.E6, 8.00, 1.5], [N.C6, 9.50, 0.5], [N.A5, 10.00, 0.5], [N.E6, 10.50, 2.0],
    ];

    // Walking bass（2 拍换一次根音，制造进行感）
    const bass = [
      [N.C2, 0.00, 2.0],
      [N.G2, 2.00, 2.0],
      [N.F2, 4.00, 2.0],   // 下属色彩
      [N.G2, 6.00, 2.0],   // 属功能回到主
      [N.C2, 8.00, 2.0],
      [N.G2, 10.00, 2.5],
    ];

    // ===== 混音总线 =====
    // 简易 reverb：delay + feedback + 低通，避免高频啸叫
    const reverbDelay = ctx.createDelay(1.0);
    reverbDelay.delayTime.value = 0.09;
    const reverbFB = ctx.createGain();
    reverbFB.gain.value = 0.38;
    const reverbLP = ctx.createBiquadFilter();
    reverbLP.type = 'lowpass';
    reverbLP.frequency.value = 2200;
    const reverbSend = ctx.createGain();
    reverbSend.gain.value = 0.0;          // send 母线，每个音按需提升
    const reverbReturn = ctx.createGain();
    reverbReturn.gain.value = 0.35;       // 返回总音量
    // 路由：send -> delay -> lp -> fb -> delay (循环) -> return -> master
    reverbSend.connect(reverbDelay);
    reverbDelay.connect(reverbLP);
    reverbLP.connect(reverbFB);
    reverbFB.connect(reverbDelay);
    reverbDelay.connect(reverbReturn);
    reverbReturn.connect(this.master);

    // 主旋律：双 osc 叠加 + detune + 低通，音色厚实温暖
    this._scheduleLead(melody, t0, beat, {
      vol: 0.20, attack: 0.015, release: 0.08, cutoff: 3500, sendReverb: 0.22,
      reverbSend,
    });
    // 和声：triangle，音量小，少量 reverb
    this._scheduleLead(harmony, t0, beat, {
      vol: 0.10, attack: 0.02, release: 0.06, cutoff: 2600, sendReverb: 0.15,
      reverbSend,
      types: ['triangle'],
      detune: 0,
    });
    // bass：square + 强低通，送少量 reverb
    this._scheduleLead(bass, t0, beat, {
      vol: 0.16, attack: 0.008, release: 0.10, cutoff: 450, sendReverb: 0.08,
      reverbSend,
      types: ['square'],
      detune: 0,
    });

    // 进行曲鼓点（总长约 12.5 拍 = 6.25s）
    this._scheduleDrumKit(t0, beat, 12.5);

    // 收尾：1 秒后衰减 reverb 反馈，防止尾音无限
    const stopAt = t0 + 12.5 * beat + 1.5;
    reverbFB.gain.setValueAtTime(0.38, stopAt - 0.3);
    reverbFB.gain.linearRampToValueAtTime(0.0, stopAt);
  },

  // 单音多 osc 叠加 + 低通 + reverb send
  _scheduleLead(notes, t0, beat, opts) {
    const ctx = this.ctx;
    const types = opts.types || ['sawtooth', 'triangle'];
    const detunes = types.length > 1 ? [-7, 7] : [0];
    for (const [freq, startBeat, durBeat] of notes) {
      const start = t0 + startBeat * beat;
      const dur = durBeat * beat;
      const out = ctx.createGain();
      out.gain.value = 0;
      // 低通滤波（音色温暖）
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = opts.cutoff || 3000;
      filter.Q.value = 0.8;
      // ADSR 包络
      const vol = opts.vol || 0.15;
      out.gain.setValueAtTime(0.0001, start);
      out.gain.exponentialRampToValueAtTime(vol, start + opts.attack);
      out.gain.setValueAtTime(vol, start + dur * 0.55);
      out.gain.exponentialRampToValueAtTime(0.0001, start + dur + (opts.release || 0.05));
      // 叠加 osc
      for (let k = 0; k < types.length; k++) {
        const osc = ctx.createOscillator();
        osc.type = types[k];
        osc.frequency.setValueAtTime(freq, start);
        osc.detune.value = detunes[k] || 0;
        osc.connect(filter);
        osc.start(start);
        osc.stop(start + dur + (opts.release || 0.05) + 0.02);
      }
      filter.connect(out);
      out.connect(this.master);
      // reverb send
      if (opts.sendReverb && opts.reverbSend) {
        const sendGain = ctx.createGain();
        sendGain.gain.value = opts.sendReverb;
        out.connect(sendGain);
        sendGain.connect(opts.reverbSend);
      }
    }
  },

  // 进行曲鼓点：底鼓 + 军鼓 + 踩镲
  _scheduleDrumKit(t0, beat, totalBeats) {
    const ctx = this.ctx;
    for (let i = 0; i < totalBeats; i++) {
      const start = t0 + i * beat;
      const half = start + beat * 0.5;

      // 每拍底鼓
      this._kick(start);
      // 拍 2、4（i=1,3,5,7...）加军鼓
      if (i % 2 === 1) this._snare(start);
      // 每拍后半加踩镲（高频噪声短促）
      this._hihat(half, 0.06);
      // 强拍（每 4 拍的第一拍）底鼓更重 + 多加一个踩镲
      if (i % 4 === 0) this._hihat(start, 0.05);
    }
  },

  // 底鼓：低频正弦快速衰减 + 轻微高频点击层
  _kick(start) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, start);
    osc.frequency.exponentialRampToValueAtTime(45, start + 0.13);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(0.32, start + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.22);
    osc.connect(gain); gain.connect(this.master);
    osc.start(start); osc.stop(start + 0.25);
  },

  // 军鼓：噪声 + 高通 + 短衰减
  _snare(start) {
    const ctx = this.ctx;
    const dur = 0.16;
    const bufferSize = Math.floor(ctx.sampleRate * dur);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let j = 0; j < bufferSize; j++) {
      // 指数衰减包络的噪声
      const env = 1 - j / bufferSize;
      data[j] = (Math.random() * 2 - 1) * env * env;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 1400;
    const gain = ctx.createGain();
    gain.gain.value = 0.22;
    noise.connect(hp); hp.connect(gain); gain.connect(this.master);
    noise.start(start); noise.stop(start + dur + 0.02);
  },

  // 踩镲：高频噪声极短衰减
  _hihat(start, vol = 0.08) {
    const ctx = this.ctx;
    const dur = 0.05;
    const bufferSize = Math.floor(ctx.sampleRate * dur);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let j = 0; j < bufferSize; j++) {
      const env = 1 - j / bufferSize;
      data[j] = (Math.random() * 2 - 1) * env;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 6000;
    const gain = ctx.createGain();
    gain.gain.value = vol;
    noise.connect(hp); hp.connect(gain); gain.connect(this.master);
    noise.start(start); noise.stop(start + dur + 0.02);
  },
};

/* ScoreSystem.js */
// ====== src/systems/ScoreSystem.js ======
// 分数、连击、星级

const ScoreSystem = {
  score: 0,
  combo: 0,             // 连续击杀数
  comboMultiplier: 1,
  comboTimer: 0,
  maxMultiplier: Balance.combo.maxMultiplier,
  kills: 0,
  escaped: 0,
  grazeCount: 0,
  totalEnemies: 0,      // 关卡总敌人数（用于全灭判定）
  stageTime: 0,
  stageStartTime: 0,
  tookDamage: false,    // 关卡是否受过伤
  mult: 1,              // 全局得分倍率（每日挑战词条）
  coinMult: 1,          // 全局金币倍率

  reset() {
    this.score = 0;
    this.combo = 0;
    this.comboMultiplier = 1;
    this.comboTimer = 0;
    this.kills = 0;
    this.escaped = 0;
    this.grazeCount = 0;
    this.tookDamage = false;
    this.stageStartTime = performance.now() / 1000;
    this.stageTime = 0;
  },

  // 局开始时设置倍率（不影响跨关 reset）
  setMult(mult, coinMult) {
    this.mult = mult || 1;
    this.coinMult = coinMult || 1;
  },

  // 关卡开始时调用，传入总敌人数（包含 Boss）
  startStage(totalEnemies) {
    this.totalEnemies = totalEnemies || 0;
    this.kills = 0;
    this.escaped = 0;
    this.grazeCount = 0;
    this.tookDamage = false;
    this.combo = 0;
    this.comboMultiplier = 1;
    this.comboTimer = 0;
    this.stageStartTime = performance.now() / 1000;
  },

  update(dt) {
    this.stageTime = performance.now() / 1000 - this.stageStartTime;
    // 连击计时
    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) {
        this.combo = 0;
        this.comboMultiplier = 1;
      }
    }
  },

  addKill(enemy) {
    this.kills++;
    this.combo++;
    if (this.combo > 1) {
      this.comboMultiplier = Math.min(this.maxMultiplier, this.combo);
    }
    this.comboTimer = Balance.combo.graceTime;
    const gain = Math.floor(enemy.scoreValue * this.comboMultiplier * this.mult);
    this.score += gain;
    if (Game.particles) {
      Game.particles.spawnText(enemy.x, enemy.y, '+' + gain, '#00f0ff');
    }
    // 金币奖励
    if (Game.addCoins) {
      const cr = Balance.coin ? Balance.coin.rewards[enemy.type] : 0;
      const base = cr !== undefined ? cr : (Balance.coin ? Balance.coin.defaultReward : 0);
      Game.addCoins(Math.round(base * this.coinMult));
    }
    // 同步到数据统计
    if (Game.stats) Game.stats.onKill(enemy);
  },

  addScore(amount) {
    this.score += amount;
  },

  addGraze() {
    this.grazeCount++;
    this.score += Balance.combo.grazeScore;
    if (Game.stats) Game.stats.onGraze();
  },

  markEscaped(enemy) {
    this.escaped++;
    // 不重置连击（已飞走的不算中断）
  },

  breakCombo() {
    this.combo = 0;
    this.comboMultiplier = 1;
    this.comboTimer = 0;
    this.tookDamage = true;
  },

  // 关卡结束判定星级
  computeStars(stageData, bossPerfect) {
    const stars = [];
    // 1. 无伤
    stars.push(!this.tookDamage);
    // 2. 全灭（无逃逸即可视为全灭，bomber 自爆不算玩家击杀但也不算逃逸）
    stars.push(this.escaped === 0);
    // 3. 限时
    stars.push(this.stageTime <= stageData.duration);
    // 4. Boss 完美
    stars.push(!!bossPerfect);
    return stars;
  },
};

/* Collision.js */
// ====== src/systems/Collision.js ======
// 碰撞检测：网格哈希优化

const Collision = {
  // 简单分组检测（避免实现完整网格哈希的复杂度）
  detect() {
    if (!Game.player) return;
    const player = Game.player;

    // ===== 1. 玩家子弹 vs 敌人/Boss =====
    PlayerBulletPool.forEachActive(b => {
      // vs 敌人
      for (let i = 0; i < Game.enemies.length; i++) {
        const e = Game.enemies[i];
        if (!e.alive) continue;
        if (Utils.circleHit(b.x, b.y, b.radius, e.x, e.y, e.radius)) {
          e.damage(b.damage, player);
          if (b.pierce === 0) { b.active = false; b.dead = true; }
          else if (b.pierce > 0) b.pierce--;
          break;
        }
      }
      // vs Boss
      if (Game.boss && Game.boss.alive && Game.boss.state !== 'intro' && Game.boss.state !== 'dead') {
        const boss = Game.boss;
        // Boss 炮塔
        for (let i = 0; i < boss.turrets.length; i++) {
          const t = boss.turrets[i];
          if (Utils.circleHit(b.x, b.y, b.radius, t.x, t.y, t.radius)) {
            t.damage(b.damage);
            if (b.pierce === 0) { b.active = false; b.dead = true; }
            else if (b.pierce > 0) b.pierce--;
            return;
          }
        }
        // Boss 主体
        if (boss.invulnerable) return; // 炮塔存活时主体免伤
        if (Utils.circleHit(b.x, b.y, b.radius, boss.x, boss.y, boss.radius)) {
          // 核心命中检测：如果子弹在核心范围内（阶段2+），伤害额外×2 已在 Boss.damage 处理
          boss.damage(b.damage, player);
          if (b.pierce === 0) { b.active = false; b.dead = true; }
          else if (b.pierce > 0) b.pierce--;
        }
      }
    });

    // ===== 2. 敌弹 vs 玩家（擦弹 + 命中） =====
    const p = player;
    EnemyBulletPool.forEachActive(b => {
      if (!p.alive) return;
      const d = Utils.dist(b.x, b.y, p.x, p.y);
      // 擦弹判定（在命中点外、擦弹半径内）
      if (d < p.grazeRadius + b.radius && d > p.hitboxRadius + b.radius) {
        // 一次擦弹：避免同一颗子弹多次擦弹，用 bullet.grazed 标记
        if (!b.grazed) {
          b.grazed = true;
          p.addGraze();
        }
      }
      // 命中
      if (d < p.hitboxRadius + b.radius) {
        p.takeDamage();
        b.active = false; b.dead = true;
      }
    });

    // ===== 3. 敌人 vs 玩家（撞击） =====
    for (let i = 0; i < Game.enemies.length; i++) {
      const e = Game.enemies[i];
      if (!e.alive) continue;
      if (Utils.circleHit(e.x, e.y, e.radius, p.x, p.y, p.hitboxRadius)) {
        p.takeDamage();
        e.damage(99, p); // 撞死敌机
      }
    }

    // ===== 4. Boss vs 玩家（撞击） =====
    if (Game.boss && Game.boss.alive && Game.boss.state === 'fight') {
      const boss = Game.boss;
      if (Utils.circleHit(boss.x, boss.y, boss.radius, p.x, p.y, p.hitboxRadius)) {
        p.takeDamage();
      }
    }

    // ===== 5. 道具拾取 =====
    for (let i = Game.pickups.length - 1; i >= 0; i--) {
      const pk = Game.pickups[i];
      if (!pk.alive) continue;
      if (Utils.circleHit(pk.x, pk.y, pk.radius + 8, p.x, p.y, p.radius)) {
        p.pickup(pk.kind);
        pk.dead = true;
      }
    }
  },
};

/* Spawner.js */
// ====== src/systems/Spawner.js ======
// 波次生成器：根据 waves 数据配置按时间生成敌人

const Spawner = {
  stageData: null,
  time: 0,
  spawnQueue: [],     // 排序后的波次
  cursor: 0,
  spawned: 0,
  bossTriggered: false,
  totalEnemies: 0,    // 关卡预计总敌人数（用于全灭判定）

  start(stageData) {
    this.stageData = stageData;
    this.time = 0;
    this.bossTriggered = false;
    this.spawnQueue = stageData.waves.slice();
    // 排序按 time
    this.spawnQueue.sort((a, b) => a.time - b.time);
    this.cursor = 0;
    this.spawned = 0;
    // 计算总敌人数（不含 Boss）
    this.totalEnemies = 0;
    for (let i = 0; i < this.spawnQueue.length; i++) {
      const w = this.spawnQueue[i];
      if (w.type) this.totalEnemies += (w.count || 1);
    }
  },

  update(dt) {
    if (this.bossTriggered) return;
    this.time += dt;

    // 触发所有 time <= 当前时间的波次
    while (this.cursor < this.spawnQueue.length) {
      const w = this.spawnQueue[this.cursor];
      if (w.time > this.time) break;

      if (w.boss) {
        // 触发 Boss
        this.bossTriggered = true;
        if (Game) Game.spawnBoss(w.boss);
        this.cursor++;
        return;
      }
      if (w.type) {
        this._spawnWave(w);
      }
      this.cursor++;
    }
  },

  _spawnWave(w) {
    const count = w.count || 1;
    const interval = w.interval || 0.3;
    // 用 setTimeout 串行生成（让敌人依次入场）
    for (let i = 0; i < count; i++) {
      const delay = i * interval * 1000;
      setTimeout(() => this._spawnOne(w), delay);
    }
  },

  _spawnOne(w) {
    if (!Game || Game.state !== 'play') return;
    const type = w.type;
    const W = Balance.width;
    let x, y;
    if (w.from === 'top' || !w.from) {
      x = Utils.rndRange(40, W - 40);
      y = -20;
    } else if (w.from === 'left') {
      x = -20; y = Utils.rndRange(40, 200);
    } else if (w.from === 'right') {
      x = W + 20; y = Utils.rndRange(40, 200);
    } else {
      x = Utils.rndRange(40, W - 40);
      y = -20;
    }

    // 阵型
    if (w.pattern === 'line' && w.count > 1 && this.spawned % w.count !== w.count - 1) {
      // 等距排列（已被 interval 处理，这里仅调整 x）
      // 简化：每个 enemy 在中部分布
      const slot = this.spawned % w.count;
      const center = W / 2;
      const spread = Math.min(w.count * 30, W - 80);
      x = center - spread / 2 + slot * (spread / Math.max(1, w.count - 1));
    }

    const e = new Enemy(type, x, y, {
      pattern: w.pattern || 'line',
      dropGuaranteed: w.dropGuaranteed || null,
      targetY: type === 'arc' || type === 'elite' ? Utils.rndRange(80, 180) : 0,
      amp: Utils.rndRange(60, 120),
      freq: Utils.rndRange(1.0, 2.0),
    });
    // 难度缩放（闯关重玩递增）
    if (Game.scaleEnemy) Game.scaleEnemy(e);
    Game.enemies.push(e);
    this.spawned++;
  },

  // 用于关卡开始前预估敌人总数
  getTotalEnemies() {
    return this.totalEnemies;
  },
};

/* SpawnerEndless.js */
// ====== src/systems/SpawnerEndless.js ======
// 无尽模式生成器：按时间程序化生成，难度阶梯递增
// 每 WAVE_TIME 秒一波，每 BOSS_INTERVAL 秒一个 Boss（HP 按 wave 缩放）

const SpawnerEndless = {
  time: 0,
  wave: 0,                  // 当前波次（1-based）
  waveTimer: 0,             // 当前波已持续时间
  bossTimer: 0,             // 距下次 Boss
  bossActive: false,
  spawnTimer: 0,            // 波内分批生成计时
  difficulty: 1,            // 难度倍率（基于 wave）
  ended: false,
  // 难度曲线（参考 Balance.endless）
  WAVE_TIME: 30,             // 每波时长
  BOSS_INTERVAL: 90,         // Boss 间隔
  // 敌人类型权重池，随难度解锁更强敌人
  _pools: {
    easy: ['grunt', 'zigzag'],
    mid: ['grunt', 'zigzag', 'arc', 'ram', 'bomber'],
    hard: ['zigzag', 'arc', 'ram', 'bomber', 'elite'],
  },

  start() {
    const cfg = Balance.endless || {};
    this.WAVE_TIME = cfg.waveTime || 30;
    this.BOSS_INTERVAL = cfg.bossInterval || 90;
    this.time = 0;
    this.wave = 0;
    this.waveTimer = 0;
    this.bossTimer = this.BOSS_INTERVAL;
    this.bossActive = false;
    this.spawnTimer = 0;
    this.difficulty = 1;
    this.ended = false;
    this._spawnNextWave();
  },

  // 当前波次的生成预算（敌人数量 / 类型池）
  _spawnNextWave() {
    this.wave++;
    this.waveTimer = 0;
    this.spawnTimer = 0;
    this.difficulty = 1 + (this.wave - 1) * 0.15;
    if (Stats) Stats.onWave(this.wave);

    // 选择敌人池
    let pool;
    if (this.wave <= 3) pool = this._pools.easy;
    else if (this.wave <= 8) pool = this._pools.mid;
    else pool = this._pools.hard;

    // 每波总敌人数
    const baseCount = 8 + this.wave * 2;
    // 每波生成 budget，分批 spawn
    this._waveBudget = baseCount;
    this._waveSpawned = 0;
    this._wavePool = pool;
    this._spawnInterval = Math.max(0.15, 0.5 - this.wave * 0.02);

    // 波次提示粒子
    if (Game.particles && this.wave > 1) {
      Game.particles.spawnText(Balance.width / 2, Balance.height / 2 - 40, 'WAVE ' + this.wave, '#00f0ff');
    }
  },

  update(dt) {
    if (this.ended) return;
    this.time += dt;
    this.waveTimer += dt;

    // Boss 战期间停止普通生成
    if (this.bossActive) {
      if (!Game.boss || Game.boss.dead) {
        this.bossActive = false;
        this.bossTimer = this.BOSS_INTERVAL;
      }
      return;
    }

    // ===== 普通波内分批生成 =====
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0 && this._waveSpawned < this._waveBudget) {
      this._spawnBatch();
      this.spawnTimer = this._spawnInterval;
    }

    // ===== 波次结束 -> 进入下一波 =====
    if (this.waveTimer >= this.WAVE_TIME && this._waveSpawned >= this._waveBudget) {
      this._spawnNextWave();
    }

    // ===== Boss 计时 =====
    this.bossTimer -= dt;
    if (this.bossTimer <= 0 && !this.bossActive) {
      this._spawnBoss();
    }
  },

  _spawnBatch() {
    // 一次生成 2~4 个敌人
    const n = 2 + Math.floor(Math.random() * 3);
    const pool = this._wavePool;
    for (let i = 0; i < n && this._waveSpawned < this._waveBudget; i++) {
      const type = pool[Math.floor(Math.random() * pool.length)];
      this._spawnOne(type);
      this._waveSpawned++;
    }
  },

  _spawnOne(type) {
    const W = Balance.width;
    const from = Math.random();
    let x, y;
    if (from < 0.7) { x = Utils.rndRange(40, W - 40); y = -20; }
    else if (from < 0.85) { x = -20; y = Utils.rndRange(40, 200); }
    else { x = W + 20; y = Utils.rndRange(40, 200); }

    const e = new Enemy(type, x, y, {
      pattern: 'line',
      targetY: type === 'arc' || type === 'elite' ? Utils.rndRange(80, 180) : 0,
      amp: Utils.rndRange(60, 120),
      freq: Utils.rndRange(1.0, 2.0),
    });
    // 难度缩放：HP/速度
    const cfg = Balance.enemy[type] || Balance.enemy.grunt;
    e.maxHp = Math.max(1, Math.round(cfg.hp * this.difficulty));
    e.hp = e.maxHp;
    e.speed = cfg.speed * (1 + (this.difficulty - 1) * 0.5);
    Game.enemies.push(e);
  },

  _spawnBoss() {
    // 每第二个 Boss 固定为无尽专属「混沌」，其余从关卡 Boss 随机（HP 按 wave 缩放）
    this._bossCount = (this._bossCount || 0) + 1;
    let key, cfg;
    if (this._bossCount % 2 === 0) {
      key = 'boss_endless';
      cfg = BossesData.boss_endless;
    } else {
      const keys = Object.keys(BossesData).filter(k => k !== 'boss_endless');
      key = keys[Math.floor(Math.random() * keys.length)];
      cfg = BossesData[key];
    }
    const clone = JSON.parse(JSON.stringify(cfg));
    // HP 倍率：基础 + wave 增长
    const hpMult = 1 + (this.wave - 1) * 0.25;
    clone.maxHp = Math.round(cfg.maxHp * hpMult);
    // 阶段 HP 阈值保持百分比不变，无需调整
    this.bossActive = true;
    if (Game) Game.spawnBoss(undefined, clone, key);
  },

  // 关卡开始前预估敌人总数（无尽模式无意义，返回 0）
  getTotalEnemies() { return 0; },

  // 无尽模式无显式 bossTriggered 流程
  get bossTriggered() { return this.bossActive; },
};

/* SaveSystem.js */
// ====== src/systems/SaveSystem.js ======
// localStorage 持久化封装：闯关进度 / 无尽最高分 / 成就 / 统计
// 独立于游戏运行时，仅做读写

const SaveSystem = {
  KEY: 'neon_abyss_save_v1',

  // 默认存档结构
  _default() {
    return {
      version: 1,
      // 金币（武器商店货币）
      coins: 0,
      // 累计获得金币（只增不减，用于解锁）
      coinsEarnedTotal: 0,
      // 武器商店：已购永久强化 + 消耗品库存
      shop: {
        owned: [],
        consumables: {
          shield_token: 0,
          revive_token: 0,
        },
      },
      // 每日挑战：日期 + 当日最高分
      daily: {
        date: '',
        bestScore: 0,
      },
      // 本地排行榜（Top 8）
      leaderboard: [],
      // 闯关模式
      stage: {
        unlockedStages: ['stage1'],          // 已解锁关卡键名
        stars: {                              // 每关星级 [bool,bool,bool,bool]
          stage1: [false, false, false, false],
          stage2: [false, false, false, false],
          stage3: [false, false, false, false],
          stage4: [false, false, false, false],
        },
        bestStageScore: { stage1: 0, stage2: 0, stage3: 0, stage4: 0 },
        clearedAll: false,
        playCount: 0,                         // 闯关总次数（用于难度递增参考）
      },
      // 当前选中战机
      selectedPlane: 'pioneer',
      // 无尽模式
      endless: {
        bestScore: 0,
        bestTime: 0,
        bestKills: 0,
        bestWave: 0,
        playCount: 0,
      },
      // 成就
      achievements: {
        unlocked: [],                          // 已解锁 id 列表
      },
      // 全局统计
      stats: {
        totalKills: 0,
        totalScore: 0,
        totalPlayTime: 0,                       // 秒
        maxCombo: 0,
        totalGraze: 0,
        totalBombs: 0,
        totalBossKills: 0,
        totalRuns: 0,                           // 总局数
        stageClears: 0,
        endlessRuns: 0,
      },
    };
  },

  _cache: null,

  _load() {
    if (this._cache) return this._cache;
    try {
      const raw = localStorage.getItem(this.KEY);
      if (!raw) {
        this._cache = this._default();
        return this._cache;
      }
      const data = JSON.parse(raw);
      // 兼容性：合并默认字段
      const def = this._default();
      this._cache = this._merge(def, data);
      return this._cache;
    } catch (e) {
      this._cache = this._default();
      return this._cache;
    }
  },

  // 浅层合并（仅一层对象）
  _merge(def, data) {
    const out = {};
    for (const k in def) {
      if (typeof def[k] === 'object' && def[k] !== null && !Array.isArray(def[k])) {
        out[k] = this._merge(def[k], data[k] || {});
      } else {
        out[k] = data[k] !== undefined ? data[k] : def[k];
      }
    }
    return out;
  },

  _save() {
    try {
      localStorage.setItem(this.KEY, JSON.stringify(this._cache));
    } catch (e) {
      // 配额满或隐私模式，忽略
    }
  },

  // ===== 通用 =====
  getAll() { return this._load(); },
  save() { this._save(); },
  reset() {
    this._cache = this._default();
    this._save();
  },

  // ===== 闯关 =====
  isStageUnlocked(key) {
    return this._load().stage.unlockedStages.indexOf(key) >= 0;
  },
  unlockStage(key) {
    const d = this._load();
    if (d.stage.unlockedStages.indexOf(key) < 0) {
      d.stage.unlockedStages.push(key);
      this._save();
    }
  },
  getStageStars(key) {
    return this._load().stage.stars[key] || [false, false, false, false];
  },
  setStageStars(key, stars) {
    const d = this._load();
    const cur = d.stage.stars[key] || [false, false, false, false];
    let changed = false;
    for (let i = 0; i < cur.length; i++) {
      if (stars[i] && !cur[i]) { cur[i] = true; changed = true; }
    }
    d.stage.stars[key] = cur;
    if (changed) this._save();
  },
  getStageBestScore(key) {
    return this._load().stage.bestStageScore[key] || 0;
  },
  setStageBestScore(key, score) {
    const d = this._load();
    if (score > (d.stage.bestStageScore[key] || 0)) {
      d.stage.bestStageScore[key] = score;
      this._save();
    }
  },
  setClearedAll() {
    const d = this._load();
    d.stage.clearedAll = true;
    this._save();
  },
  incStagePlayCount() {
    const d = this._load();
    d.stage.playCount = (d.stage.playCount || 0) + 1;
    this._save();
    return d.stage.playCount;
  },
  getStagePlayCount() {
    return this._load().stage.playCount || 0;
  },

  // ===== 无尽 =====
  getEndlessBest() {
    return this._load().endless;
  },
  updateEndlessBest(score, time, kills, wave) {
    const d = this._load();
    let changed = false;
    if (score > d.endless.bestScore) { d.endless.bestScore = score; changed = true; }
    if (time > d.endless.bestTime) { d.endless.bestTime = time; changed = true; }
    if (kills > d.endless.bestKills) { d.endless.bestKills = kills; changed = true; }
    if (wave > d.endless.bestWave) { d.endless.bestWave = wave; changed = true; }
    if (changed) this._save();
  },
  incEndlessPlayCount() {
    const d = this._load();
    d.endless.playCount = (d.endless.playCount || 0) + 1;
    this._save();
  },

  // ===== 成就 =====
  isAchievementUnlocked(id) {
    return this._load().achievements.unlocked.indexOf(id) >= 0;
  },
  unlockAchievement(id) {
    const d = this._load();
    if (d.achievements.unlocked.indexOf(id) < 0) {
      d.achievements.unlocked.push(id);
      this._save();
      return true;    // 新解锁
    }
    return false;
  },
  getUnlockedAchievements() {
    return this._load().achievements.unlocked.slice();
  },

  // ===== 金币 =====
  getCoins() {
    return this._load().coins || 0;
  },
  addCoins(n) {
    const d = this._load();
    if (n > 0) d.coinsEarnedTotal = (d.coinsEarnedTotal || 0) + n;
    d.coins = Math.max(0, (d.coins || 0) + (n || 0));
    this._save();
    return d.coins;
  },
  // 消费金币：余额不足返回 false
  spendCoins(n) {
    const d = this._load();
    if ((d.coins || 0) < n) return false;
    d.coins -= n;
    this._save();
    return true;
  },
  getCoinsEarnedTotal() {
    return this._load().coinsEarnedTotal || 0;
  },

  // ===== 武器商店 =====
  isOwned(itemId) {
    const owned = this._load().shop.owned;
    return owned && owned.indexOf(itemId) >= 0;
  },
  // 购买：扣费 + 记录，成功返回 true
  buyItem(itemId, price) {
    if (this.isOwned(itemId)) return false;
    if (!this.spendCoins(price)) return false;
    const d = this._load();
    d.shop.owned.push(itemId);
    this._save();
    return true;
  },
  getOwnedItems() {
    const owned = this._load().shop.owned;
    return owned ? owned.slice() : [];
  },

  // ===== 消耗品 =====
  getConsumableCount(kind) {
    const c = this._load().shop.consumables;
    return (c && c[kind]) || 0;
  },
  // 购买消耗品：扣费 +1 库存，成功返回 true
  buyConsumable(kind, price) {
    if (!this.spendCoins(price)) return false;
    const d = this._load();
    if (!d.shop.consumables) d.shop.consumables = {};
    d.shop.consumables[kind] = (d.shop.consumables[kind] || 0) + 1;
    this._save();
    return true;
  },
  // 使用消耗品：有库存则 -1 并返回 true
  useConsumable(kind) {
    const d = this._load();
    if (!d.shop.consumables || !(d.shop.consumables[kind] > 0)) return false;
    d.shop.consumables[kind]--;
    this._save();
    return true;
  },

  // ===== 每日挑战 =====
  // 返回今日（本地时区）日期串 YYYY-MM-DD
  todayStr() {
    const d = new Date();
    const p = (n) => (n < 10 ? '0' + n : '' + n);
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
  },
  getDailyBest() {
    const d = this._load().daily;
    if (!d || d.date !== this.todayStr()) return 0;
    return d.bestScore || 0;
  },
  // 更新当日最高分，返回是否刷新纪录
  updateDailyBest(score) {
    const d = this._load();
    if (!d.daily || d.date !== this.todayStr()) {
      d.daily = { date: this.todayStr(), bestScore: score };
      this._save();
      return true;
    }
    if (score > (d.daily.bestScore || 0)) {
      d.daily.bestScore = score;
      this._save();
      return true;
    }
    return false;
  },

  // ===== 本地排行榜 =====
  getLeaderboard() {
    const lb = this._load().leaderboard;
    return (lb && lb.slice()) || [];
  },
  // 提交一条战绩：{score,kills,mode,stage,date}；返回名次（未上榜返回 0）
  submitLeaderboard(entry) {
    const d = this._load();
    if (!Array.isArray(d.leaderboard)) d.leaderboard = [];
    d.leaderboard.push(entry);
    d.leaderboard.sort((a, b) => (b.score || 0) - (a.score || 0));
    if (d.leaderboard.length > 8) d.leaderboard.length = 8;
    this._save();
    const idx = d.leaderboard.indexOf(entry);
    return idx >= 0 ? idx + 1 : 0;
  },

  // ===== 战机 =====
  getSelectedPlane() {
    return this._load().selectedPlane || 'pioneer';
  },
  selectPlane(key) {
    if (!Planes.isUnlocked(key)) return false;
    const d = this._load();
    d.selectedPlane = key;
    this._save();
    return true;
  },

  // ===== 统计 =====
  getStats() {
    return this._load().stats;
  },
  addStat(key, amount) {
    const d = this._load();
    d.stats[key] = (d.stats[key] || 0) + (amount || 0);
    this._save();
  },
  setStatMax(key, value) {
    const d = this._load();
    if (value > (d.stats[key] || 0)) {
      d.stats[key] = value;
      this._save();
    }
  },
};

/* ProgressSystem.js */
// ====== src/systems/ProgressSystem.js ======
// 关卡进度条：实时反映击杀进度，击败 Boss/小怪时平滑更新

const ProgressSystem = {
  el: null,        // 进度条容器
  fillEl: null,    // 填充条
  percentEl: null, // 百分比文字
  killsEl: null,   // 击杀数
  totalEl: null,   // 总数
  percent: 0,      // 当前百分比
  _smoothed: 0,    // 平滑显示值（用于数字缓动）

  init() {
    this.el = document.getElementById('stage-progress');
    this.fillEl = document.getElementById('sp-fill');
    this.percentEl = this.el ? this.el.querySelector('.sp-percent') : null;
    this.killsEl = document.getElementById('sp-kills');
    this.totalEl = document.getElementById('sp-total');
    this.percent = 0;
    this._smoothed = 0;
  },

  // 关卡开始：重置并显示
  startStage(totalEnemies) {
    this.percent = 0;
    this._smoothed = 0;
    if (this.el) this.el.classList.remove('hidden');
    if (this.totalEl) this.totalEl.textContent = totalEnemies || 0;
    this._apply(0, 0);
  },

  // 无尽模式开始：按时间/波次计进度
  startEndless() {
    this.percent = 0;
    this._smoothed = 0;
    if (this.el) this.el.classList.remove('hidden');
    if (this.totalEl) this.totalEl.textContent = '∞';
    this._apply(0, 0);
  },

  // 隐藏（菜单/结算时）
  hide() {
    if (this.el) this.el.classList.add('hidden');
  },

  // 每帧更新
  update(dt) {
    if (!this.el || this.el.classList.contains('hidden')) return;

    let kills, total;
    if (Game.mode === 'endless') {
      // 无尽模式：按存活时间计算（每 90 秒一个循环，对应一个 Boss）
      const cycle = 90;
      const elapsed = Game.score ? Game.score.stageTime : 0;
      const cycleProgress = (elapsed % cycle) / cycle;
      this.percent = Math.min(100, cycleProgress * 100);
      kills = Game.score ? Game.score.kills : 0;
      this._apply(this.percent, kills);
    } else {
      // 闯关模式：击杀数 / 总敌人数
      kills = Game.score ? Game.score.kills : 0;
      total = Game.score ? Game.score.totalEnemies : 0;
      if (total > 0) {
        this.percent = Math.min(100, (kills / total) * 100);
      }
      // Boss 已被击败 → 100%
      if (Game.state === 'stage_clear') {
        this.percent = 100;
      }
      this._apply(this.percent, kills);
    }

    // 数字平滑缓动
    this._smoothed += (this.percent - this._smoothed) * Math.min(1, dt * 6);
    if (this.percentEl) {
      this.percentEl.textContent = Math.round(this._smoothed) + '%';
    }
  },

  _apply(percent, kills) {
    if (this.fillEl) {
      this.fillEl.style.width = percent.toFixed(1) + '%';
    }
    if (this.killsEl) {
      this.killsEl.textContent = kills;
    }
  },

  // Boss 被击败：直接拉满
  onBossDefeated() {
    this.percent = 100;
    this._apply(100, Game.score ? Game.score.kills : 0);
  },
};

/* Stats.js */
// ====== src/systems/Stats.js ======
// 运行时数据统计：累计本次游戏的击杀/分数/时长/连击/擦弹等
// 在事件触发时调用对应方法，结束时统一同步到 SaveSystem

const Stats = {
  // 本局统计（每局开始重置）
  kills: 0,
  score: 0,
  startTime: 0,
  playTime: 0,
  maxCombo: 0,
  graze: 0,
  bombs: 0,
  bossKills: 0,
  wave: 0,             // 无尽模式波次
  // 累计跨局（在 end() 时同步到 SaveSystem）

  reset(mode) {
    this.mode = mode || 'stage';   // 'stage' / 'endless'
    this.kills = 0;
    this.score = 0;
    this.startTime = performance.now() / 1000;
    this.playTime = 0;
    this.maxCombo = 0;
    this.graze = 0;
    this.bombs = 0;
    this.bossKills = 0;
    this.wave = 0;
  },

  update(dt) {
    this.playTime = performance.now() / 1000 - this.startTime;
  },

  // ===== 事件接口 =====
  onKill(enemy) {
    this.kills++;
  },
  onScore(amount) {
    this.score += amount || 0;
  },
  onGraze() {
    this.graze++;
  },
  onBomb() {
    this.bombs++;
  },
  onBossKill() {
    this.bossKills++;
  },
  onCombo(combo) {
    if (combo > this.maxCombo) this.maxCombo = combo;
  },
  onWave(wave) {
    if (wave > this.wave) this.wave = wave;
  },

  // ===== 本局结束：同步到 SaveSystem =====
  end() {
    const s = SaveSystem.getStats();
    SaveSystem.addStat('totalKills', this.kills);
    SaveSystem.addStat('totalScore', this.score);
    SaveSystem.addStat('totalPlayTime', Math.floor(this.playTime));
    SaveSystem.setStatMax('maxCombo', this.maxCombo);
    SaveSystem.addStat('totalGraze', this.graze);
    SaveSystem.addStat('totalBombs', this.bombs);
    SaveSystem.addStat('totalBossKills', this.bossKills);
    SaveSystem.addStat('totalRuns', 1);
    if (this.mode === 'stage') {
      SaveSystem.addStat('stageClears', this.bossKills > 0 ? 1 : 0);
    } else {
      SaveSystem.addStat('endlessRuns', 1);
    }
  },

  // 取本局简报
  summary() {
    return {
      mode: this.mode,
      kills: this.kills,
      score: this.score,
      playTime: this.playTime,
      maxCombo: this.maxCombo,
      graze: this.graze,
      bombs: this.bombs,
      bossKills: this.bossKills,
      wave: this.wave,
    };
  },
};

/* Achievements.js */
// ====== src/systems/Achievements.js ======
// 成就系统：定义 + 解锁检测 + 解锁提示 toast
// 在事件触发时由 Game/Stats 调用 check()

const Achievements = {
  // 成就定义表
  // check(stats, game) 返回 true 表示达成
  list: [
    { id: 'first_clear',    name: '初次通关',   desc: '通关第 1 关',           icon: '★',
      check: (s) => SaveSystem.getStageStars('stage1').some(x => x) },
    { id: 'clear_all',      name: '霓虹征服者', desc: '通关全部关卡',           icon: '✦',
      check: (s) => SaveSystem.getAll().stage.clearedAll },
    { id: 'graze_100',       name: '擦弹大师',   desc: '累计擦弹 100 次',        icon: '◇',
      check: (s) => SaveSystem.getStats().totalGraze >= 100 },
    { id: 'graze_500',       name: '光速行者',   desc: '累计擦弹 500 次',        icon: '◈',
      check: (s) => SaveSystem.getStats().totalGraze >= 500 },
    { id: 'endless_5k',      name: '无尽先锋',   desc: '无尽模式得分 5000',      icon: '◉',
      check: (s) => SaveSystem.getEndlessBest().bestScore >= 5000 },
    { id: 'endless_20k',     name: '深渊行者',   desc: '无尽模式得分 20000',     icon: '◎',
      check: (s) => SaveSystem.getEndlessBest().bestScore >= 20000 },
    { id: 'endless_wave10',  name: '永夜续航',   desc: '无尽到达第 10 波',       icon: '▦',
      check: (s) => SaveSystem.getEndlessBest().bestWave >= 10 },
    { id: 'kills_500',       name: '老兵',       desc: '累计击杀 500',           icon: '✕',
      check: (s) => SaveSystem.getStats().totalKills >= 500 },
    { id: 'kills_2000',      name: '歼灭者',     desc: '累计击杀 2000',          icon: '☠',
      check: (s) => SaveSystem.getStats().totalKills >= 2000 },
    { id: 'combo_50',        name: '连击之王',   desc: '单局达成 50 连击',        icon: '⚡',
      check: (s) => SaveSystem.getStats().maxCombo >= 50 },
    { id: 'boss_5',          name: '弑神者',     desc: '累计击败 5 个 Boss',     icon: '♛',
      check: (s) => SaveSystem.getStats().totalBossKills >= 5 },
    { id: 'no_damage_stage', name: '完美无瑕',   desc: '任一关卡无伤通关',        icon: '✧',
      check: (s) => {
        const st = SaveSystem.getAll().stage.stars;
        for (const k in st) { if (st[k][0]) return true; }
        return false;
      } },
    { id: 'all_stars',       name: '霓虹至高',   desc: '集齐全部关卡 4 星',       icon: '✪',
      check: (s) => {
        const st = SaveSystem.getAll().stage.stars;
        for (const k in st) { if (st[k].some(x => !x)) return false; }
        return Object.keys(st).length > 0;
      } },
    // ---- 经济 / 商店 / 收集扩展 ----
    { id: 'coins_1k',        name: '掘金者',     desc: '累计获得 1000 金币',      icon: '◈',
      check: (s) => SaveSystem.getCoinsEarnedTotal() >= 1000 },
    { id: 'coins_10k',       name: '金币雨',     desc: '累计获得 10000 金币',     icon: '❋',
      check: (s) => SaveSystem.getCoinsEarnedTotal() >= 10000 },
    { id: 'arms_dealer',     name: '军火商',     desc: '购买任一永久强化',        icon: '⚒',
      check: (s) => SaveSystem.getOwnedItems().length >= 1 },
    { id: 'full_load',       name: '满配大师',   desc: '买齐全部 6 件永久强化',    icon: '✦',
      check: (s) => SaveSystem.getOwnedItems().length >= ShopData.allKeys.length },
    { id: 'stage4_clear',    name: '深渊突破',   desc: '通关第 4 关',             icon: '★',
      check: (s) => SaveSystem.getStageStars('stage4').some(x => x) },
    { id: 'wave_15',         name: '永夜之主',   desc: '无尽到达第 15 波',        icon: '▦',
      check: (s) => SaveSystem.getEndlessBest().bestWave >= 15 },
    { id: 'plane_all',       name: '战机收藏家', desc: '解锁全部 6 架战机',       icon: '✈',
      check: (s) => Planes.allKeys.every(k => Planes.isUnlocked(k)) },
    { id: 'daily_5k',        name: '日报之星',   desc: '每日挑战得分 5000',       icon: '✥',
      check: (s) => SaveSystem.getDailyBest() >= 5000 },
    { id: 'boss_15',         name: '屠神者',     desc: '累计击败 15 个 Boss',    icon: '♟',
      check: (s) => SaveSystem.getStats().totalBossKills >= 15 },
  ],

  _toastQueue: [],
  _toastEl: null,
  _toastTimer: 0,

  init() {
    // 创建 toast 容器（由 Menu/DOM 提供），此处只缓存引用
    this._toastEl = document.getElementById('achievement-toast') || this._createToast();
  },

  _createToast() {
    const el = document.createElement('div');
    el.id = 'achievement-toast';
    el.className = 'ach-toast hidden';
    document.getElementById('game-wrap').appendChild(el);
    return el;
  },

  // 遍历所有未解锁成就，达成则解锁并弹 toast
  checkAll() {
    for (let i = 0; i < this.list.length; i++) {
      const a = this.list[i];
      if (SaveSystem.isAchievementUnlocked(a.id)) continue;
      let ok = false;
      try { ok = a.check(); } catch (e) { ok = false; }
      if (ok) {
        SaveSystem.unlockAchievement(a.id);
        this._enqueue(a);
      }
    }
  },

  _enqueue(a) {
    this._toastQueue.push(a);
    if (this._toastQueue.length === 1) this._showNext();
  },

  _showNext() {
    if (this._toastQueue.length === 0) return;
    const a = this._toastQueue[0];
    if (!this._toastEl) this.init();
    this._toastEl.innerHTML =
      `<div class="ach-icon">${a.icon}</div>
       <div class="ach-text">
         <div class="ach-label">ACHIEVEMENT UNLOCKED</div>
         <div class="ach-name">${a.name}</div>
         <div class="ach-desc">${a.desc}</div>
       </div>`;
    this._toastEl.classList.remove('hidden');
    this._toastEl.classList.add('show');
    if (Game.audio) Game.audio.play('toggle');
    this._toastTimer = 3.0;
  },

  update(dt) {
    if (this._toastQueue.length === 0) return;
    this._toastTimer -= dt;
    if (this._toastTimer <= 0) {
      this._toastEl.classList.remove('show');
      this._toastEl.classList.add('hidden');
      this._toastQueue.shift();
      const self = this;
      setTimeout(() => self._showNext(), 200);
    }
  },

  // 统计已解锁数量
  countUnlocked() {
    let n = 0;
    for (let i = 0; i < this.list.length; i++) {
      if (SaveSystem.isAchievementUnlocked(this.list[i].id)) n++;
    }
    return n;
  },
  total() { return this.list.length; },
};

/* Background.js */
// ====== src/render/Background.js ======
// 三层视差背景：远星点 + 全息网格 + 流光粒子

const Background = {
  // 远层星点
  farStars: [],
  // 中层网格滚动
  gridScrollY: 0,
  // 近层流光粒子带
  streaks: [],

  init() {
    this.farStars = [];
    for (let i = 0; i < 80; i++) {
      this.farStars.push({
        x: Math.random() * Balance.width,
        y: Math.random() * Balance.height,
        r: Utils.rndRange(0.5, 1.5),
        speed: Utils.rndRange(0.2, 0.6),
        twinkle: Math.random() * Utils.TAU,
      });
    }
    this.streaks = [];
    for (let i = 0; i < 12; i++) {
      this.streaks.push({
        x: Math.random() * Balance.width,
        y: Math.random() * Balance.height,
        len: Utils.rndRange(20, 80),
        speed: Utils.rndRange(1.8, 3.5),
        color: Utils.pick(['#00f0ff','#9b5cff','#ff2e88']),
        alpha: Utils.rndRange(0.3, 0.8),
      });
    }
    this.gridScrollY = 0;
  },

  update(dt) {
    // 远星
    for (let i = 0; i < this.farStars.length; i++) {
      const s = this.farStars[i];
      s.y += s.speed * 60 * dt;
      s.twinkle += dt * 3;
      if (s.y > Balance.height) {
        s.y = -2;
        s.x = Math.random() * Balance.width;
      }
    }
    // 网格滚动
    this.gridScrollY += 1.0 * 60 * dt;
    if (this.gridScrollY > 64) this.gridScrollY -= 64;
    // 流光
    for (let i = 0; i < this.streaks.length; i++) {
      const s = this.streaks[i];
      s.y += s.speed * 60 * dt;
      if (s.y > Balance.height + 80) {
        s.y = -80;
        s.x = Math.random() * Balance.width;
      }
    }
  },

  draw(ctx, time) {
    // 深空底色
    const grad = ctx.createLinearGradient(0, 0, 0, Balance.height);
    grad.addColorStop(0, '#05060f');
    grad.addColorStop(0.5, '#0a0e22');
    grad.addColorStop(1, '#05060f');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, Balance.width, Balance.height);

    // 远星
    ctx.save();
    for (let i = 0; i < this.farStars.length; i++) {
      const s = this.farStars[i];
      const a = 0.5 + Math.sin(s.twinkle) * 0.3;
      ctx.globalAlpha = a;
      ctx.fillStyle = '#e8f4ff';
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Utils.TAU);
      ctx.fill();
    }
    ctx.restore();

    // 全息网格（远景地平线效果）
    ctx.save();
    ctx.globalAlpha = 0.18;
    ctx.strokeStyle = Balance.color.cyan;
    ctx.lineWidth = 1;
    const gridSize = 64;
    const offsetY = this.gridScrollY;
    for (let y = -gridSize; y < Balance.height + gridSize; y += gridSize) {
      const py = y + offsetY;
      ctx.beginPath();
      ctx.moveTo(0, py);
      ctx.lineTo(Balance.width, py);
      ctx.stroke();
    }
    for (let x = 0; x < Balance.width; x += gridSize) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, Balance.height);
      ctx.stroke();
    }
    ctx.restore();

    // 近层流光带（水平线）
    ctx.save();
    for (let i = 0; i < this.streaks.length; i++) {
      const s = this.streaks[i];
      ctx.globalAlpha = s.alpha * (0.5 + Math.sin(time * 2 + i) * 0.3);
      ctx.shadowBlur = 8;
      ctx.shadowColor = s.color;
      ctx.strokeStyle = s.color;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(s.x, s.y);
      ctx.lineTo(s.x, s.y + s.len);
      ctx.stroke();
    }
    ctx.restore();

    // 顶部底部暗角
    ctx.save();
    const vg = ctx.createLinearGradient(0, 0, 0, 60);
    vg.addColorStop(0, 'rgba(5,6,15,0.7)');
    vg.addColorStop(1, 'rgba(5,6,15,0)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, Balance.width, 60);
    const vg2 = ctx.createLinearGradient(0, Balance.height - 60, 0, Balance.height);
    vg2.addColorStop(0, 'rgba(5,6,15,0)');
    vg2.addColorStop(1, 'rgba(5,6,15,0.7)');
    ctx.fillStyle = vg2;
    ctx.fillRect(0, Balance.height - 60, Balance.width, 60);
    ctx.restore();
  },
};

/* Effects.js */
// ====== src/render/Effects.js ======
// 全屏特效：闪光、扫描线、Boss 出场 WARNING、战斗结束 CG 动画

const Effects = {
  flashEl: null,
  scanLineY: 0,
  warningTimer: 0,
  warningActive: false,
  warningText: '',

  // ===== CG 动画状态 =====
  cg: {
    active: false,
    type: '',        // 'victory' | 'defeat'
    timer: 0,
    phase: 0,
    stars: [],
    debris: [],
    voicePlayed: false,
    onComplete: null,
    playerColor: '#00f0ff',
  },

  init() {
    this.flashEl = document.getElementById('flash');
  },

  // 全屏白闪
  flash() {
    if (this.flashEl) {
      this.flashEl.classList.remove('show');
      void this.flashEl.offsetWidth;
      this.flashEl.classList.add('show');
    }
  },

  // Boss 出场 WARNING（duration 秒）
  triggerBossWarning(duration = 1.0) {
    this.warningActive = true;
    this.warningTimer = duration;
    if (Game.audio) Game.audio.play('warning');
  },

  // ===== 启动 CG 动画 =====
  // type: 'victory' | 'defeat'
  playCG(type, opts = {}) {
    const cg = this.cg;
    cg.active = true;
    cg.type = type;
    cg.timer = 0;
    cg.phase = 0;
    cg.voicePlayed = false;
    cg.onComplete = opts.onComplete || null;
    cg.playerColor = opts.playerColor || '#00f0ff';
    cg.title = opts.title || (type === 'victory' ? 'VICTORY' : 'DEFEAT');
    cg.subtitle = opts.subtitle || '';
    cg.stars = [];
    cg.debris = [];
    // 生成星空粒子（用于纵深感）
    for (let i = 0; i < 80; i++) {
      cg.stars.push({
        x: Math.random() * Balance.width,
        y: Math.random() * Balance.height,
        z: Math.random() * 0.8 + 0.2,   // 深度（速度系数）
        size: Math.random() * 2 + 0.5,
      });
    }
    if (type === 'defeat') {
      // 生成残骸碎片
      for (let i = 0; i < 24; i++) {
        const ang = Math.random() * Utils.TAU;
        const sp = 60 + Math.random() * 180;
        cg.debris.push({
          x: Balance.width / 2,
          y: Balance.height / 2,
          vx: Math.cos(ang) * sp,
          vy: Math.sin(ang) * sp,
          size: 2 + Math.random() * 4,
          color: Math.random() < 0.5 ? '#ffaa00' : '#ff3050',
          life: 0,
          maxLife: 1.5 + Math.random(),
        });
      }
    }
  },

  update(dt) {
    this.scanLineY = (this.scanLineY + dt * 400) % Balance.height;
    if (this.warningActive) {
      this.warningTimer -= dt;
      if (this.warningTimer <= 0) this.warningActive = false;
    }

    // CG 更新
    const cg = this.cg;
    if (cg.active) {
      cg.timer += dt;
      // 时长分阶段（整体压缩至 2.8s）
      // victory: 0-1.0s 飞行+星空 / 1.0-2.0s 文字+语音 / 2.0-2.8s 渐隐
      // defeat:  0-1.2s 爆炸+残骸 / 1.2-2.2s 文字+语音 / 2.2-2.8s 渐隐
      const t1 = cg.type === 'victory' ? 1.0 : 1.2;
      const t2 = cg.type === 'victory' ? 2.0 : 2.2;
      const tEnd = 2.8;

      if (cg.timer < t1) cg.phase = 0;
      else if (cg.timer < t2) cg.phase = 1;
      else if (cg.timer < tEnd) cg.phase = 2;
      else {
        // 结束
        cg.active = false;
        if (cg.onComplete) {
          const cb = cg.onComplete;
          cg.onComplete = null;
          cb();
        }
        return;
      }

      // 星空推进
      if (cg.type === 'victory') {
        for (const s of cg.stars) {
          s.y += s.z * 320 * dt;
          if (s.y > Balance.height) { s.y = 0; s.x = Math.random() * Balance.width; }
        }
      }

      // 残骸推进
      if (cg.type === 'defeat') {
        for (const d of cg.debris) {
          d.life += dt;
          d.x += d.vx * dt;
          d.y += d.vy * dt;
          d.vy += 120 * dt; // 重力
          d.vx *= 0.98;
        }
      }

      // 阶段 1 末尾播放语音
      if (cg.phase >= 1 && !cg.voicePlayed) {
        cg.voicePlayed = true;
        if (Game.audio) {
          if (cg.type === 'victory') {
            Game.audio.speak('胜利！干得漂亮！', { rate: 1.1, pitch: 1.1 });
          } else {
            Game.audio.speak('战机损毁，任务失败', { rate: 0.95, pitch: 0.85 });
          }
        }
      }
    }
  },

  draw(ctx, time) {
    // 扫描线（持续运行的细节）
    ctx.save();
    ctx.globalAlpha = 0.04;
    ctx.fillStyle = '#00f0ff';
    for (let y = 0; y < Balance.height; y += 4) {
      ctx.fillRect(0, y, Balance.width, 1);
    }
    ctx.restore();

    // 移动扫描带（更明显的）
    ctx.save();
    const gradS = ctx.createLinearGradient(0, this.scanLineY - 30, 0, this.scanLineY + 30);
    gradS.addColorStop(0, 'rgba(0,240,255,0)');
    gradS.addColorStop(0.5, 'rgba(0,240,255,0.08)');
    gradS.addColorStop(1, 'rgba(0,240,255,0)');
    ctx.fillStyle = gradS;
    ctx.fillRect(0, this.scanLineY - 30, Balance.width, 60);
    ctx.restore();

    // WARNING 大字
    if (this.warningActive) {
      ctx.save();
      const blink = Math.floor(this.warningTimer * 8) % 2 === 0;
      // 全屏红色扫描带
      ctx.fillStyle = `rgba(255, 46, 136, ${0.15 * (blink ? 1 : 0.5)})`;
      ctx.fillRect(0, 0, Balance.width, Balance.height);

      ctx.font = 'bold 48px Orbitron, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.globalAlpha = blink ? 1 : 0.3;
      ctx.shadowBlur = 24;
      ctx.shadowColor = '#ff2e88';
      ctx.fillStyle = '#ff2e88';
      ctx.fillText('WARNING', Balance.width / 2, Balance.height / 2 - 20);
      ctx.font = '14px Share Tech Mono, monospace';
      ctx.shadowBlur = 8;
      ctx.fillText('— BOSS APPROACHING —', Balance.width / 2, Balance.height / 2 + 20);
      ctx.restore();
    }

    // ===== CG 动画 =====
    const cg = this.cg;
    if (cg.active) {
      this._drawCG(ctx, time);
    }
  },

  _drawCG(ctx, time) {
    const cg = this.cg;
    const W = Balance.width, H = Balance.height;
    const cx = W / 2, cy = H / 2;

    // 背景渐变（胜利：深蓝紫；失败：暗红黑）
    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    if (cg.type === 'victory') {
      grad.addColorStop(0, '#0a0420');
      grad.addColorStop(0.5, '#100828');
      grad.addColorStop(1, '#020208');
    } else {
      grad.addColorStop(0, '#1a0008');
      grad.addColorStop(0.5, '#100004');
      grad.addColorStop(1, '#020000');
    }
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    // 阶段 0：飞行 / 爆炸
    if (cg.phase === 0) {
      if (cg.type === 'victory') {
        // 星空纵深
        ctx.save();
        for (const s of cg.stars) {
          ctx.globalAlpha = s.z;
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(s.x, s.y, s.size, s.size);
        }
        ctx.restore();
        // 玩家飞机向上飞行 + 引擎尾焰
        ctx.save();
        const flyY = H * 0.7 - cg.timer * 180;
        ctx.translate(cx, flyY);
        ctx.shadowBlur = 20;
        ctx.shadowColor = cg.playerColor;
        ctx.fillStyle = cg.playerColor;
        ctx.beginPath();
        ctx.moveTo(0, -18);
        ctx.lineTo(-14, 10);
        ctx.lineTo(-6, 6);
        ctx.lineTo(0, 14);
        ctx.lineTo(6, 6);
        ctx.lineTo(14, 10);
        ctx.closePath();
        ctx.fill();
        // 尾焰
        const flick = 0.7 + Math.random() * 0.3;
        ctx.fillStyle = '#ffaa00';
        ctx.beginPath();
        ctx.moveTo(-4, 10);
        ctx.lineTo(0, 18 + 10 * flick);
        ctx.lineTo(4, 10);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      } else {
        // 爆炸闪光 + 残骸
        ctx.save();
        const flashA = Math.max(0, 1 - cg.timer / 2);
        ctx.fillStyle = `rgba(255,170,0,${0.3 * flashA})`;
        ctx.fillRect(0, 0, W, H);
        // 残骸
        for (const d of cg.debris) {
          if (d.life > d.maxLife) continue;
          const a = 1 - d.life / d.maxLife;
          ctx.globalAlpha = a;
          ctx.shadowBlur = 8;
          ctx.shadowColor = d.color;
          ctx.fillStyle = d.color;
          ctx.fillRect(d.x - d.size / 2, d.y - d.size / 2, d.size, d.size);
        }
        ctx.restore();
      }
    }

    // 阶段 1 & 2：标题文字
    if (cg.phase >= 1) {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // 标题（带辉光 + 缩放进入）
      const enterT = cg.type === 'victory' ? 1.0 : 1.2;
      const p = Math.min(1, (cg.timer - enterT) / 0.35);
      const scale = 0.5 + p * 0.5 + Math.sin(time * 3) * 0.02;
      ctx.translate(cx, cy - 30);
      ctx.scale(scale, scale);
      const titleColor = cg.type === 'victory' ? '#00f0ff' : '#ff3050';
      ctx.shadowBlur = 30;
      ctx.shadowColor = titleColor;
      ctx.fillStyle = titleColor;
      ctx.font = 'bold 56px Orbitron, sans-serif';
      ctx.globalAlpha = p;
      ctx.fillText(cg.title, 0, 0);
      ctx.restore();

      // 副标题
      if (cg.subtitle) {
        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '16px Share Tech Mono, monospace';
        ctx.fillStyle = '#e8f4ff';
        ctx.globalAlpha = p * 0.9;
        ctx.fillText(cg.subtitle, cx, cy + 30);
        ctx.restore();
      }

      // 装饰光带
      ctx.save();
      ctx.globalAlpha = p * 0.6;
      const lineGrad = ctx.createLinearGradient(cx - 120, 0, cx + 120, 0);
      lineGrad.addColorStop(0, 'rgba(0,240,255,0)');
      lineGrad.addColorStop(0.5, titleColor);
      lineGrad.addColorStop(1, 'rgba(0,240,255,0)');
      ctx.fillStyle = lineGrad;
      ctx.fillRect(cx - 120, cy + 2, 240, 2);
      ctx.restore();
    }

    // 阶段 2：渐隐
    if (cg.phase === 2) {
      const t2 = cg.type === 'victory' ? 2.0 : 2.2;
      const fa = Math.min(1, (cg.timer - t2) / 0.6);
      ctx.save();
      ctx.fillStyle = `rgba(0,0,0,${fa})`;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }
  },
};

/* Renderer.js */
// ====== src/render/Renderer.js ======
// 主绘制器：统一调度渲染顺序

const Renderer = {
  ctx: null,
  canvas: null,

  init(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    // 高 DPI 支持
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Balance.width * dpr;
    canvas.height = Balance.height * dpr;
    canvas.style.width = Balance.width + 'px';
    canvas.style.height = Balance.height + 'px';
    this.ctx.scale(dpr, dpr);
    this.ctx.imageSmoothingEnabled = true;
  },

  getCtx() { return this.ctx; },

  draw(time) {
    const ctx = this.ctx;
    // 清屏
    ctx.clearRect(0, 0, Balance.width, Balance.height);

    // 1. 背景
    Background.draw(ctx, time);

    // 2. 道具
    for (let i = 0; i < Game.pickups.length; i++) {
      if (Game.pickups[i].alive) Game.pickups[i].draw(ctx);
    }

    // 3. 玩家子弹
    PlayerBulletPool.draw(ctx);

    // 4. 敌弹
    EnemyBulletPool.draw(ctx);

    // 5. 敌人
    for (let i = 0; i < Game.enemies.length; i++) {
      if (Game.enemies[i].alive) Game.enemies[i].draw(ctx);
    }

    // 6. Boss
    if (Game.boss && Game.boss.alive) Game.boss.draw(ctx);

    // 7. 玩家
    if (Game.player && Game.player.alive) Game.player.draw(ctx);

    // 8. 粒子（最上层）
    if (Game.particles) Game.particles.draw(ctx);

    // 9. UI
    if (Game.hud) Game.hud.draw(ctx);
    if (Game.bossUI && Game.boss) Game.bossUI.draw(ctx);

    // 10. 全屏特效
    Effects.draw(ctx, time);
  },
};

/* HUD.js */
// ====== src/ui/HUD.js ======
// 玩家 HUD：HP/能量/分数/连击/Bomb/武器/火力

const HUD = {
  draw(ctx) {
    const p = Game.player;
    if (!p) return;
    ctx.save();
    ctx.font = '12px "Share Tech Mono", monospace';
    ctx.textBaseline = 'top';

    // ===== 左上：HP + 能量 =====
    this._drawHpBar(ctx, 12, 12, p);
    this._drawEnergyBar(ctx, 12, 32, p);

    // ===== 右上：分数 + 连击 =====
    ctx.textAlign = 'right';
    ctx.shadowBlur = 6;
    ctx.shadowColor = Balance.color.cyan;
    ctx.fillStyle = Balance.color.text;
    ctx.font = 'bold 18px "Orbitron", sans-serif';
    ctx.fillText(String(Game.score.score).padStart(8, '0'), Balance.width - 12, 10);

    // 连击倍率
    if (Game.score.comboMultiplier > 1) {
      ctx.font = 'bold 14px "Orbitron", sans-serif';
      ctx.fillStyle = Balance.color.orange;
      ctx.shadowColor = Balance.color.orange;
      const scale = 1 + Math.min(0.5, Game.score.comboMultiplier * 0.05);
      ctx.save();
      ctx.translate(Balance.width - 12, 34);
      ctx.scale(scale, scale);
      ctx.fillText('×' + Game.score.comboMultiplier, 0, 0);
      ctx.restore();
    }

    // 金币（右上，分数下方）
    ctx.font = 'bold 13px "Orbitron", sans-serif';
    ctx.fillStyle = '#ffd43b';
    ctx.shadowColor = '#ffd43b';
    ctx.fillText('◉ ' + (SaveSystem.getCoins()), Balance.width - 12, 52);

    // ===== 底部：Bomb / 武器 / 火力 =====
    ctx.textAlign = 'left';
    this._drawBombs(ctx, 12, Balance.height - 28, p);
    this._drawWeapon(ctx, Balance.width / 2, Balance.height - 28, p);

    ctx.restore();
  },

  _drawHpBar(ctx, x, y, p) {
    // 六边形分段 HP
    const segW = 14, segH = 10, gap = 3;
    ctx.shadowBlur = 6;
    ctx.shadowColor = Balance.color.cyan;
    for (let i = 0; i < p.maxHp; i++) {
      const sx = x + i * (segW + gap);
      const active = i < p.hp;
      ctx.fillStyle = active ? Balance.color.cyan : 'rgba(232,244,255,0.15)';
      if (active) {
        ctx.beginPath();
        Utils.clipCorner(ctx, sx, y, segW, segH, 2);
        ctx.fill();
      } else {
        ctx.strokeStyle = 'rgba(232,244,255,0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        Utils.clipCorner(ctx, sx, y, segW, segH, 2);
        ctx.stroke();
      }
    }
    // 文字
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(232,244,255,0.5)';
    ctx.font = '9px "Share Tech Mono", monospace';
    ctx.fillText('HULL', x, y - 12);
  },

  _drawEnergyBar(ctx, x, y, p) {
    const w = 110, h = 6;
    const ratio = p.energy / Balance.energy.max;
    // 底
    ctx.fillStyle = 'rgba(155, 92, 255, 0.15)';
    ctx.fillRect(x, y, w, h);
    // 填充
    ctx.shadowBlur = 8;
    ctx.shadowColor = Balance.color.purple;
    ctx.fillStyle = Balance.color.purple;
    ctx.fillRect(x, y, w * ratio, h);
    // 满 Bomb 可用闪烁
    if (ratio >= 1 || p.bombs > 0) {
      ctx.fillStyle = `rgba(0,240,255,${0.5 + Math.sin(performance.now() / 100) * 0.4})`;
      ctx.fillRect(x, y - 2, w, 1);
    }
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(232,244,255,0.5)';
    ctx.font = '9px "Share Tech Mono", monospace';
    ctx.fillText('ENERGY ' + Math.floor(ratio * 100) + '%', x, y + h + 2);
  },

  _drawBombs(ctx, x, y, p) {
    ctx.fillStyle = 'rgba(232,244,255,0.5)';
    ctx.font = '9px "Share Tech Mono", monospace';
    ctx.fillText('BOMB', x, y - 12);
    for (let i = 0; i < p.maxBombs; i++) {
      const bx = x + i * 18;
      const active = i < p.bombs;
      ctx.shadowBlur = active ? 10 : 0;
      ctx.shadowColor = Balance.color.cyan;
      ctx.fillStyle = active ? Balance.color.cyan : 'rgba(232,244,255,0.2)';
      ctx.beginPath();
      ctx.arc(bx + 6, y + 6, 5, 0, Utils.TAU);
      ctx.fill();
      if (active) {
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(bx + 6, y + 6, 2, 0, Utils.TAU);
        ctx.fill();
      }
    }
  },

  _drawWeapon(ctx, cx, y, p) {
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(232,244,255,0.5)';
    ctx.font = '9px "Share Tech Mono", monospace';
    ctx.fillText('WEAPON', cx, y - 12);

    const w = p.weapon.type;
    const color = w === 'laser' ? '#00f0ff' : w === 'homing' ? '#9b5cff' : '#ffaa00';
    ctx.shadowBlur = 8;
    ctx.shadowColor = color;
    ctx.fillStyle = color;
    ctx.font = 'bold 12px "Orbitron", sans-serif';
    const label = w === 'laser' ? 'LASER' : w === 'homing' ? 'HOMING' : 'SCATTER';
    ctx.fillText(label, cx, y);

    // 火力等级 P×N
    ctx.fillStyle = Balance.color.orange;
    ctx.shadowColor = Balance.color.orange;
    ctx.font = 'bold 11px "Orbitron", sans-serif';
    ctx.fillText('P×' + p.weapon.level, cx, y + 14);

    ctx.textAlign = 'left';
  },
};

/* BossUI.js */
// ====== src/ui/BossUI.js ======
// Boss 血条 + 名字 + 阶段指示

const BossUI = {
  slideIn: 0,         // 0~1 滑入进度
  targetSlide: 0,
  boss: null,
  phaseFlash: 0,

  setBoss(boss) {
    this.boss = boss;
    this.targetSlide = 1;
    this.slideIn = 0;
  },

  clear() {
    this.targetSlide = 0;
    this.boss = null;
  },

  onPhaseChange(boss) {
    this.phaseFlash = 1.0;
  },

  update(dt) {
    this.slideIn = Utils.lerp(this.slideIn, this.targetSlide, 0.1);
    if (this.phaseFlash > 0) this.phaseFlash -= dt * 2;
  },

  draw(ctx) {
    // Boss 入场前（intro/WARNING）不显示血条
    if (!this.boss || this.boss.state === 'intro' || this.slideIn < 0.05) return;
    const b = this.boss;
    const cx = Balance.width / 2;
    const w = Balance.width - 60;
    const h = 8;
    const y = 56;
    const offsetX = (1 - this.slideIn) * Balance.width * 0.5;

    ctx.save();
    ctx.translate(offsetX, 0);
    ctx.globalAlpha = this.slideIn;

    // 名字
    ctx.textAlign = 'center';
    ctx.font = 'bold 14px "Orbitron", sans-serif';
    ctx.shadowBlur = 8;
    ctx.shadowColor = b.color;
    ctx.fillStyle = b.color;
    ctx.fillText(b.name + ' / ' + b.title, cx, y - 12);

    // 血条底
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(255, 46, 136, 0.15)';
    ctx.fillRect(30, y, w, h);

    // 阶段分隔标记
    const phaseColor = b.phases[b.phaseIndex].color;
    for (let i = 0; i < b.phases.length; i++) {
      const ph = b.phases[i];
      const ratio = ph.hpThreshold;
      const px = 30 + w * ratio;
      ctx.strokeStyle = 'rgba(255,255,255,0.3)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(px, y - 2);
      ctx.lineTo(px, y + h + 2);
      ctx.stroke();
    }

    // 血条填充
    const hpRatio = b.hp / b.maxHp;
    ctx.shadowBlur = 8;
    ctx.shadowColor = phaseColor;
    ctx.fillStyle = phaseColor;
    ctx.fillRect(30, y, w * hpRatio, h);
    // 阶段闪光
    if (this.phaseFlash > 0) {
      ctx.globalAlpha = this.slideIn * this.phaseFlash;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(30, y, w * hpRatio, h);
      ctx.globalAlpha = this.slideIn;
    }

    // 阶段文字
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(232,244,255,0.6)';
    ctx.font = '9px "Share Tech Mono", monospace';
    ctx.fillText(`PHASE ${b.phaseIndex + 1} / ${b.phases.length}`, cx, y + h + 6);

    ctx.restore();
  },
};

/* Menu.js */
// ====== src/ui/Menu.js ======
// 覆盖层菜单：标题 / 模式选择 / 关卡选择 / 成就 / 统计 / 暂停 / 通关 / 失败

const Menu = {
  overlay: null,
  box: null,
  titleEl: null,
  subEl: null,
  statsEl: null,
  buttonsEl: null,
  logoEl: null,

  init() {
    this.overlay = document.getElementById('overlay');
    this.box = document.getElementById('overlay-box');
    this.titleEl = document.getElementById('overlay-title');
    this.subEl = document.getElementById('overlay-sub');
    this.statsEl = document.getElementById('overlay-stats');
    this.buttonsEl = document.getElementById('overlay-buttons');
    this.logoEl = document.getElementById('wavepeak-logo');
  },

  show(title, sub, statsHtml, buttons, showLogo) {
    if (this.logoEl) {
      if (showLogo) this.logoEl.classList.remove('hidden');
      else this.logoEl.classList.add('hidden');
    }
    // 浪尖.jpg 横幅与 Logo 同步（仅标题界面显示）
    this._bannerEl = this._bannerEl || document.getElementById('langjian-banner');
    if (this._bannerEl) {
      if (showLogo) this._bannerEl.classList.remove('hidden');
      else this._bannerEl.classList.add('hidden');
    }
    this.titleEl.textContent = title;
    this.subEl.textContent = sub || '';
    this.statsEl.innerHTML = statsHtml || '';
    this.buttonsEl.innerHTML = '';
    if (buttons && buttons.length) {
      for (const b of buttons) {
        const btn = document.createElement('button');
        btn.className = 'menu-btn' + (b.danger ? ' danger' : '') + (b.accent ? ' accent' : '');
        btn.textContent = b.label;
        btn.addEventListener('click', () => {
          if (Game.audio) { Game.audio.resume(); Game.audio.play('toggle'); }
          if (b.onClick) b.onClick();
        });
        this.buttonsEl.appendChild(btn);
      }
    }
    this.overlay.classList.remove('hidden');
  },

  hide() {
    this.overlay.classList.add('hidden');
  },

  // ===== 标题 / 主菜单（模式选择）=====
  showTitle() {
    const st = SaveSystem.getAll();
    const stats = `
      <div class="stat-line"><span class="stat-label">移动</span><span class="stat-value">WASD / 方向键</span></div>
      <div class="stat-line"><span class="stat-label">开火</span><span class="stat-value">Space（自动开火）</span></div>
      <div class="stat-line"><span class="stat-label">低速</span><span class="stat-value">Shift</span></div>
      <div class="stat-line"><span class="stat-label">炸弹 BOMB</span><span class="stat-value">Z</span></div>
      <div class="stat-line"><span class="stat-label">清屏技能</span><span class="stat-value">Q（8s 冷却）</span></div>
      <div class="stat-line"><span class="stat-label">投降技能</span><span class="stat-value">X</span></div>
      <div class="stat-line"><span class="stat-label">僚机编队</span><span class="stat-value">V</span></div>
      <div class="stat-line"><span class="stat-label">暂停</span><span class="stat-value">Esc / P</span></div>
      <div class="stat-line"><span class="stat-label">成就</span><span class="stat-value">${Achievements.countUnlocked()}/${Achievements.total()}</span></div>
      <div class="stat-line"><span class="stat-label">金币</span><span class="stat-value">◉ ${st.coins || 0}</span></div>
      <div class="stat-line"><span class="stat-label">无尽最高</span><span class="stat-value">${st.endless.bestScore}</span></div>
      <div class="stat-line"><span class="stat-label">今日最佳</span><span class="stat-value">${SaveSystem.getDailyBest()}</span></div>
    `;
    const unlockedCount = Planes.allKeys.filter(k => Planes.isUnlocked(k)).length;
    const currentPlane = Planes[SaveSystem.getSelectedPlane()];
    this.show('霓虹深渊', 'STAR FIGHTER · NEON ABYSS', stats, [
      { label: '闯关模式', accent: true, onClick: () => this.showShipSelect(true) },
      { label: '无尽模式', onClick: () => Game.startEndlessMode() },
      { label: '每日挑战', onClick: () => this.showDaily() },
      { label: `选择战机 (${currentPlane.name} · ${unlockedCount}/${Planes.allKeys.length})`, onClick: () => this.showShipSelect() },
      { label: `武器商店 (◉ ${st.coins || 0})`, onClick: () => this.showShop() },
      { label: '排行榜', onClick: () => this.showLeaderboard() },
      { label: '成就', onClick: () => this.showAchievements() },
      { label: '数据统计', onClick: () => this.showStats() },
      { label: '关于', onClick: () => this.showAbout() },
      { label: '重置存档', danger: true, onClick: () => this._confirmReset() },
    ], true);
  },

  // ===== 每日挑战 =====
  showDaily() {
    const cfg = Game.dailyConfig();
    const plane = Planes[cfg.plane];
    const modNames = { score2: '得分 ×2', coin2: '金币 ×2', bomb1: '初始炸弹 1' };
    const modsHtml = cfg.mods.map(m => `<span class="daily-mod">${modNames[m]}</span>`).join(' ');
    const best = SaveSystem.getDailyBest();
    const stats = `
      <div class="stat-line"><span class="stat-label">日期</span><span class="stat-value">${cfg.date}</span></div>
      <div class="stat-line"><span class="stat-label">当日固定战机</span><span class="stat-value" style="color:${plane.color}">${plane.name}</span></div>
      <div class="stat-line"><span class="stat-label">词条</span><span class="stat-value">${modsHtml}</span></div>
      <div class="stat-line"><span class="stat-label">今日最佳</span><span class="stat-value">${best}</span></div>
    `;
    this.show('每日挑战', 'DAILY CHALLENGE', stats, [
      { label: '开始挑战', accent: true, onClick: () => Game.startDailyMode() },
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ]);
  },

  // ===== 排行榜 =====
  showLeaderboard() {
    const lb = SaveSystem.getLeaderboard();
    let html = '';
    if (lb.length === 0) {
      html = '<div class="lb-empty">暂无战绩，去创造第一个纪录吧！</div>';
    } else {
      const modeNames = { stage: '闯关', endless: '无尽', daily: '每日' };
      for (let i = 0; i < lb.length; i++) {
        const e = lb[i];
        const rank = i + 1;
        const rankCls = rank === 1 ? ' gold' : rank === 2 ? ' silver' : rank === 3 ? ' bronze' : '';
        html += `
          <div class="lb-row${rankCls}">
            <span class="lb-rank">${rank}</span>
            <span class="lb-score">${e.score || 0}</span>
            <span class="lb-meta">${modeNames[e.mode] || e.mode || '-'} ${e.stage || ''} · ✕${e.kills || 0} · ${e.date || ''}</span>
          </div>`;
      }
    }
    this.show('排行榜', 'LOCAL TOP 8', html, [
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ]);
  },

  // ===== 武器商店 =====
  showShop() {
    const coins = SaveSystem.getCoins();
    let html = `<div class="shop-coins">持有金币 <span class="coin-num">◉ ${coins}</span></div>`;
    html += `<div class="shop-grid">`;
    for (const key of ShopData.allKeys) {
      const item = ShopData.items[key];
      const owned = SaveSystem.isOwned(key);
      const affordable = coins >= item.price;
      html += `
        <div class="shop-card${owned ? ' owned' : ''}" style="--shop-color:${item.color}">
          <div class="shop-icon">${item.icon}</div>
          <div class="shop-name">${item.name}</div>
          <div class="shop-desc">${item.desc}</div>
          <div class="shop-price${affordable || owned ? '' : ' poor'}">${owned ? '✓ 已装备' : '◉ ' + item.price}</div>
          <button class="shop-buy${owned ? ' disabled' : affordable ? '' : ' disabled'}"
                  data-key="${key}" data-owned="${owned ? 1 : 0}" data-price="${item.price}">
            ${owned ? '已拥有' : affordable ? '购 买' : '金币不足'}
          </button>
        </div>`;
    }
    html += `</div>`;
    // 消耗品区
    html += `<div class="shop-section">消耗品（可叠加购买，使用后消耗）</div>`;
    html += `<div class="shop-grid">`;
    for (const key of ShopData.consumableKeys) {
      const item = ShopData.consumables[key];
      const count = SaveSystem.getConsumableCount(key);
      const affordable = coins >= item.price;
      html += `
        <div class="shop-card" style="--shop-color:${item.color}">
          <div class="shop-icon">${item.icon}</div>
          <div class="shop-name">${item.name}</div>
          <div class="shop-desc">${item.desc}</div>
          <div class="shop-price${affordable ? '' : ' poor'}">◉ ${item.price} <span class="stock">库存 ×${count}</span></div>
          <button class="shop-buy${affordable ? '' : ' disabled'}" data-kind="${key}" data-price="${item.price}">
            ${affordable ? '购 买' : '金币不足'}
          </button>
        </div>`;
    }
    html += `</div>`;
    html += `<div class="shop-tip">永久强化一次买断；消耗品每局限用，护盾开局生效，复活币自动触发</div>`;
    this.show('武器商店', 'WEAPON SHOP', html, [
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ], false);

    // 绑定购买事件
    setTimeout(() => {
      const btns = document.querySelectorAll('.shop-buy');
      btns.forEach(btn => {
        btn.addEventListener('click', () => {
          const permKey = btn.dataset.key;
          const kindKey = btn.dataset.kind;
          if (permKey) {
            if (btn.dataset.owned === '1') return;
            const price = parseInt(btn.dataset.price, 10);
            if (SaveSystem.buyItem(permKey, price)) {
              if (Game.audio) Game.audio.play('powerup');
              this.showShop();
            } else {
              if (Game.audio) Game.audio.play('hurt');
            }
          } else if (kindKey) {
            if (btn.classList.contains('disabled')) return;
            const price = parseInt(btn.dataset.price, 10);
            if (SaveSystem.buyConsumable(kindKey, price)) {
              if (Game.audio) Game.audio.play('powerup');
              this.showShop();
            } else {
              if (Game.audio) Game.audio.play('hurt');
            }
          }
        });
      });
    }, 30);
  },

  // ===== 关于 =====
  showAbout() {
    const html = `
      <div class="about-box">
        <div class="about-line">星际战机：霓虹深渊</div>
        <div class="about-sub">STAR FIGHTER · NEON ABYSS</div>
        <div class="about-desc">一款纯前端 Canvas 射击游戏，零素材依赖，全程序化绘制与合成音效。</div>
        <div class="about-section">核心特色</div>
        <div class="about-item">· 闯关模式：3 关递进 + Boss 战 + 星级评定</div>
        <div class="about-item">· 无尽模式：无限波次 + 动态难度</div>
        <div class="about-item">· 4 架战机，各有专属武器与解锁条件</div>
        <div class="about-item">· 一键清屏(Q) / 一键投降(X) / 炸弹(Z)</div>
        <div class="about-item">· 敌人嘲讽气泡 / Boss 专属胜利语音</div>
        <div class="about-item">· 成就系统 / 数据统计 / 进度保存</div>
        <div class="about-section">技术栈</div>
        <div class="about-item">HTML5 Canvas + Web Audio API + localStorage</div>
        <div class="about-item">固定步长游戏循环 + 对象池 + 圆形碰撞</div>
      </div>`;
    this.show('关于', 'ABOUT', html, [
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ], false);
  },

  // ===== 战机选择 =====
  // prep=true 时为闯关准备流程：选完战机后进入选关
  showShipSelect(prep = false) {
    this._prepMode = prep;
    const unlockedCount = Planes.allKeys.filter(k => Planes.isUnlocked(k)).length;
    const currentKey = SaveSystem.getSelectedPlane();
    let html = `<div class="ship-header">已解锁 ${unlockedCount}/${Planes.allKeys.length}</div>`;
    html += `<div class="ship-grid">`;
    for (const key of Planes.allKeys) {
      const cfg = Planes[key];
      const unlocked = Planes.isUnlocked(key);
      const selected = key === currentKey;
      const hint = unlocked ? cfg.desc : Planes.unlockHint(key);
      const selectedMark = selected ? '<span class="ship-selected">✓ 当前</span>' : '';
      const lockMark = !unlocked ? '<span class="ship-lock">🔒</span>' : '';
      // 属性条
      const bars = this._shipBars(cfg);
      html += `
        <div class="ship-card${selected ? ' selected' : ''}${unlocked ? '' : ' locked'}"
             data-key="${key}" data-unlocked="${unlocked ? 1 : 0}">
          <div class="ship-icon" style="--ship-color:${cfg.color};--ship-accent:${cfg.accent}">
            <canvas width="80" height="80"></canvas>
          </div>
          <div class="ship-name">${lockMark}${cfg.name}</div>
          <div class="ship-sub">${cfg.subtitle}</div>
          <div class="ship-desc">${hint}</div>
          <div class="ship-bars">${bars}</div>
          ${selectedMark}
        </div>`;
    }
    html += `</div>`;
    const buttons = [];
    if (prep) {
      buttons.push({ label: '下一步：选择关卡', accent: true, onClick: () => this.showStageSelect() });
      buttons.push({ label: '返回', danger: true, onClick: () => this.showTitle() });
    } else {
      buttons.push({ label: '返回', danger: true, onClick: () => this.showTitle() });
    }
    this.show('选择战机', 'SELECT YOUR FIGHTER', html, buttons, false);

    // 绑定点击事件
    setTimeout(() => {
      const cards = document.querySelectorAll('.ship-card');
      cards.forEach(card => {
        card.addEventListener('click', () => {
          if (card.dataset.unlocked !== '1') return;
          const key = card.dataset.key;
          if (SaveSystem.selectPlane(key)) {
            // 重绘（保持 prep 上下文）
            this.showShipSelect(this._prepMode);
            // 播放音效
            if (Game.audio) Game.audio.play('toggle');
          }
        });
      });
    }, 30);
  },

  _shipBars(cfg) {
    const speedRatio = Math.min(1, cfg.speed / (Balance.player.speed * 1.3));
    const hpRatio = Math.min(1, cfg.maxHp / 7);
    const bombRatio = Math.min(1, cfg.startBombs / 3);
    return `
      <div class="bar-row"><span>速</span><div class="bar"><i style="width:${Math.round(speedRatio*100)}%;background:${cfg.color}"></i></div></div>
      <div class="bar-row"><span>血</span><div class="bar"><i style="width:${Math.round(hpRatio*100)}%;background:${cfg.color}"></i></div></div>
      <div class="bar-row"><span>弹</span><div class="bar"><i style="width:${Math.round(bombRatio*100)}%;background:${cfg.color}"></i></div></div>`;
  },

  // ===== 关卡选择 =====
  showStageSelect() {
    const stages = WavesData.stages;
    let statsHtml = '';
    for (let i = 0; i < stages.length; i++) {
      const key = stages[i];
      const data = WavesData[key];
      const unlocked = SaveSystem.isStageUnlocked(key);
      const stars = SaveSystem.getStageStars(key);
      const starStr = stars.map(s => s ? '★' : '☆').join(' ');
      const best = SaveSystem.getStageBestScore(key);
      const lock = unlocked ? '' : ' 🔒';
      statsHtml += `
        <div class="stat-line stage-row${unlocked ? '' : ' locked'}">
          <span class="stat-label">STAGE ${data.stage}${lock}</span>
          <span class="stat-value">${starStr}</span>
          <span class="stat-label">BEST ${best}</span>
        </div>`;
    }
    const buttons = [
      { label: '从第 1 关开始', accent: true, onClick: () => Game.startStageMode() },
    ];
    // 为每个已解锁关卡加按钮
    for (let i = 0; i < stages.length; i++) {
      const key = stages[i];
      if (SaveSystem.isStageUnlocked(key)) {
        const data = WavesData[key];
        if (data.stage > 1) {
          buttons.push({ label: `第 ${data.stage} 关`, onClick: () => Game.startStageAt(key) });
        }
      }
    }
    buttons.push({ label: '返回', danger: true, onClick: () => this._prepMode ? this.showShipSelect(true) : this.showTitle() });
    this.show('闯关模式', 'STAGE SELECT', statsHtml, buttons);
  },

  // ===== 成就 =====
  showAchievements() {
    let html = '';
    for (let i = 0; i < Achievements.list.length; i++) {
      const a = Achievements.list[i];
      const unlocked = SaveSystem.isAchievementUnlocked(a.id);
      html += `
        <div class="ach-row${unlocked ? '' : ' locked'}">
          <span class="ach-icon-mini">${a.icon}</span>
          <div class="ach-info">
            <div class="ach-name-mini">${a.name}</div>
            <div class="ach-desc-mini">${a.desc}</div>
          </div>
          <span class="ach-status">${unlocked ? '已解锁' : '未解锁'}</span>
        </div>`;
    }
    const count = Achievements.countUnlocked();
    this.show('成就', `ACHIEVEMENTS ${count}/${Achievements.total()}`, html, [
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ]);
  },

  // ===== 数据统计 =====
  showStats() {
    const s = SaveSystem.getStats();
    const e = SaveSystem.getEndlessBest();
    const st = SaveSystem.getAll().stage;
    const html = `
      <div class="stat-line"><span class="stat-label">总局数</span><span class="stat-value">${s.totalRuns}</span></div>
      <div class="stat-line"><span class="stat-label">总击杀</span><span class="stat-value">${s.totalKills}</span></div>
      <div class="stat-label" style="font-size:11px;opacity:.5;margin-top:8px;">闯关模式</div>
      <div class="stat-line"><span class="stat-label">通关次数</span><span class="stat-value">${s.stageClears}</span></div>
      <div class="stat-line"><span class="stat-label">闯关次数</span><span class="stat-value">${st.playCount}</span></div>
      <div class="stat-label" style="font-size:11px;opacity:.5;margin-top:8px;">无尽模式</div>
      <div class="stat-line"><span class="stat-label">最高分</span><span class="stat-value">${e.bestScore}</span></div>
      <div class="stat-line"><span class="stat-label">最长存活</span><span class="stat-value">${e.bestTime.toFixed(1)}s</span></div>
      <div class="stat-line"><span class="stat-label">最多击杀</span><span class="stat-value">${e.bestKills}</span></div>
      <div class="stat-line"><span class="stat-label">最高波次</span><span class="stat-value">${e.bestWave}</span></div>
      <div class="stat-label" style="font-size:11px;opacity:.5;margin-top:8px;">累计</div>
      <div class="stat-line"><span class="stat-label">总分</span><span class="stat-value">${s.totalScore}</span></div>
      <div class="stat-line"><span class="stat-label">最长连击</span><span class="stat-value">${s.maxCombo}</span></div>
      <div class="stat-line"><span class="stat-label">总擦弹</span><span class="stat-value">${s.totalGraze}</span></div>
      <div class="stat-line"><span class="stat-label">总炸弹</span><span class="stat-value">${s.totalBombs}</span></div>
      <div class="stat-line"><span class="stat-label">Boss击杀</span><span class="stat-value">${s.totalBossKills}</span></div>
      <div class="stat-line"><span class="stat-label">游戏时长</span><span class="stat-value">${Math.floor(s.totalPlayTime/60)}m</span></div>
    `;
    this.show('数据统计', 'PLAYER STATS', html, [
      { label: '返回', danger: true, onClick: () => this.showTitle() },
    ]);
  },

  // ===== 确认重置 =====
  _confirmReset() {
    this.show('重置存档？', '将清除所有进度与成就', '', [
      { label: '确认重置', danger: true, onClick: () => { SaveSystem.reset(); this.showTitle(); } },
      { label: '取消', onClick: () => this.showTitle() },
    ]);
  },

  // ===== 暂停 =====
  showPause() {
    this.show('PAUSED', '游戏已暂停', '', [
      { label: '继续', onClick: () => Game.resumeGame() },
      { label: '重新开始', onClick: () => Game.restart() },
      { label: '返回主菜单', danger: true, onClick: () => Game.toTitle() },
    ]);
  },

  // ===== 失败 =====
  showGameOver() {
    const s = Game.score;
    const summ = Stats.summary();
    let extraStats = '';
    if (Game.mode === 'endless') {
      const best = SaveSystem.getEndlessBest();
      extraStats += `<div class="stat-line"><span class="stat-label">WAVE</span><span class="stat-value">${summ.wave}</span></div>`;
      extraStats += `<div class="stat-line"><span class="stat-label">存活</span><span class="stat-value">${summ.playTime.toFixed(1)}s</span></div>`;
      extraStats += `<div class="stat-line"><span class="stat-label">历史最高</span><span class="stat-value">${best.bestScore}</span></div>`;
    }
    if (Game.mode === 'daily') {
      extraStats += `<div class="stat-line"><span class="stat-label">WAVE</span><span class="stat-value">${summ.wave}</span></div>`;
      extraStats += `<div class="stat-line"><span class="stat-label">今日最佳</span><span class="stat-value">${SaveSystem.getDailyBest()}${Game._dailyNewRecord ? ' NEW!' : ''}</span></div>`;
    }
    if (Game.lastRank) {
      extraStats += `<div class="stat-line"><span class="stat-label">排行榜</span><span class="stat-value" style="color:#ffd43b">RANK #${Game.lastRank}</span></div>`;
    }
    const stats = `
      <div class="stat-line"><span class="stat-label">SCORE</span><span class="stat-value">${Game.totalScore + s.score}</span></div>
      <div class="stat-line"><span class="stat-label">KILLS</span><span class="stat-value">${s.kills}</span></div>
      <div class="stat-line"><span class="stat-label">GRAZE</span><span class="stat-value">${s.grazeCount}</span></div>
      <div class="stat-line"><span class="stat-label">COINS</span><span class="stat-value" style="color:#ffd43b">◉ +${Game.coinsRun || 0}</span></div>
      ${extraStats}
    `;
    this.show('GAME OVER',
      Game.mode === 'daily' ? 'DAILY FAILED'
        : Game.mode === 'endless' ? 'ENDLESS FAILED' : 'STAGE FAILED',
      stats, [
      { label: '重新开始', accent: true, onClick: () => Game.restart() },
      { label: '返回主菜单', danger: true, onClick: () => Game.toTitle() },
    ]);
  },

  // ===== 通关本关 =====
  showStageClear(stars, totalScore) {
    const s = Game.score;
    const starsHtml = Array.from({length: 4}, (_, i) =>
      `<span class="stat-value">${i < stars.filter(x=>x).length ? '★' : '☆'}</span>`
    ).join(' ');
    // 保存的最高分对比
    const best = SaveSystem.getStageBestScore(Game.stageKey);
    const newRecord = s.score >= best;
    const stats = `
      <div class="stat-line"><span class="stat-label">SCORE</span><span class="stat-value">${s.score}${newRecord ? ' NEW!' : ''}</span></div>
      <div class="stat-line"><span class="stat-label">BEST</span><span class="stat-value">${best}</span></div>
      <div class="stat-line"><span class="stat-label">KILLS</span><span class="stat-value">${s.kills}</span></div>
      <div class="stat-line"><span class="stat-label">TIME</span><span class="stat-value">${s.stageTime.toFixed(1)}s</span></div>
      <div class="stat-line"><span class="stat-label">STARS</span><span class="stat-value">${starsHtml}</span></div>
      <div class="stat-line"><span class="stat-label">COINS</span><span class="stat-value" style="color:#ffd43b">◉ +${Game.coinsRun || 0}</span></div>
    `;
    const isLast = Game.currentStage >= WavesData.stages.length;
    if (isLast) {
      this.show('CLEAR ALL', 'FINAL VICTORY', stats, [
        { label: '返回主菜单', accent: true, onClick: () => Game.toTitle() },
      ]);
    } else {
      this.show('STAGE CLEAR', `STAGE ${Game.currentStage} PASSED`, stats, [
        { label: '进入下一关', accent: true, onClick: () => Game.nextStage() },
        { label: '返回主菜单', danger: true, onClick: () => Game.toTitle() },
      ]);
    }
  },
};

/* Game.js */
// ====== src/core/Game.js ======
// 全局游戏对象：状态机、实体集合、流程调度
// 支持双模式：闯关模式 (stage) / 无尽模式 (endless)

const Game = {
  // 状态：title / stage_intro / play / pause / stage_clear / endless_clear / game_over
  state: 'title',
  // 模式：'stage' / 'endless'
  mode: 'stage',
  canvas: null,
  player: null,
  enemies: [],
  boss: null,
  pickups: [],
  particles: ParticleSystem,
  score: ScoreSystem,
  audio: AudioSystem,
  hud: HUD,
  bossUI: BossUI,
  // 生成器：根据模式切换
  spawner: Spawner,            // 闯关模式
  spawnerEndless: SpawnerEndless, // 无尽模式
  effects: Effects,
  background: Background,
  renderer: Renderer,
  input: Input,
  save: SaveSystem,
  stats: Stats,
  achievements: Achievements,
  progress: ProgressSystem,
  // 关卡
  currentStage: 0,       // 1-based
  stageKey: null,         // 当前关卡键名
  stageData: null,
  totalScore: 0,
  coinsRun: 0,            // 本局已获得金币
  // 时间
  lastTime: 0,
  accumulator: 0,
  // 暂存玩家状态用于跨关继承
  playerSnapshot: null,
  // 当前所用生成器引用（update 时用）
  _activeSpawner: null,
  // 难度倍率（闯关重玩递增）
  _difficultyMult: { hp: 1, speed: 1 },

  init(canvas) {
    this.canvas = canvas;
    Renderer.init(canvas);
    Input.init(canvas);
    Effects.init();
    Menu.init();
    PlayerBulletPool.init();
    EnemyBulletPool.init();
    ParticleSystem.init();
    AudioSystem.init();
    Background.init();
    BossUI.init && BossUI.init();
    Achievements.init();
    ProgressSystem.init();
    SaveSystem.getAll(); // 预加载存档

    // 事件：点击/按键解锁音频
    const unlockAudio = () => {
      AudioSystem.resume();
      window.removeEventListener('click', unlockAudio);
      window.removeEventListener('keydown', unlockAudio);
    };
    window.addEventListener('click', unlockAudio);
    window.addEventListener('keydown', unlockAudio);

    this.state = 'title';
    this.mode = 'stage';
    Menu.showTitle();
  },

  // ===== 金币 =====
  addCoins(n) {
    if (!n) return;
    this.coinsRun += n;
    if (this.save) this.save.addCoins(n);
  },

  // ===== 状态切换：闯关 =====
  startGame() {
    // 兼容旧入口：默认闯关从第 1 关
    this.startStageMode();
  },

  startStageMode() {
    this.mode = 'stage';
    this.currentStage = 0;
    this.totalScore = 0;
    this.coinsRun = 0;
    this.playerSnapshot = null;
    this._dailyPlane = null;
    ScoreSystem.setMult(1, 1);
    // 消耗品：临时护盾（本局开局生效一次）
    this._shieldPending = SaveSystem.useConsumable('shield_token');
    SaveSystem.incStagePlayCount();
    this._applyDifficultyScaling();
    Menu.hide();
    this.nextStage();
  },

  // 关卡选择：从指定关卡开始（需已解锁）
  startStageAt(stageKey) {
    if (!SaveSystem.isStageUnlocked(stageKey)) return;
    this.mode = 'stage';
    this.stageKey = stageKey;
    // 找到 stage 在 stages 数组中的位置
    const idx = WavesData.stages.indexOf(stageKey);
    this.currentStage = idx;   // nextStage 会 +1
    this.totalScore = 0;
    this.coinsRun = 0;
    this.playerSnapshot = null;
    this._dailyPlane = null;
    ScoreSystem.setMult(1, 1);
    // 消耗品：临时护盾（本局开局生效一次）
    this._shieldPending = SaveSystem.useConsumable('shield_token');
    this._applyDifficultyScaling();
    Menu.hide();
    this.nextStage();
  },

  nextStage() {
    this.currentStage++;
    if (this.currentStage > WavesData.stages.length) {
      // 全通关：提交排行榜战绩
      SaveSystem.setClearedAll();
      this.lastRank = SaveSystem.submitLeaderboard({
        score: this.totalScore + ScoreSystem.score,
        kills: Stats.kills || 0,
        mode: 'stage',
        stage: 'ALL CLEAR',
        date: SaveSystem.todayStr(),
      });
      Achievements.checkAll();
      this.state = 'title';
      this._clearStage();
      Menu.showTitle();
      return;
    }
    Menu.hide();
    const key = WavesData.stages[this.currentStage - 1];
    this.stageKey = key;
    this._startStage(WavesData[key]);
  },

  // ===== 状态切换：无尽 =====
  startEndlessMode() {
    this.mode = 'endless';
    this.totalScore = 0;
    this.coinsRun = 0;
    this.playerSnapshot = null;
    this._dailyPlane = null;
    ScoreSystem.setMult(1, 1);
    // 消耗品：临时护盾（本局开局生效一次）
    this._shieldPending = SaveSystem.useConsumable('shield_token');
    SaveSystem.incEndlessPlayCount();
    Menu.hide();
    this._startEndless();
  },

  // ===== 每日挑战 =====
  // 由日期种子决定固定战机 + 随机词条（score2 得分x2 / coin2 金币x2 / bomb1 初始炸弹1）
  dailyConfig() {
    const date = SaveSystem.todayStr();
    let h = 0;
    for (let i = 0; i < date.length; i++) h = (h * 31 + date.charCodeAt(i)) >>> 0;
    const plane = Planes.allKeys[h % Planes.allKeys.length];
    const modPool = ['score2', 'coin2', 'bomb1'];
    const mods = [modPool[h % 3], modPool[(h >> 3) % 3]].filter((v, i, a) => a.indexOf(v) === i);
    return { date, plane, mods };
  },

  startDailyMode() {
    const cfg = this.dailyConfig();
    this.mode = 'daily';
    this.totalScore = 0;
    this.coinsRun = 0;
    this.playerSnapshot = null;
    this._dailyPlane = cfg.plane;
    // 词条倍率
    let mult = 1, coinMult = 1;
    for (const m of cfg.mods) {
      if (m === 'score2') mult *= 2;
      if (m === 'coin2') coinMult *= 2;
    }
    ScoreSystem.setMult(mult, coinMult);
    this._dailyMods = cfg.mods;
    // 消耗品：临时护盾（本局开局生效一次）
    this._shieldPending = SaveSystem.useConsumable('shield_token');
    Menu.hide();
    this._startEndless();
  },

  _startEndless() {
    this._clearStage();
    Background.init();
    PlayerBulletPool.clear();
    EnemyBulletPool.clear();
    ParticleSystem.clear();

    // 玩家：无尽模式从头开始（每日挑战用当日固定战机）
    const planeKey = this._dailyPlane || SaveSystem.getSelectedPlane();
    this.player = new Player(Balance.width / 2, Balance.height - 100, planeKey);
    if (Input._releaseControl) Input._releaseControl(); // 新局清理触控残留锁
    if (this._dailyMods && this._dailyMods.includes('bomb1')) {
      this.player.bombs = 1;
    }
    this.player.invincible = 1.5;

    this.enemies = [];
    this.boss = null;
    this.pickups = [];
    BossUI.clear();

    SpawnerEndless.start();
    ScoreSystem.reset();
    ScoreSystem.startStage(0); // 无尽无总敌人数
    ProgressSystem.startEndless();

    Stats.reset('endless');
    this._activeSpawner = SpawnerEndless;

    // 入场提示
    this.state = 'stage_intro';
    this._stageIntroTimer = 1.5;
    this._showStageIntro({
      stage: this.mode === 'daily' ? 'DAILY' : 'ENDLESS',
      background: this.mode === 'daily' ? '每日挑战' : 'NEON ABYSS',
    });
  },

  // ===== 通用：重启 / 返回 =====
  restart() {
    Menu.hide();
    if (this.mode === 'daily') {
      this.startDailyMode();  // 每日挑战重启保持当日配置
    } else if (this.mode === 'endless') {
      this._startEndless();
    } else if (this.stageData) {
      // 闯关：重新开始当前关（保持跨关继承快照）
      this._startStage(this.stageData);
    }
  },

  toTitle() {
    Menu.hide();
    this.state = 'title';
    this._clearStage();
    this.playerSnapshot = null;
    this.totalScore = 0;
    ProgressSystem.hide();
    Menu.showTitle();
  },

  resumeGame() {
    Menu.hide();
    this.state = 'play';
  },

  pauseGame() {
    if (this.state !== 'play') return;
    this.state = 'pause';
    Menu.showPause();
  },

  // ===== 关卡启动：闯关 =====
  _startStage(stageData) {
    this.stageData = stageData;
    this._clearStage();
    Background.init();
    PlayerBulletPool.clear();
    EnemyBulletPool.clear();
    ParticleSystem.clear();

    // 玩家：跨关继承
    const planeKey = SaveSystem.getSelectedPlane();
    this.player = new Player(Balance.width / 2, Balance.height - 100, planeKey);
    if (Input._releaseControl) Input._releaseControl(); // 新局清理触控残留锁
    if (this.playerSnapshot) {
      this.player.weapon = this.playerSnapshot.weapon;
      this.player.weapon.level = Math.max(1, this.player.weapon.level);
      this.player.bombs = this.playerSnapshot.bombs;
      this.player.hp = this.playerSnapshot.hp;
      // 僚机不继承
    }
    this.player.invincible = 1.5;

    this.enemies = [];
    this.boss = null;
    this.pickups = [];
    BossUI.clear();

    Spawner.start(stageData);
    ScoreSystem.reset();
    ScoreSystem.startStage(Spawner.getTotalEnemies());
    ProgressSystem.startStage(Spawner.getTotalEnemies());

    Stats.reset('stage');
    this._activeSpawner = Spawner;

    // 关卡入场提示
    this.state = 'stage_intro';
    this._stageIntroTimer = 1.5;
    this._showStageIntro(stageData);
  },

  _showStageIntro(stageData) {
    // 第 1 关显示移动端触控提示（检测触屏设备）
    let statsHtml = '';
    if (stageData.stage === 1) {
      const isTouch = (typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches)
        || ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
      if (isTouch) {
        statsHtml = `
          <div class="stat-line" style="margin:6px 0;padding:10px;background:rgba(0,240,255,0.08);border:1px solid rgba(0,240,255,0.3);border-radius:8px;text-align:center;">
            <span class="stat-label" style="display:block;font-size:13px;color:#00f0ff;margin-bottom:4px;">📱 移动端操作</span>
            <span class="stat-value" style="display:block;font-size:12px;line-height:1.7;opacity:.9;">
              按住屏幕拖动 = 移动飞机<br>
              手指不会挡住飞机（相对拖动）<br>
              右下按钮 = 炸弹 / 低速<br>
              自动开火，无需按键
            </span>
          </div>`;
      } else {
        statsHtml = `
          <div class="stat-line" style="margin:6px 0;padding:10px;background:rgba(0,240,255,0.06);border:1px solid rgba(0,240,255,0.2);border-radius:8px;text-align:center;">
            <span class="stat-label" style="display:block;font-size:12px;opacity:.8;">WASD/方向键 移动 · Shift 低速 · Z 炸弹 · Q 清屏 · X 投降 · Esc 暂停</span>
          </div>`;
      }
    }
    Menu.show(
      `STAGE ${stageData.stage}`,
      stageData.background.toUpperCase().replace('_', ' '),
      statsHtml,
      [{ label: 'GO', onClick: () => { Menu.hide(); this.state = 'play'; } }]
    );
  },

  _clearStage() {
    this.enemies = [];
    this.boss = null;
    this.pickups = [];
    PlayerBulletPool.clear();
    EnemyBulletPool.clear();
    ParticleSystem.clear();
    BossUI.clear();
    this._activeSpawner = null;
  },

  // ===== 难度递增（闯关重玩）=====
  _applyDifficultyScaling() {
    const sc = Balance.stageScaling;
    const clears = SaveSystem.getStagePlayCount();
    const hpMult = Math.min(sc.maxHpMult, 1 + clears * sc.hpPerClear);
    const speedMult = Math.min(sc.maxSpeedMult, 1 + clears * sc.speedPerClear);
    this._difficultyMult = { hp: hpMult, speed: speedMult };
  },

  // 应用到敌人（在 Enemy 构造后由 Spawner 调用本钩子）
  scaleEnemy(e) {
    if (this.mode !== 'stage') return;
    const cfg = Balance.enemy[e.type] || Balance.enemy.grunt;
    e.maxHp = Math.max(1, Math.round(cfg.hp * this._difficultyMult.hp));
    e.hp = e.maxHp;
    e.speed = cfg.speed * this._difficultyMult.speed;
  },

  // ===== Boss 生成 =====
  // 闯关：spawnBoss(bossKey) 从 BossesData 取
  // 无尽：spawnBoss(undefined, cfg, endlessKey) 使用克隆配置
  spawnBoss(bossKey, cfg, endlessKey) {
    let config;
    if (cfg) {
      config = cfg;
    } else {
      config = BossesData[bossKey];
      if (!config) return;
    }
    this.boss = new Boss(config);
    this.boss._endlessKey = endlessKey || bossKey;
    BossUI.setBoss(this.boss);
    Effects.triggerBossWarning(1.8);
    if (this.audio) this.audio.play('warning');
  },

  onBossDefeated(boss) {
    this.boss = null;
    BossUI.clear();
    EnemyBulletPool.clearAll();
    Stats.onBossKill();
    Achievements.checkAll();

    if (this.mode === 'endless') {
      // 无尽：Boss 死后继续，给奖励，清场敌弹
      ScoreSystem.addScore(5000);
      // Boss 金币奖励
      this.addCoins(Balance.coin.boss);
      // 掉落道具
      this._dropEndlessReward(boss);
      // 进度条重置（进入下一个循环）
      ProgressSystem.onBossDefeated();
      setTimeout(() => { ProgressSystem.percent = 0; }, 800);
      // 状态回到 play（不切结算）
      this.state = 'play';
      if (Game.particles) Game.particles.spawnText(Balance.width / 2, Balance.height / 2, 'BOSS DOWN!', '#ffaa00');
      return;
    }

    // 闯关：计算星级 + 结算
    const perfectBoss = boss.perfectStage && !this.player.tookDamageThisStage;
    const stars = ScoreSystem.computeStars(this.stageData, perfectBoss);
    this.totalScore += ScoreSystem.score;
    // Boss 击杀 + 通关金币奖励
    this.addCoins(Balance.coin.boss + Balance.coin.stageClearBonus);
    // 保存星级与最高分
    SaveSystem.setStageStars(this.stageKey, stars);
    SaveSystem.setStageBestScore(this.stageKey, ScoreSystem.score);
    // 解锁下一关
    const idx = WavesData.stages.indexOf(this.stageKey);
    if (idx >= 0 && idx + 1 < WavesData.stages.length) {
      SaveSystem.unlockStage(WavesData.stages[idx + 1]);
    }
    if (this.currentStage >= WavesData.stages.length) {
      SaveSystem.setClearedAll();
    }
    Achievements.checkAll();

    // 持久化玩家状态
    this.playerSnapshot = {
      weapon: this.player.weapon,
      bombs: this.player.bombs,
      hp: this.player.hp,
    };
    this.state = 'stage_clear';
    ProgressSystem.onBossDefeated();
    const self = this;
    setTimeout(() => {
      // 通关进入下一关：播放激昂胜利旋律
      if (self.audio) self.audio.play('victory_melody');
      // Boss 专属胜利语音（爷们牛逼 / 牛来 / 胆子真是肥嘟嘟的）
      if (self.audio) self.audio.bossVictory(boss);
      // 播放胜利 CG 动画，结束后显示结算
      Effects.playCG('victory', {
        playerColor: self.player.color,
        title: 'STAGE CLEAR',
        subtitle: `STAGE ${self.currentStage} PASSED`,
        onComplete: () => Menu.showStageClear(stars, self.totalScore),
      });
    }, 800);
  },

  _dropEndlessReward(boss) {
    // Boss 死亡位置掉落多个道具
    if (!Game.pickups) return;
    const drops = ['P', 'energy', 'bomb', 'shield'];
    for (let i = 0; i < drops.length; i++) {
      const p = new Pickup(boss.x + Utils.rndRange(-30, 30), boss.y + 20, drops[i]);
      p.vy = 80 + i * 20;
      Game.pickups.push(p);
    }
  },

  onPlayerDeath() {
    this.state = 'game_over';
    ProgressSystem.hide();
    // 本局统计同步
    Stats.update(0);
    Stats.end();
    Achievements.checkAll();

    const finalScore = this.totalScore + ScoreSystem.score;
    if (this.mode === 'endless') {
      // 保存无尽最高分
      SaveSystem.updateEndlessBest(
        finalScore,
        Stats.playTime,
        Stats.kills,
        Stats.wave
      );
      Achievements.checkAll();
    }
    // 每日挑战：更新当日最高分
    if (this.mode === 'daily') {
      this._dailyNewRecord = SaveSystem.updateDailyBest(finalScore);
      Achievements.checkAll();
    }
    // 排行榜：提交本局战绩
    this.lastRank = SaveSystem.submitLeaderboard({
      score: finalScore,
      kills: Stats.kills || 0,
      mode: this.mode,
      stage: this.mode === 'stage' ? (this.stageKey || '') : (Stats.wave ? 'W' + Stats.wave : ''),
      date: SaveSystem.todayStr(),
    });
    // 播放失败 CG 动画，结束后显示结算
    const self = this;
    Effects.playCG('defeat', {
      playerColor: this.player ? this.player.color : '#00f0ff',
      title: 'GAME OVER',
      subtitle: this.mode === 'daily' ? 'DAILY FAILED'
        : this.mode === 'endless' ? 'ENDLESS FAILED' : 'STAGE FAILED',
      onComplete: () => Menu.showGameOver(),
    });
  },

  // ===== 工具：寻找最近敌人（homing 用） =====
  findNearestEnemy(x, y, maxRange = 600) {
    let nearest = null;
    let minD = maxRange * maxRange;
    for (let i = 0; i < this.enemies.length; i++) {
      const e = this.enemies[i];
      if (!e.alive) continue;
      const d = Utils.dist2(x, y, e.x, e.y);
      if (d < minD) { minD = d; nearest = e; }
    }
    if (this.boss && this.boss.alive && this.boss.state === 'fight') {
      // 优先 Boss 核心
      const d = Utils.dist2(x, y, this.boss.x, this.boss.y);
      if (d < minD) { minD = d; nearest = this.boss; }
    }
    return nearest;
  },

  // ===== 主更新 =====
  update(dt) {
    Input.update();
    Achievements.update(dt);

    // 暂停切换
    if (Input.actions.pause) {
      if (this.state === 'play') this.pauseGame();
      else if (this.state === 'pause') this.resumeGame();
    }

    if (this.state === 'stage_intro') {
      this._stageIntroTimer -= dt;
      Background.update(dt);
      Effects.update(dt);
      if (this._stageIntroTimer <= 0) {
        Menu.hide();
        this.state = 'play';
      }
      Input.clearFrameActions();
      return;
    }

    if (this.state !== 'play') {
      // 暂停/结算时仍渲染但不更新实体
      Background.update(dt);
      Effects.update(dt);
      Input.clearFrameActions();
      return;
    }

    // ===== play 状态 =====
    Background.update(dt);
    Effects.update(dt);
    BossUI.update(dt);
    Stats.update(dt);

    // 玩家死亡倒计时处理（避免 setTimeout 跨重启污染）
    if (this.player && !this.player.alive && this.player.deathTimer !== undefined && this.player.deathTimer !== null) {
      this.player.deathTimer -= dt;
      if (this.player.deathTimer <= 0) {
        this.player.deathTimer = null;
        this.onPlayerDeath();
        Input.clearFrameActions();
        return;
      }
    }

    // 玩家
    if (this.player) this.player.update(dt);

    // 敌人
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      e.update(dt);
      if (e.dead) this.enemies.splice(i, 1);
    }

    // Boss
    if (this.boss) this.boss.update(dt);
    if (this.boss && this.boss.dead) {
      // 死亡动画在 Boss._die 中处理，最终 onBossDefeated 触发
    }

    // 道具
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const pk = this.pickups[i];
      pk.update(dt);
      if (pk.dead) this.pickups.splice(i, 1);
    }

    // 子弹
    PlayerBulletPool.update(dt);
    EnemyBulletPool.update(dt);

    // 粒子
    ParticleSystem.update(dt);

    // 分数系统
    ScoreSystem.update(dt);
    // 同步分数与连击到统计（stage 模式累加跨关 totalScore）
    Stats.score = (this.totalScore || 0) + ScoreSystem.score;
    Stats.onCombo(ScoreSystem.combo);

    // 生成器（根据模式）
    if (this._activeSpawner) this._activeSpawner.update(dt);

    // 进度条更新
    ProgressSystem.update(dt);

    // 碰撞
    Collision.detect();

    // 清空瞬时输入
    Input.clearFrameActions();
  },

  // 主绘制
  draw(time) {
    Renderer.draw(time);
  },
};

/* main.js */
// ====== src/main.js ======
// 入口：初始化 + 主循环（固定逻辑步长 + 插值渲染）

(function() {
  const canvas = document.getElementById('game');
  Game.init(canvas);

  // 主循环
  let lastTime = performance.now();
  let accumulator = 0;
  const STEP = Balance.dt;       // 1/60
  const MAX_FRAME = 0.25;        // 最大单帧时间，防止暂停后跳变

  function frame(now) {
    try {
      let dt = (now - lastTime) / 1000;
      lastTime = now;
      if (dt > MAX_FRAME) dt = MAX_FRAME;

      // 固定步长更新
      accumulator += dt;
      while (accumulator >= STEP) {
        Game.update(STEP);
        accumulator -= STEP;
      }

      // 渲染
      const time = now / 1000;
      Game.draw(time);
    } catch (e) {
      // 捕获 rAF 回调里的异常并暴露，便于诊断
      window.__gameError = (window.__gameError || '') + '\n[' + new Date().toISOString() + '] ' + (e && e.stack ? e.stack : String(e));
      console.error('[Game loop]', e);
    }
    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);

  // 调试入口：暴露 Game
  if (Balance.debug) window.__game = Game;
})();
